const fs = require('fs');
const path = require('path');

const analisesDir = __dirname;
const files = fs.readdirSync(analisesDir).filter(f => f.endsWith('.har'));

console.log('Arquivos HAR em analises/:', files);

const allEndpoints = new Map();

for (const f of files) {
  const harPath = path.join(analisesDir, f);
  const sizeMB = (fs.statSync(harPath).size / (1024 * 1024)).toFixed(2);
  console.log(`\n========================================`);
  console.log(`Analisando ${f} (${sizeMB} MB)...`);
  try {
    const raw = fs.readFileSync(harPath, 'utf-8');
    const data = JSON.parse(raw);
    const entries = data.log?.entries || [];
    console.log(`Total de entradas HTTP: ${entries.length}`);

    const fileEndpoints = new Set();

    for (const e of entries) {
      const req = e.request || {};
      const res = e.response || {};
      const urlStr = req.url || '';

      if (urlStr.includes('/api/')) {
        try {
          const parsed = new URL(urlStr);
          fileEndpoints.add(`${req.method} ${parsed.pathname}`);

          if (!allEndpoints.has(parsed.pathname)) {
            allEndpoints.set(parsed.pathname, {
              methods: new Set(),
              sampleQueries: new Set(),
              sources: new Set(),
              sampleResponses: []
            });
          }
          const epInfo = allEndpoints.get(parsed.pathname);
          epInfo.methods.add(req.method);
          if (parsed.search) epInfo.sampleQueries.add(parsed.search);
          epInfo.sources.add(f);

          // Se tiver body de resposta e ainda não pegamos amostra
          if (res.content?.text && epInfo.sampleResponses.length < 1) {
            try {
              let text = res.content.text;
              if (res.content.encoding === 'base64') {
                text = Buffer.from(text, 'base64').toString('utf-8');
              }
              const json = JSON.parse(text);
              epInfo.sampleResponses.push({
                query: parsed.search,
                keys: Array.isArray(json) ? (json[0] ? Object.keys(json[0]) : 'empty array') : Object.keys(json),
                sampleData: Array.isArray(json) ? json.slice(0, 2) : json
              });
            } catch (err) {
              // não é json válido
            }
          }
        } catch (e) {}
      }
    }

    console.log(`Endpoints encontrados neste arquivo:`);
    for (const ep of fileEndpoints) {
      console.log(`  - ${ep}`);
    }

  } catch (err) {
    console.error(`Erro ao processar ${f}:`, err.message);
  }
}

console.log(`\n========================================`);
console.log(`RESUMO GERAL DE ENDPOINTS:`);
for (const [pathname, info] of allEndpoints.entries()) {
  console.log(`\nEndpoint: [${Array.from(info.methods).join(', ')}] ${pathname}`);
  console.log(`  Fontes: ${Array.from(info.sources).join(', ')}`);
  console.log(`  Exemplos de Query: ${Array.from(info.sampleQueries).slice(0, 5).join(' | ')}`);
  if (info.sampleResponses.length > 0) {
    console.log(`  Estrutura da Resposta:`, info.sampleResponses[0].keys);
  }
}

fs.writeFileSync(path.join(analisesDir, 'endpoints_descobertos.json'), JSON.stringify(
  Array.from(allEndpoints.entries()).map(([path, info]) => ({
    endpoint: path,
    methods: Array.from(info.methods),
    sources: Array.from(info.sources),
    queries: Array.from(info.sampleQueries),
    sample: info.sampleResponses[0] || null
  })), null, 2
));
console.log('\nSalvo em analises/endpoints_descobertos.json');

const fs = require('fs');
