      headers: req.headers?.filter(h => ['authorization', 'cookie', 'content-type'].includes(h.name.toLowerCase())),
      status: res.status
    });
  }

  if (url.includes('/api/')) {
    const parsed = new URL(url);
    const key = `${req.method} ${parsed.pathname}`;
    if (!endpoints.has(key)) {
      endpoints.set(key, {
        method: req.method,
        pathname: parsed.pathname,
        queries: new Set(),
        responseSample: null
      });
    }
    const item = endpoints.get(key);
    if (parsed.search) item.queries.add(parsed.search);

    if (!item.responseSample && res.content?.text) {
      try {
        let text = res.content.text;
        if (res.content.encoding === 'base64') {
          text = Buffer.from(text, 'base64').toString('utf-8');
        }
        item.responseSample = JSON.parse(text);
      } catch (err) {}
    }
  }
}

