const axios = require('axios');
const https = require('https');
const fs = require('fs');
const path = require('path');

const CEVEN_BASE = 'https://ceven.drivetriunfante-locomotiva.com.br';
const agent = new https.Agent({ rejectUnauthorized: false });

const GERENTES = [
  { nome: 'Diego', filial: 'tbe1', sigla: 'TBE' },
  { nome: 'Saldanha', filial: 'tsj1', sigla: 'TSJ' },
  { nome: 'Adriano', filial: 'mcd1', sigla: 'MCD', altFiliais: ['mcd2'] },
  { nome: 'Cleverson', filial: 'mcd1', sigla: 'MCD' },
  { nome: 'Vagner', filial: 'tph1', sigla: 'TPH' },
  // Bertoni desativado, ignorado
  { nome: 'Danilo', filial: 'tcg1', sigla: 'TCG' },
  { nome: 'Leandro Souza', filial: 'tpa1', sigla: 'TPA', altNomes: ['Leandro'], altFiliais: ['tpa2'] },
  { nome: 'Christian Radke', filial: 'tpa1', sigla: 'TPA', altNomes: ['Radke'], altFiliais: ['tpa2'] },
  { nome: 'Fabio Colares', filial: 'api1', sigla: 'API', altNomes: ['Fabio', 'Colares'] },
  { nome: 'Marcelo', filial: 'api1', sigla: 'API' },
  { nome: 'Leonardo', filial: 'tcv1', sigla: 'TCV' },
  { nome: 'Marcos Colling', filial: 'abc1', sigla: 'ABC', altNomes: ['Marcos'] },
  { nome: 'Becher', filial: 'tca1', sigla: 'TCA' },
  { nome: 'Fabio Machado', filial: 'tbl1', sigla: 'TBL', altNomes: ['Fabio'] }
];

async function testLogin(nome, filial, password = 'abc123') {
  try {
    const res = await axios.post(`${CEVEN_BASE}/api/gerente-auth/login`, {
      filial,
      nome,
      password
    }, {
      headers: {
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64)',
        'Content-Type': 'application/json',
        'Referer': `${CEVEN_BASE}/gerente/login`
      },
      httpsAgent: agent,
      timeout: 10000
    });
    return res.data;
  } catch (err) {
    return { error: err.response?.data || err.message, status: err.response?.status };
  }
}

async function run() {
  console.log('Iniciando testes de login dos gerentes...\n');
  const results = [];

  for (const g of GERENTES) {
    let loginSuccess = null;
    let usedNome = g.nome;
    let usedFilial = g.filial;

    // Tentativa com nome principal
    console.log(`Tentando login: [${g.sigla}] ${g.nome} em ${g.filial}...`);
    let res = await testLogin(g.nome, g.filial);

    if (res && res.access_token) {
      loginSuccess = res;
    } else {
      // Tenta nomes alternativos ou filiais alternativas
      const nomes = [g.nome, ...(g.altNomes || [])];
      const filiais = [g.filial, ...(g.altFiliais || [])];

      for (const f of filiais) {
        for (const n of nomes) {
          if (f === g.filial && n === g.nome) continue;
          console.log(`  Tentando variante: ${n} em ${f}...`);
          const r = await testLogin(n, f);
          if (r && r.access_token) {
            loginSuccess = r;
            usedNome = n;
            usedFilial = f;
            break;
          }
        }
        if (loginSuccess) break;
      }
    }

    if (loginSuccess) {
      console.log(`  ✅ SUCESSO! Logado como "${usedNome}" em ${usedFilial}`);
      results.push({
        gerenteOriginal: g.nome,
        nomeAutenticado: usedNome,
        sigla: g.sigla,
        filialKey: usedFilial,
        token: loginSuccess.access_token,
        user: loginSuccess.user
      });
    } else {
      console.log(`  ❌ FALHA ao logar ${g.nome} em ${g.sigla}:`, res.error || res);
      results.push({
        gerenteOriginal: g.nome,
        sigla: g.sigla,
        falha: true,
        detalhe: res
      });
    }
  }

  fs.writeFileSync(path.join(__dirname, 'resultado_logins_gerentes.json'), JSON.stringify(results, null, 2));
  console.log('\nResultados salvos em analises/resultado_logins_gerentes.json');
}

run();

