const axios = require('axios');
const https = require('https');
const agent = new https.Agent({ rejectUnauthorized: false });

async function check() {
  try {
    const res = await axios.get('https://ceven.drivetriunfante-locomotiva.com.br/gerente/login', {
      httpsAgent: agent,
      headers: { 'User-Agent': 'Mozilla/5.0' }
    });
    console.log('HTML size:', res.data.length);
    // Procurar por scripts
    const scriptRegex = /<script[^>]+src=["']([^"']+)["']/g;
    let match;
    const scripts = [];
    while ((match = scriptRegex.exec(res.data)) !== null) {
      scripts.push(match[1]);
    }
    console.log('Scripts:', scripts);

    // Baixar os scripts e procurar a lista de gerentes
    for (const s of scripts) {
      const url = s.startsWith('http') ? s : `https://ceven.drivetriunfante-locomotiva.com.br${s}`;
      console.log('Baixando script:', url);
      const sRes = await axios.get(url, { httpsAgent: agent });
      const js = sRes.data;
      if (typeof js === 'string' && js.includes('Saldanha')) {
        console.log(`Encontrado "Saldanha" em ${s}!`);
        // Procurar trecho de código ao redor
        const idx = js.indexOf('Saldanha');
        console.log('Trecho:', js.slice(Math.max(0, idx - 200), Math.min(js.length, idx + 400)));
      }
    }
  } catch (err) {
    console.error('Erro:', err.message);
  }
}

check();

