const axios = require('axios');
const https = require('https');
const fs = require('fs');
const path = require('path');
const XLSX = require('xlsx');

const CEVEN_BASE = 'https://ceven.drivetriunfante-locomotiva.com.br';
const agent = new https.Agent({ rejectUnauthorized: false });

const FILIAIS_CONFIG = [
  { sigla: 'TBE', key: 'tbe1', nome: 'Três Lagoas BE', gerentes: [{ nome: 'Diego', pass: 'abc123' }] },
  { sigla: 'TSJ', key: 'tsj1', nome: 'São José', gerentes: [{ nome: 'Saldanha', pass: 'abc123' }] },
  { sigla: 'MCD', key: 'mcd1', nome: 'Maracaju', gerentes: [{ nome: 'Adriano', pass: 'abc123' }, { nome: 'Cleverson', pass: 'abc123' }] },
  { sigla: 'TPH', key: 'tph1', nome: 'Três Lagoas PH', gerentes: [{ nome: 'Vagner', pass: 'abc123' }] }, // Bertoni desativado
  { sigla: 'TCG', key: 'tcg1', nome: 'Campo Grande', gerentes: [{ nome: 'Danilo', pass: 'abc123' }] },
  { sigla: 'TPA', key: 'tpa1', nome: 'Pontes e Lacerda', gerentes: [{ nome: 'Leandro Souza', pass: 'abc123' }, { nome: 'Christian Radke', pass: 'abc123' }] },
  { sigla: 'API', key: 'api1', nome: 'Aparecida', gerentes: [{ nome: 'Fabio Colares', pass: 'abc123' }, { nome: 'Marcelo', pass: 'abc123' }] },
  { sigla: 'TCV', key: 'tcv1', nome: 'Três Lagoas CV', gerentes: [{ nome: 'Leonardo', pass: 'abc123' }] },
  { sigla: 'ABC', key: 'abc1', nome: 'ABC', gerentes: [{ nome: 'Marcos Colling', pass: 'abc123' }] },
  { sigla: 'TCA', key: 'tca1', nome: 'Tangará da Serra', gerentes: [{ nome: 'Becher', pass: 'abc123' }] },
  { sigla: 'TBL', key: 'tbl1', nome: 'Três Lagoas TBL', gerentes: [{ nome: 'Fabio Machado', pass: '123456', altPass: 'abc123' }] }
];

async function loginGerente(filialKey, nome, password, altPass) {
  const passwordsToTry = [password];
  if (altPass) passwordsToTry.push(altPass);

  for (const pw of passwordsToTry) {
    try {
      const res = await axios.post(`${CEVEN_BASE}/api/gerente-auth/login`, {
        filial: filialKey,
        nome,
        password: pw
      }, {
        headers: { 'Content-Type': 'application/json' },
        httpsAgent: agent,
        timeout: 8000
      });
      if (res.data?.access_token) {
        return { token: res.data.access_token, nome, pw };
      }
    } catch (e) {
      // continua para a próxima senha
    }
  }
  return null;
}

async function fetchHierarquia() {
  console.log('=== EXTRAINDO HIERARQUIA COMPLETA DE TODAS AS 11 FILIAIS DO CEVEN ===\n');

  const dadosConsolidados = [];
  const resumoFiliais = [];
  const tabelaLinhas = [];

  for (const fil of FILIAIS_CONFIG) {
    console.log(`\n🏢 Processando Filial: ${fil.sigla} (${fil.nome}) [${fil.key}]...`);

    let token = null;
    let gerenteAutenticado = null;
    const gerentesNomes = fil.gerentes.map(g => g.nome).join(', ');

    for (const g of fil.gerentes) {
      const auth = await loginGerente(fil.key, g.nome, g.pass, g.altPass);
      if (auth) {
        token = auth.token;
        gerenteAutenticado = auth.nome;
        console.log(`  🔑 Autenticado com sucesso pelo gerente: ${auth.nome}`);
        break;
      }
    }

    if (!token) {
      console.error(`  ❌ Falha de login para a filial ${fil.sigla}!`);
      continue;
    }

    // 1. Buscar lista de supervisores oficiais
    let supervisores = [];
    try {
      const supRes = await axios.get(`${CEVEN_BASE}/api/gerente/supervisores?filial=${fil.key}`, {
        headers: { 'Authorization': `Bearer ${token}` },
        httpsAgent: agent,
        timeout: 10000
      });
      supervisores = supRes.data || [];
      console.log(`  👥 Total de Supervisores encontrados: ${supervisores.length}`);
    } catch (e) {
      console.error(`  ⚠️ Erro ao buscar supervisores de ${fil.sigla}:`, e.message);
    }

    // 2. Para cada supervisor, buscar seus RCAs vinculados
    const filialEstrutura = {
      filialSigla: fil.sigla,
      filialKey: fil.key,
      filialNome: fil.nome,
      gerentesCadastrados: gerentesNomes,
      gerenteAtivoLogin: gerenteAutenticado,
      totalSupervisores: supervisores.length,
      supervisores: []
    };

    let totalRcasFilial = 0;

    for (const sup of supervisores) {
      let rcas = [];
      try {
        const rcaRes = await axios.get(`${CEVEN_BASE}/api/gerente/supervisor/rcas?filial=${fil.key}&supervisorId=${sup.id}`, {
          headers: { 'Authorization': `Bearer ${token}` },
          httpsAgent: agent,
          timeout: 10000
        });
        rcas = rcaRes.data || [];
      } catch (e) {
