args.CodeContent:
const fs = require('fs');
const path = require('path');
const readline = require('readline');
const XLSX = require('xlsx');

const csvPath = path.join(__dirname, 'clientes_rf_2026-09-12 (1).csv');

async function profileCsv() {
  console.log('=== INICIANDO MAPEAMENTO COMPLETO DE CLIENTES RF ===');
  console.log(`Lendo arquivo: ${csvPath}...`);

  const fileStream = fs.createReadStream(csvPath, { encoding: 'utf-8' });
  const rl = readline.createInterface({
    input: fileStream,
    crlfDelay: Infinity
  });

  let totalLines = 0;
  let header = [];
  const colStats = [];

  for await (const line of rl) {
    totalLines++;
    if (totalLines === 1) {
      header = line.split(';').map((h, idx) => h.trim() || `col_${idx}`);
      for (let i = 0; i < header.length; i++) {
        colStats.push({
          index: i + 1,
          name: header[i],
          totalCount: 0,
          filledCount: 0,
          emptyCount: 0,
          valueFrequency: new Map(),
          typesDetected: new Set(),
          sampleValues: new Set(),
          minLength: Infinity,
          maxLength: 0,
          numericMin: Infinity,
          numericMax: -Infinity,
          numericSum: 0,
          numericCount: 0
        });
      }
      continue;
    }

    const cols = line.split(';');

    for (let i = 0; i < header.length; i++) {
      const stat = colStats[i];
      stat.totalCount++;
      const val = cols[i] !== undefined ? cols[i].trim() : '';

      if (val === '') {
        stat.emptyCount++;
      } else {
        stat.filledCount++;
        stat.minLength = Math.min(stat.minLength, val.length);
        stat.maxLength = Math.max(stat.maxLength, val.length);

        if (stat.sampleValues.size < 5) {
          stat.sampleValues.add(val);
        }

        // Frequência dos top valores (limite de 1000 chaves para memória)
        if (stat.valueFrequency.size < 5000) {
          stat.valueFrequency.set(val, (stat.valueFrequency.get(val) || 0) + 1);
        }

        // Detecção de tipo de dado
        // 1. Numérico
        const cleanNum = val.replace(/\./g, '').replace(',', '.');
        const numVal = parseFloat(cleanNum);
        if (!isNaN(numVal) && !isNaN(val) && !val.includes('/') && !val.includes('-')) {
          stat.typesDetected.add('NUMERIC');
          stat.numericCount++;
          stat.numericMin = Math.min(stat.numericMin, numVal);
          stat.numericMax = Math.max(stat.numericMax, numVal);
          stat.numericSum += numVal;
        } else if (val.match(/^\d{2}\/\d{2}\/\d{4}/) || val.match(/^\d{4}-\d{2}-\d{2}/)) {
          stat.typesDetected.add('DATE');
        } else if (val.toUpperCase() === 'ATIVO' || val.toUpperCase() === 'INATIVO' || val.toUpperCase() === 'SIM' || val.toUpperCase() === 'NAO') {
          stat.typesDetected.add('STATUS/BOOLEAN');
        } else if (val.match(/^\d{2}\.\d{3}\.\d{3}\/\d{4}-\d{2}$/)) {
          stat.typesDetected.add('CNPJ');
        } else if (val.match(/^\d{5}-\d{3}$/)) {
          stat.typesDetected.add('CEP');
        } else if (val.includes('@')) {
          stat.typesDetected.add('EMAIL');
        } else if (val.startsWith('-') && (val.includes('.') || val.length > 5)) {
          stat.typesDetected.add('COORDINATE');
        } else {
          stat.typesDetected.add('STRING');
        }
      }
    }

    if ((totalLines - 1) % 10000 === 0) {
      console.log(`  Processadas ${(totalLines - 1).toLocaleString()} linhas...`);
    }
  }

  const dataRowsCount = totalLines - 1;
  console.log(`\nProcessamento finalizado: ${dataRowsCount.toLocaleString()} registros analisados.`);

  // Descrições de negócio para cada coluna conhecida do CEVEN / RF
  const descricoesNegocio = {
    'sem_roteiro': 'Indicador se o cliente está fora da rota ativa de visitas regulares do RCA',
    'filial': 'Código oficial da filial proprietária da conta do cliente no CEVEN (ex: ABC1, TCV1)',
    'status': 'Status comercial do cliente no ERP/Winthor (ATIVO / INATIVO)',
    'cod': 'Código interno do cliente no Winthor (CodCli)',
    'cnpj': 'CNPJ formatado do cliente (Receita Federal)',
    'nome': 'Nome fantasia comercial do cliente no ERP',
    'razao': 'Razão social oficial registrada no CNPJ',
    'endereco': 'Logradouro e número do estabelecimento',
    'cep': 'Código de Endereçamento Postal',
    'cidade': 'Município de localização da empresa',
    'uf': 'Unidade Federativa (Estado)',
    'pop_mun': 'População estimada do município (IBGE)',
    'pib_pc': 'PIB per capita do município',
    'telefone': 'Telefone cadastrado no ERP / CEVEN',
    'contato': 'Nome do comprador / responsável no PDV',
    'email': 'E-mail cadastrado no ERP / CEVEN',
    'data_ult': 'Data da última compra faturada pelo cliente',
    'vlr_ult': 'Valor em R$ da última compra realizada',
    'vlr_max': 'Maior valor histórico de compra do cliente em um único pedido',
    'limite': 'Limite de crédito concedido ao cliente no Winthor',
    'prazo': 'Condição padrão de pagamento acordada (em dias)',
    'atividade': 'Ramo de atividade comercial classificado no Winthor (ex: A69, A35, A07)',
    'dt_abertura': 'Data em que o cliente foi cadastrado no Winthor/ERP',
    'obs': 'Observações comerciais de faturamento/entrega',
    'tipo': 'Tipo de rota ou geolocalização (ex: Normal, GEO compartilhada, etc.)',
    'filiais_cnpj': 'Histórico de filiais do grupo onde este mesmo CNPJ possui cadastro/compras',
    'situacao_cnpj': 'Situação cadastral na Receita Federal (ex: ATIVA, BAIXADA, SUSPENSA)',
    'cnae_principal': 'Código CNAE de atividade primária na Receita Federal',
    'cnaes_secundarios': 'Lista de CNAEs de atividades secundárias',
    'capital_social': 'Capital social registrado da empresa na Receita Federal (em R$)',
    'natureza_jur': 'Código e descrição da Natureza Jurídica (ex: Sociedade Empresária Limitada)',
    'socios': 'Quadro de Sócios e Administradores (QSA) obtido na Receita Federal',
    'rf_abertura': 'Data oficial de abertura da empresa na Receita Federal',
    'rf_telefone': 'Telefone registrado na base da Receita Federal',
    'rf_email': 'E-mail registrado na base da Receita Federal',
    'lat': 'Latitude geográfica do PDV',
    'lon': 'Longitude geográfica do PDV'
  };

  // Montar relatório analítico estruturado
  const relatorioColunas = [];
  const tabelaMarkdownLinhas = [];

  for (const s of colStats) {
    const preenchimentoPct = ((s.filledCount / dataRowsCount) * 100).toFixed(1);
    const vaziosPct = ((s.emptyCount / dataRowsCount) * 100).toFixed(1);
    const tipos = Array.from(s.typesDetected).join(', ') || 'TEXT';

    // Top 3 valores mais frequentes
    const sortedFreq = Array.from(s.valueFrequency.entries())
      .sort((a, b) => b[1] - a[1])
      .slice(0, 3);
    const topValoresStr = sortedFreq.map(([k, v]) => `"${k}" (${v})`).join('; ');

    const desc = descricoesNegocio[s.name] || 'Campo do cadastro de clientes / enriquecimento RF';

    relatorioColunas.push({
      indice: s.index,
      coluna: s.name,
      descricao: desc,
      tipoPredominante: tipos,
      preenchidos: s.filledCount,
      preenchidosPct: `${preenchimentoPct}%`,
      vazios: s.emptyCount,
      vaziosPct: `${vaziosPct}%`,
      tamanhoMin: s.minLength === Infinity ? 0 : s.minLength,
      tamanhoMax: s.maxLength,
      amostras: Array.from(s.sampleValues).slice(0, 3),
      topValoresFrequentes: sortedFreq
    });

    tabelaMarkdownLinhas.push({
      n: s.index,
      nome: `\`${s.name}\``,
      tipo: tipos,
      preenchimento: `${preenchimentoPct}% (${s.filledCount.toLocaleString()})`,
      amostras: Array.from(s.sampleValues).slice(0, 2).map(v => v.slice(0, 25)).join(' | ') || '-',
      descricao: desc
    });
  }

  // 1. Salvar JSON estruturado
  const jsonPath = path.join(__dirname, 'perfil_clientes_rf.json');
  fs.writeFileSync(jsonPath, JSON.stringify({
    arquivo: 'clientes_rf_2026-09-12 (1).csv',
    totalRegistros: dataRowsCount,
    totalColunas: header.length,
    geradoEm: new Date().toISOString(),
    colunas: relatorioColunas
  }, null, 2), 'utf-8');
  console.log(`💾 Salvo JSON de mapeamento em: ${jsonPath}`);

  // 2. Salvar Dicionário em Excel (.xlsx)
  const wb = XLSX.utils.book_new();
  const wsDicionario = XLSX.utils.json_to_sheet(relatorioColunas.map(c => ({
    'Ordem': c.indice,
    'Nome Coluna': c.coluna,
    'Descrição de Negócio': c.descricao,
    'Tipos de Dados Detectados': c.tipoPredominante,
    'Registros Preenchidos': c.preenchidos,
    '% Preenchimento': c.preenchidosPct,
    'Registros Vazios': c.vazios,
    '% Vazios': c.vaziosPct,
    'Tamanho Mínimo': c.tamanhoMin,
    'Tamanho Máximo': c.tamanhoMax,
    'Exemplos de Valores': c.amostras.join(' | ')
  })));
  XLSX.utils.book_append_sheet(wb, wsDicionario, 'Dicionario_Colunas');
  const xlsxPath = path.join(__dirname, 'dicionario_clientes_rf.xlsx');
  XLSX.writeFile(wb, xlsxPath);
  console.log(`📊 Salvo Excel do dicionário em: ${xlsxPath}`);

  // 3. Salvar Markdown Rico
  let md = `# 📖 Dicionário e Mapeamento de Dados: \`clientes_rf_2026-09-12 (1).csv\`\n\n`;
  md += `> **Data da Análise:** ${new Date().toISOString().slice(0, 10)}\n`;
  md += `> **Total de Registros:** **${dataRowsCount.toLocaleString()}** clientes\n`;
  md += `> **Total de Colunas:** **${header.length}** atributos mapeados\n`;
  md += `> **Separador:** Ponto e vírgula (\`;\`)\n\n`;

  md += `## 📌 Sumário Executivo do Dataset\n`;
  md += `Esta base consolida o cadastro comercial do Winthor/CEVEN enriquecido com dados oficiais da **Receita Federal** (RF), georreferenciamento e indicadores socioeconômicos dos municípios.\n\n`;

  md += `## 📋 Tabela Completa de Colunas e Tipagem\n\n`;
  md += `| # | Coluna | Tipo de Dado | Preenchimento | Amostra de Dados | Descrição de Negócio |\n`;
  md += `| :-: | :--- | :--- | :-: | :--- | :--- |\n`;

  for (const row of tabelaMarkdownLinhas) {
    md += `| ${row.n} | ${row.nome} | \`${row.tipo}\` | **${row.preenchimento}** | ${row.amostras} | ${row.descricao} |\n`;
  }

  md += `\n---\n\n## 🔍 Análise Granular por Grupos de Informação\n\n`;

  md += `### 1. Dados de Identificação Comercial (Winthor / CEVEN)\n`;
  md += `- **\`filial\` (Col 2):** 100% preenchida. 11 filiais oficiais cadastradas (\`API1\`, \`TCA1\`, \`TBL1\`, \`TPA1\`, \`TCV1\`, \`TSJ1\`, \`TCG1\`, \`TPH1\`, \`TBE1\`, \`ABC1\`, \`MCD1\`).\n`;
  md += `- **\`status\` (Col 3):** Classificação do cliente em **ATIVO** ou **INATIVO**.\n`;
  md += `- **\`cnpj\` (Col 5):** Chave unívoca nacional do cliente comercial.\n`;
  md += `- **\`nome\` & \`razao\` (Cols 6-7):** Nome fantasia e razão social para busca textual e correspondência.\n`;
  md += `- **\`sem_roteiro\` (Col 1):** Flag que indica clientes cadastrados que não estão na escala diária de visitas de nenhum vendedor.\n\n`;

  md += `### 2. Histórico Transacional e Financeiro\n`;
  md += `- **\`data_ult\` (Col 17) & \`vlr_ult\` (Col 18):** Recência e valor da última compra realizada.\n`;
  md += `- **\`vlr_max\` (Col 19):** Potencial máximo demonstrado em pedido único.\n`;
  md += `- **\`limite\` (Col 20) & \`prazo\` (Col 21):** Capacidade de crédito e prazos comerciais liberados.\n`;
  md += `- **\`atividade\` (Col 22):** Segmentação comercial de canal (ex: A07, A13, A35, A69).\n\n`;

  md += `### 3. Enriquecimento da Receita Federal (RF) e Inteligência\n`;
  md += `- **\`situacao_cnpj\` (Col 27):** Situação cadastral na RF (ATIVA, BAIXADA, SUSPENSA).\n`;
  md += `- **\`cnae_principal\` (Col 28) & \`cnaes_secundarios\` (Col 29):** Códigos oficiais de atividade econômica.\n`;
  md += `- **\`capital_social\` (Col 30):** Porte e robustez do patrimônio registrado.\n`;
  md += `- **\`socios\` (Col 32):** Quadro societário para cruzamentos de sócios e redes de lojas.\n`;
  md += `- **\`rf_telefone\` / \`rf_email\` (Cols 34-35):** Contatos oficiais cadastrados na RF para enriquecimento cadastral.\n\n`;

  md += `### 4. Geolocalização e Demografia\n`;
  md += `- **\`lat\` (Col 36) & \`lon\` (Col 37):** Coordenadas geográficas para mapas de calor, raio de visitação e roteirização.\n`;
  md += `- **\`pop_mun\` (Col 12) & \`pib_pc\` (Col 13):** Potencial de consumo do município onde o cliente está instalado.\n`;

  const mdPath = path.join(__dirname, 'DICIONARIO_DE_DADOS_CLIENTES_RF.md');
  fs.writeFileSync(mdPath, md, 'utf-8');
  console.log(`📝 Salvo Markdown do Dicionário em: ${mdPath}`);

  console.log('\n🎉 MAPEAMENTO COMPLETO CONCLUÍDO COM SUCESSO!');
}

