args.CodeContent:
const axios = require('axios');
const https = require('https');
const fs = require('fs');
const path = require('path');
const Database = require('better-sqlite3');

const CEVEN_BASE = 'https://ceven.drivetriunfante-locomotiva.com.br';
const agent = new https.Agent({ rejectUnauthorized: false, keepAlive: true });

const dbPath = path.join(__dirname, 'pedidos_historico_ceven.db');
const db = new Database(dbPath);
db.pragma('journal_mode = WAL');
db.pragma('synchronous = NORMAL');

// 1. Criar Tabelas
db.exec(`
  CREATE TABLE IF NOT EXISTS filiais (
    codigo TEXT PRIMARY KEY,
    sigla TEXT,
    gerente TEXT
  );

  CREATE TABLE IF NOT EXISTS supervisores (
    id INTEGER,
    nome TEXT,
    filial_codigo TEXT,
    PRIMARY KEY (id, filial_codigo)
  );

  CREATE TABLE IF NOT EXISTS vendedores (
    id INTEGER,
    nome TEXT,
    supervisor_id INTEGER,
    filial_codigo TEXT,
    PRIMARY KEY (id, filial_codigo)
  );

  CREATE TABLE IF NOT EXISTS clientes_roteiro (
    id_cliente TEXT,
    cnpj TEXT,
    nome_cliente TEXT,
    razao_social TEXT,
    rca_id INTEGER,
    filial_codigo TEXT,
    status_visita TEXT,
    PRIMARY KEY (id_cliente, filial_codigo, rca_id)
  );

  CREATE TABLE IF NOT EXISTS pedidos (
    num_pedido TEXT,
    filial_codigo TEXT,
    id_cliente TEXT,
    rca_id INTEGER,
    data_pedido TEXT,
    status_pedido TEXT,
    categoria_corte TEXT,
    vl_faturado_winthor REAL,
    vl_perdido_logistica REAL,
    total_clube REAL,
    qtd_skus INTEGER,
    qtd_cortados INTEGER,
    PRIMARY KEY (num_pedido, filial_codigo, id_cliente)
  );

  CREATE TABLE IF NOT EXISTS pedido_itens (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    num_pedido TEXT,
    filial_codigo TEXT,
    id_cliente TEXT,
    tipo_registro TEXT, -- 'VENDA' ou 'CORTE'
    codprod TEXT,
    descricao TEXT,
    quantidade REAL,
    valor_total REAL
  );

  CREATE INDEX IF NOT EXISTS idx_pedidos_filial ON pedidos (filial_codigo);
  CREATE INDEX IF NOT EXISTS idx_pedidos_data ON pedidos (data_pedido);
  CREATE INDEX IF NOT EXISTS idx_pedidos_cliente ON pedidos (id_cliente);
  CREATE INDEX IF NOT EXISTS idx_pedidos_rca ON pedidos (rca_id);
  CREATE INDEX IF NOT EXISTS idx_itens_pedido ON pedido_itens (num_pedido, filial_codigo);
  CREATE INDEX IF NOT EXISTS idx_itens_codprod ON pedido_itens (codprod);
`);

// Statements preparados
const stmtInsertCliente = db.prepare(`
  INSERT OR REPLACE INTO clientes_roteiro (id_cliente, cnpj, nome_cliente, razao_social, rca_id, filial_codigo, status_visita)
  VALUES (@id_cliente, @cnpj, @nome_cliente, @razao_social, @rca_id, @filial_codigo, @status_visita)
`);

const stmtInsertPedido = db.prepare(`
  INSERT OR REPLACE INTO pedidos (num_pedido, filial_codigo, id_cliente, rca_id, data_pedido, status_pedido, categoria_corte, vl_faturado_winthor, vl_perdido_logistica, total_clube, qtd_skus, qtd_cortados)
  VALUES (@num_pedido, @filial_codigo, @id_cliente, @rca_id, @data_pedido, @status_pedido, @categoria_corte, @vl_faturado_winthor, @vl_perdido_logistica, @total_clube, @qtd_skus, @qtd_cortados)
`);

const stmtInsertItem = db.prepare(`
  INSERT INTO pedido_itens (num_pedido, filial_codigo, id_cliente, tipo_registro, codprod, descricao, quantidade, valor_total)
  VALUES (@num_pedido, @filial_codigo, @id_cliente, @tipo_registro, @codprod, @descricao, @quantidade, @valor_total)
`);

const stmtCheckPedidoExiste = db.prepare(`
  SELECT 1 FROM pedidos WHERE num_pedido = ? AND filial_codigo = ? LIMIT 1
`);

const stmtClientesProcessados = db.prepare(`
  SELECT DISTINCT id_cliente FROM pedidos WHERE filial_codigo = ?
`);

// Função com retry
async function fetchWithRetry(url, maxRetries = 3) {
  for (let attempt = 1; attempt <= maxRetries; attempt++) {
    try {
      const res = await axios.get(url, {
        headers: { 'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64)' },
        httpsAgent: agent,
        timeout: 12000
      });
      return res.data;
    } catch (err) {
      if (attempt === maxRetries) {
        return null;
      }
      await new Promise(r => setTimeout(r, attempt * 500));
    }
  }
  return null;
}

// Execução para as filiais selecionadas
const FILIAIS_ALVO = ['TSJ', 'TCV'];

async function main() {
  console.log(`=== INICIANDO MINERAÇÃO COMPLETA DE PEDIDOS E CORTES (FILIAIS: ${FILIAIS_ALVO.join(', ')}) ===\n`);

  // Carregar hierarquia gerada anteriormente
  const hierarquiaPath = path.join(__dirname, 'hierarquia_completa_ceven.json');
  if (!fs.existsSync(hierarquiaPath)) {
    console.error('Arquivo hierarquia_completa_ceven.json não encontrado!');
    return;
  }
  const hierarquia = JSON.parse(fs.readFileSync(hierarquiaPath, 'utf-8'));

  for (const filSigla of FILIAIS_ALVO) {
    const filialData = hierarquia.find(f => f.filial === filSigla);
    if (!filialData) {
      console.warn(`Filial ${filSigla} não encontrada na hierarquia!`);
      continue;
    }

    const filialKey = filialData.codigoFilial.toLowerCase();
    console.log(`\n🏢 ========================================================`);
    console.log(`🏢 FILIAL ${filSigla} [${filialKey}] — Gerente: ${filialData.gerentes}`);
    console.log(`🏢 Supervisores: ${filialData.totalSupervisores} | Vendedores: ${filialData.totalRcas}`);
    console.log(`🏢 ========================================================\n`);

    // 1. Coletar lista de clientes dos roteiros de cada RCA
    console.log(`1️⃣  Mapeando clientes de todos os ${filialData.totalRcas} vendedores via /api/rca/roteiro-mes...`);
    const clientesMap = new Map(); // id_cliente -> info

    const allRcas = [];
    for (const sup of filialData.supervisores) {
      for (const rca of sup.rcas) {
        if (rca.rcaId && rca.rcaId !== '-') {
          allRcas.push({ rcaId: rca.rcaId, rcaNome: rca.rcaNome, supId: sup.supervisorId, supNome: sup.supervisorNome });
        }
      }
    }

    // Processar roteiros dos RCAs em lotes
    let rcaCount = 0;
    for (const rca of allRcas) {
      rcaCount++;
      const roteiro = await fetchWithRetry(`${CEVEN_BASE}/api/rca/roteiro-mes?filial=${filialKey}&id=${rca.rcaId}`);
      if (Array.isArray(roteiro)) {
        for (const item of roteiro) {
          const cliId = String(item.id_cliente || item.id || '').trim();
          if (cliId && cliId !== '0') {
            if (!clientesMap.has(cliId)) {
              clientesMap.set(cliId, {
                id_cliente: cliId,
                cnpj: item.cnpj || '',
                nome_cliente: item.nome_cliente || item.FANTASIA || '',
                razao_social: item.razao_social || '',
                rca_id: parseInt(rca.rcaId, 10),
                filial_codigo: filialData.codigoFilial.toUpperCase(),
                status_visita: item.status || ''
              });
            }
          }
        }
      }
      if (rcaCount % 10 === 0 || rcaCount === allRcas.length) {
        console.log(`   [${rcaCount}/${allRcas.length} RCAs] Total de clientes distintos encontrados até agora: ${clientesMap.size}`);
      }
    }

    // Salvar clientes mapeados no banco
    const clientesList = Array.from(clientesMap.values());
    console.log(`\n💾 Salvando ${clientesList.length} clientes na tabela clientes_roteiro...`);
    const insertManyClientes = db.transaction((list) => {
      for (const c of list) stmtInsertCliente.run(c);
    });
    insertManyClientes(clientesList);

    // 2. Mineração profunda de pedidos em /api/rca/historico-cliente/{clienteId}
    console.log(`\n2️⃣  Minerando histórico completo de pedidos e cortes de cada cliente...`);

    // Checar quais clientes já foram minerados para permitir retomada rápida
    const clientesJaProcessados = new Set(
      stmtClientesProcessados.all(filialData.codigoFilial.toUpperCase()).map(r => r.id_cliente)
    );
    console.log(`   Clientes já salvos no banco para ${filSigla}: ${clientesJaProcessados.size}`);

    const clientesParaProcessar = clientesList.filter(c => !clientesJaProcessados.has(c.id_cliente));
    console.log(`   Clientes a consultar agora: ${clientesParaProcessar.length}`);

    let totalPedidosExtraidos = 0;
    let totalItensExtraidos = 0;
    let totalCortesExtraidos = 0;
    let totalValorFaturado = 0;
    let totalValorCortado = 0;

    const CONCURRENCY = 6;
    let index = 0;

    async function worker() {
      while (index < clientesParaProcessar.length) {
        const i = index++;
        const cli = clientesParaProcessar[i];
        const historico = await fetchWithRetry(`${CEVEN_BASE}/api/rca/historico-cliente/${cli.id_cliente}?filial=${filialKey}`);

        if (historico && Array.isArray(historico.ultimas_visitas) && historico.ultimas_visitas.length > 0) {
          const transacaoPedidos = db.transaction(() => {
            for (const v of historico.ultimas_visitas) {
              const numPed = String(v.num_pedido || '').trim();
              if (!numPed) continue;

              const vlFat = parseFloat(v.vl_faturado_winthor) || 0;
              const vlPerd = parseFloat(v.vl_perdido_logistica) || 0;
              const skusVendidos = Array.isArray(v.skus) ? v.skus : (v.skus_winthor || []);
              const itensCortados = Array.isArray(v.itens_cortados) ? v.itens_cortados : [];

              stmtInsertPedido.run({
                num_pedido: numPed,
                filial_codigo: filialData.codigoFilial.toUpperCase(),
                id_cliente: cli.id_cliente,
                rca_id: cli.rca_id,
                data_pedido: v.data_visita || null,
                status_pedido: v.status_pedido || v.status || 'FATURADO',
                categoria_corte: v.categoria_corte || 'SEM CORTE',
                vl_faturado_winthor: vlFat,
                vl_perdido_logistica: vlPerd,
                total_clube: parseFloat(v.total_clube) || vlFat,
                qtd_skus: skusVendidos.length,
                qtd_cortados: itensCortados.length
              });

              totalPedidosExtraidos++;
              totalValorFaturado += vlFat;
              totalValorCortado += vlPerd;

              // Inserir SKUs vendidos
              for (const s of skusVendidos) {
                stmtInsertItem.run({
                  num_pedido: numPed,
                  filial_codigo: filialData.codigoFilial.toUpperCase(),
                  id_cliente: cli.id_cliente,
                  tipo_registro: 'VENDA',
                  codprod: String(s.codigo || s.codprod || ''),
                  descricao: s.descricao || '',
                  quantidade: parseFloat(s.quantidade || s.qt_vendida) || 1,
                  valor_total: parseFloat(s.total || s.vl_faturado) || 0
                });
                totalItensExtraidos++;
              }

              // Inserir Itens Cortados
              for (const c of itensCortados) {
                stmtInsertItem.run({
                  num_pedido: numPed,
                  filial_codigo: filialData.codigoFilial.toUpperCase(),
                  id_cliente: cli.id_cliente,
                  tipo_registro: 'CORTE',
                  codprod: String(c.codprod || c.codigo || ''),
                  descricao: c.descricao || '',
                  quantidade: parseFloat(c.qtdev || c.quantidade_cortada || c.quantidade) || 1,
                  valor_total: parseFloat(c.vl_devolvido || c.valor_cortado || c.total) || 0
                });
                totalCortesExtraidos++;
              }
            }
          });
          transacaoPedidos();
        }

        if ((i + 1) % 100 === 0 || i + 1 === clientesParaProcessar.length) {
          const pct = (((i + 1) / clientesParaProcessar.length) * 100).toFixed(1);
          console.log(`   [${filSigla}] Progresso: ${i + 1}/${clientesParaProcessar.length} (${pct}%) | Pedidos: ${totalPedidosExtraidos.toLocaleString()} | Itens: ${totalItensExtraidos.toLocaleString()} | Cortes: ${totalCortesExtraidos.toLocaleString()} | R$ Fat: ${totalValorFaturado.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}`);
        }
      }
    }

    // Disparar workers em paralelo
    const workers = Array.from({ length: CONCURRENCY }, () => worker());
    await Promise.all(workers);

    console.log(`\n✅ Concluída extração da filial ${filSigla}!`);
  }

  // Estatísticas finais consolidadas no banco
  const totalGeralPedidos = db.prepare('SELECT COUNT(*) as c, SUM(vl_faturado_winthor) as fat, SUM(vl_perdido_logistica) as cort FROM pedidos').get();
  const totalGeralItens = db.prepare('SELECT COUNT(*) as c FROM pedido_itens WHERE tipo_registro = "VENDA"').get();
  const totalGeralCortes = db.prepare('SELECT COUNT(*) as c FROM pedido_itens WHERE tipo_registro = "CORTE"').get();

  console.log(`\n========================================================`);
  console.log(`🎉 MINERAÇÃO DE DADOS FINALIZADA COM SUCESSO!`);
  console.log(`📦 Total de Pedidos Armazenados no SQLite: ${totalGeralPedidos.c.toLocaleString()}`);
  console.log(`🛒 Total de Itens Vendidos (Linhas de Pedido): ${totalGeralItens.c.toLocaleString()}`);
  console.log(`✂️ Total de Itens Cortados Registrados: ${totalGeralCortes.c.toLocaleString()}`);
  console.log(`💰 Faturamento Consolidado dos Pedidos: ${totalGeralPedidos.fat.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}`);
  console.log(`💾 Banco de Dados Salvo em: ${dbPath}`);
  console.log(`========================================================\n`);
}

main();

