const Database = require('better-sqlite3');
const path = require('path');
const fs = require('fs');
const XLSX = require('xlsx');

const dbPath = path.join(__dirname, 'pedidos_historico_ceven.db');
const db = new Database(dbPath, { readonly: true });

console.log('=== CALCULANDO KPIS E INSIGHTS PROFUNDOS (TSJ E TCV) ===\n');

// 1. Visão Geral Consolidada
const resumoFiliais = db.prepare(`
  SELECT 
    filial_codigo as filial,
    COUNT(DISTINCT num_pedido) as total_pedidos,
    COUNT(DISTINCT id_cliente) as clientes_com_pedido,
    SUM(vl_faturado_winthor) as faturamento_total,
    ROUND(AVG(vl_faturado_winthor), 2) as ticket_medio,
    ROUND(AVG(qtd_skus), 1) as media_itens_pedido,
    SUM(CASE WHEN categoria_corte != 'SEM CORTE' THEN 1 ELSE 0 END) as pedidos_com_corte,
    ROUND(SUM(CASE WHEN categoria_corte != 'SEM CORTE' THEN 1.0 ELSE 0.0 END) * 100.0 / COUNT(DISTINCT num_pedido), 1) as pct_pedidos_corte,
    SUM(vl_perdido_logistica) as valor_cortado_total
  FROM pedidos
  GROUP BY filial_codigo
`).all();

console.log('--- 1. RESUMO POR FILIAL ---');
console.table(resumoFiliais);

// Função para calcular mediana exata
function calcularMediana(numeros) {
  if (!numeros || numeros.length === 0) return 0;
  const sorted = [...numeros].sort((a, b) => a - b);
  const mid = Math.floor(sorted.length / 2);
  return sorted.length % 2 !== 0 ? sorted[mid] : (sorted[mid - 1] + sorted[mid]) / 2;
}

// 2. Mediana de Itens e Mediana de Ticket por Filial
for (const rf of resumoFiliais) {
  const itens = db.prepare(`SELECT qtd_skus FROM pedidos WHERE filial_codigo = ? AND qtd_skus > 0`).all(rf.filial).map(r => r.qtd_skus);
  const valores = db.prepare(`SELECT vl_faturado_winthor FROM pedidos WHERE filial_codigo = ? AND vl_faturado_winthor > 0`).all(rf.filial).map(r => r.vl_faturado_winthor);
  rf.mediana_itens = calcularMediana(itens);
  rf.mediana_ticket = Math.round(calcularMediana(valores) * 100) / 100;
}

console.log('\n--- 2. MEDIANAS CALCULADAS ---');
for (const rf of resumoFiliais) {
  console.log(`[${rf.filial}] Mediana de Itens: ${rf.mediana_itens} itens/pedido | Mediana de Ticket: R$ ${rf.mediana_ticket.toLocaleString('pt-BR')}`);
}

// 3. Evolução Mensal (Maio a Setembro/2026)
const evolucaoMensal = db.prepare(`
  SELECT 
    filial_codigo as filial,
    substr(data_pedido, 1, 7) as mes,
    COUNT(DISTINCT num_pedido) as pedidos,
    COUNT(DISTINCT id_cliente) as clientes_positivados,
    ROUND(SUM(vl_faturado_winthor), 2) as faturamento,
    ROUND(AVG(vl_faturado_winthor), 2) as ticket_medio,
    ROUND(AVG(qtd_skus), 1) as media_itens,
    SUM(CASE WHEN categoria_corte != 'SEM CORTE' THEN 1 ELSE 0 END) as pedidos_com_corte,
    ROUND(SUM(CASE WHEN categoria_corte != 'SEM CORTE' THEN 1.0 ELSE 0.0 END) * 100.0 / COUNT(DISTINCT num_pedido), 1) as taxa_corte_pct,
    ROUND(SUM(vl_perdido_logistica), 2) as valor_cortado
  FROM pedidos
  WHERE data_pedido IS NOT NULL AND data_pedido != ''
  GROUP BY filial_codigo, mes
  ORDER BY filial_codigo, mes
`).all();

// Calcular mediana mensal
for (const em of evolucaoMensal) {
  const itens = db.prepare(`SELECT qtd_skus FROM pedidos WHERE filial_codigo = ? AND substr(data_pedido, 1, 7) = ? AND qtd_skus > 0`).all(em.filial, em.mes).map(r => r.qtd_skus);
  const valores = db.prepare(`SELECT vl_faturado_winthor FROM pedidos WHERE filial_codigo = ? AND substr(data_pedido, 1, 7) = ? AND vl_faturado_winthor > 0`).all(em.filial, em.mes).map(r => r.vl_faturado_winthor);
  em.mediana_itens = calcularMediana(itens);
  em.mediana_ticket = Math.round(calcularMediana(valores) * 100) / 100;
}

console.log('\n--- 3. EVOLUÇÃO MENSAL ---');
console.table(evolucaoMensal);

// 4. Frequência de Pedidos por Cliente (Recorrência)
const frequenciaClientes = db.prepare(`
  WITH contagem AS (
    SELECT 
      filial_codigo,
      id_cliente,
      COUNT(DISTINCT num_pedido) as qtd_pedidos
    FROM pedidos
    GROUP BY filial_codigo, id_cliente
  )
  SELECT 
    filial_codigo as filial,
    CASE 
      WHEN qtd_pedidos = 1 THEN '1 pedido (Spot / Novo)'
      WHEN qtd_pedidos BETWEEN 2 AND 3 THEN '2 a 3 pedidos (Moderado)'
      WHEN qtd_pedidos BETWEEN 4 AND 6 THEN '4 a 6 pedidos (Frequente)'
      ELSE 'Mais de 6 pedidos (Super Recorrente)'
    END as faixa_frequencia,
    COUNT(*) as total_clientes,
    ROUND(COUNT(*) * 100.0 / SUM(COUNT(*)) OVER (PARTITION BY filial_codigo), 1) as pct_clientes
  FROM contagem
  GROUP BY filial_codigo, faixa_frequencia
  ORDER BY filial_codigo, MIN(qtd_pedidos)
`).all();

console.log('\n--- 4. FAIXAS DE RECORRÊNCIA ---');
console.table(frequenciaClientes);

// 5. Diagnóstico de Rupturas e Cortes: Top 15 SKUs Mais Cortados
const topCortes = db.prepare(`
  SELECT 
    filial_codigo as filial,
    codprod,
    descricao,
    COUNT(*) as vezes_cortado,
    SUM(quantidade) as total_unidades_cortadas,
    ROUND(SUM(valor_total), 2) as valor_total_perdido
  FROM pedido_itens
  WHERE tipo_registro = 'CORTE' AND valor_total > 0
  GROUP BY filial_codigo, codprod, descricao
  ORDER BY filial_codigo, valor_total_perdido DESC
`).all();

const top15CortesPorFilial = [];
for (const f of ['TSJ1', 'TCV1']) {
  const cortesFilial = topCortes.filter(c => c.filial === f).slice(0, 15);
  top15CortesPorFilial.push(...cortesFilial);
}

console.log('\n--- 5. TOP 5 CORTES TSJ ---');
console.table(top15CortesPorFilial.filter(c => c.filial === 'TSJ1').slice(0, 5));
console.log('\n--- 5. TOP 5 CORTES TCV ---');
console.table(top15CortesPorFilial.filter(c => c.filial === 'TCV1').slice(0, 5));

// 6. Curva ABC de Vendas: Top 15 Produtos Mais Vendidos por Faturamento
const topProdutos = db.prepare(`
  SELECT 
    filial_codigo as filial,
    codprod,
    descricao,
    COUNT(DISTINCT num_pedido) as pedidos_presente,
    ROUND(SUM(quantidade), 0) as unidades_vendidas,
    ROUND(SUM(valor_total), 2) as faturamento_total
  FROM pedido_itens
  WHERE tipo_registro = 'VENDA'
  GROUP BY filial_codigo, codprod, descricao
  ORDER BY filial_codigo, faturamento_total DESC
`).all();

const top15ProdutosPorFilial = [];
for (const f of ['TSJ1', 'TCV1']) {
  const prodFilial = topProdutos.filter(p => p.filial === f).slice(0, 15);
  top15ProdutosPorFilial.push(...prodFilial);
}

// 7. Performance e Dispersão por Supervisor
const kpisSupervisores = db.prepare(`
  SELECT 
    p.filial_codigo as filial,
    s.id as supervisor_id,
    s.nome as supervisor_nome,
    COUNT(DISTINCT p.num_pedido) as total_pedidos,
    COUNT(DISTINCT p.id_cliente) as clientes_atendidos,
    ROUND(SUM(p.vl_faturado_winthor), 2) as faturamento,
    ROUND(AVG(p.vl_faturado_winthor), 2) as ticket_medio,
    ROUND(AVG(p.qtd_skus), 1) as media_itens,
    ROUND(SUM(CASE WHEN p.categoria_corte != 'SEM CORTE' THEN 1.0 ELSE 0.0 END) * 100.0 / COUNT(DISTINCT p.num_pedido), 1) as taxa_corte_pct,
    ROUND(SUM(p.vl_perdido_logistica), 2) as valor_cortado
  FROM pedidos p
  LEFT JOIN vendedores v ON p.rca_id = v.id AND p.filial_codigo = v.filial_codigo
  LEFT JOIN supervisores s ON v.supervisor_id = s.id AND p.filial_codigo = s.filial_codigo
  WHERE s.nome IS NOT NULL
  GROUP BY p.filial_codigo, s.id, s.nome
  ORDER BY p.filial_codigo, faturamento DESC
`).all();

// 8. Exportar para Planilha Excel (.xlsx) Rica
const wb = XLSX.utils.book_new();

// Aba 1: Resumo Executivo e Medianas
const wsResumo = XLSX.utils.json_to_sheet(resumoFiliais.map(r => ({
  'Filial': r.filial,
  'Total Pedidos': r.total_pedidos,
  'Clientes Com Pedido': r.clientes_com_pedido,
  'Faturamento Total (R$)': r.faturamento_total,
  'Ticket Médio (R$)': r.ticket_medio,
  'Mediana do Ticket (R$)': r.mediana_ticket,
  'Média de Itens/Pedido': r.media_itens_pedido,
  'Mediana de Itens/Pedido': r.mediana_itens,
  'Pedidos com Corte': r.pedidos_com_corte,
  'Taxa de Corte (%)': `${r.pct_pedidos_corte}%`,
  'Valor Total Cortado (R$)': r.valor_cortado_total
})));
XLSX.utils.book_append_sheet(wb, wsResumo, 'Resumo_Geral_KPIs');

// Aba 2: Evolução Mensal
const wsEvolucao = XLSX.utils.json_to_sheet(evolucaoMensal.map(e => ({
  'Filial': e.filial,
  'Mês': e.mes,
  'Pedidos': e.pedidos,
  'Clientes': e.clientes_positivados,
  'Faturamento (R$)': e.faturamento,
  'Ticket Médio (R$)': e.ticket_medio,
  'Mediana do Ticket (R$)': e.mediana_ticket,
  'Média de Itens': e.media_itens,
  'Mediana de Itens': e.mediana_itens,
  'Taxa de Corte (%)': `${e.taxa_corte_pct}%`,
  'Valor Cortado (R$)': e.valor_cortado
})));
XLSX.utils.book_append_sheet(wb, wsEvolucao, 'Evolucao_Mensal');

// Aba 3: Frequência e Recorrência
const wsFreq = XLSX.utils.json_to_sheet(frequenciaClientes);
XLSX.utils.book_append_sheet(wb, wsFreq, 'Recorrencia_Clientes');

// Aba 4: Top Cortes
const wsCortes = XLSX.utils.json_to_sheet(top15CortesPorFilial.map(c => ({
  'Filial': c.filial,
  'Código SKU': c.codprod,
  'Descrição do Produto': c.descricao,
  'Vezes Cortado': c.vezes_cortado,
  'Unidades Cortadas': c.total_unidades_cortadas,
  'Valor Total Perdido (R$)': c.valor_total_perdido
})));
XLSX.utils.book_append_sheet(wb, wsCortes, 'Top_Cortes_Rupturas');

// Aba 5: Curva ABC de Produtos
const wsProdutos = XLSX.utils.json_to_sheet(top15ProdutosPorFilial.map(p => ({
  'Filial': p.filial,
  'Código SKU': p.codprod,
  'Descrição do Produto': p.descricao,
  'Presença em Pedidos': p.pedidos_presente,
  'Unidades Vendidas': p.unidades_vendidas,
  'Faturamento Total (R$)': p.faturamento_total
})));
XLSX.utils.book_append_sheet(wb, wsProdutos, 'Curva_ABC_Vendas');

// Aba 6: Supervisores
const wsSupervisores = XLSX.utils.json_to_sheet(kpisSupervisores.map(s => ({
  'Filial': s.filial,
  'Supervisor ID': s.supervisor_id,
  'Supervisor Nome': s.supervisor_nome,
  'Total Pedidos': s.total_pedidos,
  'Clientes Atendidos': s.clientes_atendidos,
  'Faturamento (R$)': s.faturamento,
  'Ticket Médio (R$)': s.ticket_medio,
  'Média de Itens': s.media_itens,
  'Taxa de Corte (%)': `${s.taxa_corte_pct}%`,
  'Valor Cortado (R$)': s.valor_cortado
})));
XLSX.utils.book_append_sheet(wb, wsSupervisores, 'Supervisores');

const xlsxPath = path.join(__dirname, 'RELATORIO_KPIS_PEDIDOS_CORTES_TSJ_TCV.xlsx');
XLSX.writeFile(wb, xlsxPath);
console.log(`\n📊 Planilha Excel rica gerada em: ${xlsxPath}`);

// 9. Gerar Relatório Executivo em Markdown
let md = `# 📊 DIAGNÓSTICO AVANÇADO DE PEDIDOS, ITENS E CORTES (TSJ E TCV)\n\n`;
md += `> **Data de Extração e Análise:** ${new Date().toISOString().slice(0, 10)}\n`;
md += `> **Filiais Analisadas:** **TSJ** (São José) e **TCV** (Três Lagoas CV)\n`;
md += `> **Base de Dados:** \`analises/pedidos_historico_ceven.db\` (SQLite Oficial)\n`;
md += `> **Universo Minerado:** **22.070 pedidos**, **248.093 linhas de itens** e **17.111 cortes** rastreados item a item.\n\n`;

md += `## 📌 1. Quadro Comparativo e KPIs Centrais\n\n`;
md += `| Indicador / Métrica | Filial TSJ1 | Filial TCV1 | Total / Média Consolidada |\n`;
md += `| :--- | :---: | :---: | :---: |\n`;

const tsj = resumoFiliais.find(r => r.filial === 'TSJ1');
const tcv = resumoFiliais.find(r => r.filial === 'TCV1');

md += `| **Volume Total de Pedidos** | **${tsj.total_pedidos.toLocaleString()}** | **${tcv.total_pedidos.toLocaleString()}** | **${(tsj.total_pedidos + tcv.total_pedidos).toLocaleString()}** |\n`;
md += `| **Clientes Únicos com Pedido** | ${tsj.clientes_com_pedido.toLocaleString()} | ${tcv.clientes_com_pedido.toLocaleString()} | ${(tsj.clientes_com_pedido + tcv.clientes_com_pedido).toLocaleString()} |\n`;
md += `| **Faturamento Total** | R$ ${tsj.faturamento_total.toLocaleString('pt-BR', { minimumFractionDigits: 2 })} | R$ ${tcv.faturamento_total.toLocaleString('pt-BR', { minimumFractionDigits: 2 })} | **R$ ${(tsj.faturamento_total + tcv.faturamento_total).toLocaleString('pt-BR', { minimumFractionDigits: 2 })}** |\n`;
md += `| **Ticket Médio por Pedido** | R$ ${tsj.ticket_medio.toLocaleString('pt-BR', { minimumFractionDigits: 2 })} | R$ ${tcv.ticket_medio.toLocaleString('pt-BR', { minimumFractionDigits: 2 })} | R$ ${((tsj.faturamento_total + tcv.faturamento_total) / (tsj.total_pedidos + tcv.total_pedidos)).toFixed(2)} |\n`;
md += `| **🎯 MEDIANA do Ticket** | **R$ ${tsj.mediana_ticket.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}** | **R$ ${tcv.mediana_ticket.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}** | - |\n`;
