const Database = require('better-sqlite3');
const db = new Database('analises/pedidos_historico_ceven.db', { readonly: true });

const countCortes = db.prepare("SELECT COUNT(*) as c FROM pedido_itens WHERE tipo_registro = 'CORTE'").get();
console.log('Total registros corte:', countCortes.c);

const sample = db.prepare("SELECT * FROM pedido_itens WHERE tipo_registro = 'CORTE' LIMIT 5").all();
console.log('Amostra de corte:', sample);

const samplePedidosComCorte = db.prepare("SELECT num_pedido, filial_codigo, vl_perdido_logistica, qtd_cortados, categoria_corte FROM pedidos WHERE categoria_corte != 'SEM CORTE' LIMIT 5").all();
console.log('Amostra pedidos com corte:', samplePedidosComCorte);

const Database = require('better-sqlite3');
const path = require('path');
const fs = require('fs');
const XLSX = require('xlsx');

const dbPath = path.join(__dirname, 'pedidos_historico_ceven.db');
const db = new Database(dbPath, { readonly: true });

console.log('=== EXPORTANDO BASE BRUTA DE TCV PARA AUDITORIA EM EXCEL ===\n');

// 1. Aba: Pedidos TCV (cabeçalho completo)
console.log('1. Carregando pedidos de TCV...');
const pedidos = db.prepare(`
  SELECT 
    p.filial_codigo as 'Filial',
    p.num_pedido as 'Numero_Pedido',
    p.data_pedido as 'Data_Pedido',
    p.status_pedido as 'Status_Pedido',
    p.categoria_corte as 'Categoria_Corte',
    p.vl_faturado_winthor as 'Valor_Faturado_R$',
    p.vl_perdido_logistica as 'Valor_Cortado_R$',
    p.qtd_skus as 'Qtd_Itens_Vendidos',
    p.qtd_cortados as 'Qtd_Itens_Cortados',
    p.id_cliente as 'ID_Cliente',
    COALESCE(c.cnpj, '') as 'CNPJ_Cliente',
    COALESCE(c.nome_cliente, '') as 'Nome_Fantasia',
    COALESCE(c.razao_social, '') as 'Razao_Social',
    p.rca_id as 'RCA_ID',
    COALESCE(v.nome, '') as 'RCA_Nome',
    COALESCE(s.id, '') as 'Supervisor_ID',
    COALESCE(s.nome, '') as 'Supervisor_Nome'
  FROM pedidos p
  LEFT JOIN clientes_roteiro c ON p.id_cliente = c.id_cliente AND p.filial_codigo = c.filial_codigo
  LEFT JOIN vendedores v ON p.rca_id = v.id AND p.filial_codigo = v.filial_codigo
  LEFT JOIN supervisores s ON v.supervisor_id = s.id AND p.filial_codigo = s.filial_codigo
  WHERE p.filial_codigo = 'TCV1'
  ORDER BY p.data_pedido DESC, p.num_pedido DESC
`).all();

console.log(`   Carregados ${pedidos.length} pedidos.`);

// 2. Aba: Cortes TCV (cada item cortado)
console.log('2. Carregando itens cortados de TCV...');
const cortes = db.prepare(`
  SELECT 
    i.filial_codigo as 'Filial',
    i.num_pedido as 'Numero_Pedido',
    p.data_pedido as 'Data_Pedido',
    p.categoria_corte as 'Tipo_Corte_Pedido',
    i.id_cliente as 'ID_Cliente',
    COALESCE(c.nome_cliente, '') as 'Nome_Cliente',
    p.rca_id as 'RCA_ID',
    COALESCE(v.nome, '') as 'RCA_Nome',
    i.codprod as 'Codigo_SKU',
    i.descricao as 'Descricao_Produto',
    i.quantidade as 'Quantidade_Cortada',
    i.valor_total as 'Valor_Cortado_R$'
  FROM pedido_itens i
  LEFT JOIN pedidos p ON i.num_pedido = p.num_pedido AND i.filial_codigo = p.filial_codigo
  LEFT JOIN clientes_roteiro c ON i.id_cliente = c.id_cliente AND i.filial_codigo = c.filial_codigo
  LEFT JOIN vendedores v ON p.rca_id = v.id AND i.filial_codigo = v.filial_codigo
  WHERE i.filial_codigo = 'TCV1' AND i.tipo_registro = 'CORTE'
  ORDER BY p.data_pedido DESC, i.num_pedido DESC
`).all();

console.log(`   Carregados ${cortes.length} itens cortados.`);

// 3. Aba: Clientes TCV
console.log('3. Carregando cadastro de clientes de TCV...');
const clientes = db.prepare(`
  SELECT 
    c.filial_codigo as 'Filial',
    c.id_cliente as 'ID_Cliente',
    c.cnpj as 'CNPJ',
    c.nome_cliente as 'Nome_Fantasia',
    c.razao_social as 'Razao_Social',
    c.rca_id as 'RCA_ID',
    COALESCE(v.nome, '') as 'RCA_Nome',
    COALESCE(s.id, '') as 'Supervisor_ID',
    COALESCE(s.nome, '') as 'Supervisor_Nome',
    COUNT(DISTINCT p.num_pedido) as 'Total_Pedidos_Historico',
    ROUND(SUM(p.vl_faturado_winthor), 2) as 'Total_Faturado_R$',
    ROUND(AVG(p.vl_faturado_winthor), 2) as 'Ticket_Medio_R$',
    MAX(p.data_pedido) as 'Data_Ultima_Compra'
  FROM clientes_roteiro c
  LEFT JOIN pedidos p ON c.id_cliente = p.id_cliente AND c.filial_codigo = p.filial_codigo
  LEFT JOIN vendedores v ON c.rca_id = v.id AND c.filial_codigo = v.filial_codigo
  LEFT JOIN supervisores s ON v.supervisor_id = s.id AND c.filial_codigo = s.filial_codigo
  WHERE c.filial_codigo = 'TCV1'
  GROUP BY c.id_cliente, c.filial_codigo
  ORDER BY Total_Faturado_R$ DESC
`).all();

console.log(`   Carregados ${clientes.length} clientes.`);

// 4. Aba: Itens Vendidos TCV
console.log('4. Carregando itens vendidos de TCV...');
const itensVendidos = db.prepare(`
  SELECT 
    i.num_pedido as 'Numero_Pedido',
    p.data_pedido as 'Data_Pedido',
    i.id_cliente as 'ID_Cliente',
    COALESCE(c.nome_cliente, '') as 'Nome_Cliente',
    p.rca_id as 'RCA_ID',
    i.codprod as 'Codigo_SKU',
    i.descricao as 'Descricao_Produto',
    i.quantidade as 'Quantidade_Vendida',
    i.valor_total as 'Valor_Faturado_R$'
  FROM pedido_itens i
  LEFT JOIN pedidos p ON i.num_pedido = p.num_pedido AND i.filial_codigo = p.filial_codigo
  LEFT JOIN clientes_roteiro c ON i.id_cliente = c.id_cliente AND i.filial_codigo = c.filial_codigo
  WHERE i.filial_codigo = 'TCV1' AND i.tipo_registro = 'VENDA'
  ORDER BY p.data_pedido DESC, i.num_pedido DESC
`).all();

console.log(`   Carregados ${itensVendidos.length} itens vendidos.`);

// 5. Montando Pasta de Trabalho Excel
console.log('\nMontando arquivo Excel (.xlsx)...');
const wb = XLSX.utils.book_new();

console.log(' - Adicionando aba Pedidos_TCV...');
XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(pedidos), 'Pedidos_TCV');

console.log(' - Adicionando aba Cortes_TCV...');
XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(cortes), 'Cortes_TCV');

console.log(' - Adicionando aba Clientes_TCV...');
XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(clientes), 'Clientes_TCV');

console.log(' - Adicionando aba Itens_Vendidos_TCV...');
XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(itensVendidos), 'Itens_Vendidos_TCV');

const xlsxOut = path.join(__dirname, 'AUDITORIA_DADOS_BRUTOS_TCV.xlsx');
console.log(`Escrevendo arquivo em disco: ${xlsxOut}...`);
XLSX.writeFile(wb, xlsxOut);

console.log(`\n🎉 ARQUIVO DE AUDITORIA DE TCV GERADO COM SUCESSO!`);
console.log(`📁 Caminho: ${xlsxOut}`);

