const Database = require('better-sqlite3');
const path = require('path');
const fs = require('fs');

const dbPath = path.join(__dirname, 'pedidos_historico_ceven.db');
const db = new Database(dbPath);

console.log('=== POPULANDO SUPERVISORES, VENDEDORES E ATUALIZANDO CORTES ===\n');

// 1. Inserir Hierarquia completa
const hierarquiaPath = path.join(__dirname, 'hierarquia_completa_ceven.json');
const hierarquia = JSON.parse(fs.readFileSync(hierarquiaPath, 'utf-8'));

const stmtInsertSup = db.prepare(`
  INSERT OR REPLACE INTO supervisores (id, nome, filial_codigo)
  VALUES (@id, @nome, @filial_codigo)
`);

const stmtInsertVend = db.prepare(`
  INSERT OR REPLACE INTO vendedores (id, nome, supervisor_id, filial_codigo)
  VALUES (@id, @nome, @supervisor_id, @filial_codigo)
`);

const insertHierarchy = db.transaction(() => {
  for (const f of hierarquia) {
    const filKey = f.codigoFilial.toUpperCase();
    for (const s of f.supervisores) {
      stmtInsertSup.run({
        id: s.supervisorId,
        nome: s.supervisorNome,
        filial_codigo: filKey
      });

      for (const v of s.rcas) {
        const vid = parseInt(v.rcaId, 10);
        if (!isNaN(vid)) {
          stmtInsertVend.run({
            id: vid,
            nome: v.rcaNome,
            supervisor_id: s.supervisorId,
            filial_codigo: filKey
          });
        }
      }
    }
  }
});

insertHierarchy();
console.log('✅ Supervisores e Vendedores inseridos no SQLite:');
console.log('   Total supervisores:', db.prepare('SELECT COUNT(*) as c FROM supervisores').get().c);
console.log('   Total vendedores:', db.prepare('SELECT COUNT(*) as c FROM vendedores').get().c);

// 2. Construir Catálogo de Preço Médio Unitário de Venda por SKU
console.log('\n2. Calculando catálogo de preços médios unitários por SKU...');
const catalogoPrecos = new Map();

// Média por SKU na filial e média geral do grupo
const precosFilial = db.prepare(`
  SELECT 
    filial_codigo,
    codprod,
    ROUND(SUM(valor_total) / SUM(quantidade), 2) as preco_unitario
  FROM pedido_itens
  WHERE tipo_registro = 'VENDA' AND quantidade > 0 AND valor_total > 0
  GROUP BY filial_codigo, codprod
`).all();

for (const p of precosFilial) {
  catalogoPrecos.set(`${p.filial_codigo}_${p.codprod}`, p.preco_unitario);
}

const precosGerais = db.prepare(`
  SELECT 
    codprod,
    ROUND(SUM(valor_total) / SUM(quantidade), 2) as preco_unitario
  FROM pedido_itens
  WHERE tipo_registro = 'VENDA' AND quantidade > 0 AND valor_total > 0
  GROUP BY codprod
`).all();

for (const p of precosGerais) {
  if (!catalogoPrecos.has(`GERAL_${p.codprod}`)) {
    catalogoPrecos.set(`GERAL_${p.codprod}`, p.preco_unitario);
  }
}

console.log(`   Catálogo construído com ${catalogoPrecos.size} referências de preço unitário.`);

