console.log(`   Catálogo construído com ${catalogoPrecos.size} referências de preço.`);

// 3. Atualizar Itens de Corte de TCV com quantidade real e preço estimado
console.log('\n3. Reconsultando pedidos de TCV com cortes para capturar quantidade real (qt_cortada) e valor...');

