  DELETE FROM pedido_itens WHERE num_pedido = ? AND filial_codigo = 'TCV1' AND tipo_registro = 'CORTE'
`);

const stmtInsertCorteAtualizado = db.prepare(`
  INSERT INTO pedido_itens (num_pedido, filial_codigo, id_cliente, tipo_registro, codprod, descricao, quantidade, valor_total)
  VALUES (@num_pedido, 'TCV1', @id_cliente, 'CORTE', @codprod, @descricao, @quantidade, @valor_total)
`);

async function atualizarCortesTCV() {
  let processados = 0;
  let totalCortesAtualizados = 0;
  const CONCURRENCY = 8;
  let index = 0;

  async function worker() {
    while (index < clientesComCorte.length) {
      const i = index++;
      const cliId = clientesComCorte[i].id_cliente;

      try {
        const res = await axios.get(`${CEVEN_BASE}/api/rca/historico-cliente/${cliId}?filial=tcv1`, {
          headers: { 'User-Agent': 'Mozilla/5.0' },
          httpsAgent: agent,
          timeout: 10000
        });

        const visitas = res.data?.ultimas_visitas || [];
        const transacao = db.transaction(() => {
          for (const v of visitas) {
            const numPed = String(v.num_pedido || '').trim();
            if (!numPed) continue;

            if (Array.isArray(v.itens_cortados) && v.itens_cortados.length > 0) {
              stmtDeleteCortesPedido.run(numPed);

              for (const c of v.itens_cortados) {
                const cod = String(c.codigo || c.codprod || '').trim();
                const desc = c.descricao || '';
                const qt = Math.abs(parseFloat(c.qt_cortada || c.quantidade_cortada || c.qtdev || c.quantidade) || 1);

                // Buscar preço unitário no catálogo
                let precoUnit = catalogoPrecos.get(`TCV1_${cod}`) || catalogoPrecos.get(`GERAL_${cod}`) || 0;
                let vlTotal = Math.round(qt * precoUnit * 100) / 100;

                stmtInsertCorteAtualizado.run({
                  num_pedido: numPed,
                  id_cliente: cliId,
                  codprod: cod,
                  descricao: desc,
                  quantidade: qt,
                  valor_total: vlTotal
                });
                totalCortesAtualizados++;
              }
            }
          }
        });
        transacao();

      } catch (err) {
        // ignora timeout pontual
      }

      processados++;
      if (processados % 100 === 0 || processados === clientesComCorte.length) {
        console.log(`   [TCV] Atualizados ${processados}/${clientesComCorte.length} clientes | Itens cortados com qtd real: ${totalCortesAtualizados}`);
      }
    }
  }

  const workers = Array.from({ length: CONCURRENCY }, () => worker());
  await Promise.all(workers);

  console.log(`\n✅ Concluída atualização dos cortes de TCV! Total cortes gravados com qtd real: ${totalCortesAtualizados}`);
}

atualizarCortesTCV();

