const Database = require('better-sqlite3');
const path = require('path');
const fs = require('fs');
const XLSX = require('xlsx');

const dbPath = path.join(__dirname, 'pedidos_historico_ceven.db');
const db = new Database(dbPath, { readonly: true });

console.log('=== REGERANDO BASE DE AUDITORIA DE TCV COM TODAS AS CORREÇÕES ===\n');

// Função auxiliar para converter string 'YYYY-MM-DD' em Date nativa do Excel com meio-dia UTC
function toExcelDate(dateStr) {
  if (!dateStr || typeof dateStr !== 'string') return null;
  const parts = dateStr.trim().slice(0, 10).split('-');
  if (parts.length === 3) {
    const y = parseInt(parts[0], 10);
    const m = parseInt(parts[1], 10) - 1;
    const d = parseInt(parts[2], 10);
    if (y >= 1990 && y <= 2050 && m >= 0 && m <= 11 && d >= 1 && d <= 31) {
      return new Date(Date.UTC(y, m, d, 12, 0, 0));
    }
  }
  return null;
}

// 1. Aba: Pedidos TCV
console.log('1. Carregando e formatando Pedidos TCV...');
const rawPedidos = db.prepare(`
  SELECT 
    p.filial_codigo as filial,
    p.num_pedido,
    p.data_pedido,
    p.status_pedido,
    p.categoria_corte,
    p.vl_faturado_winthor,
    p.vl_perdido_logistica,
    p.qtd_skus,
    p.qtd_cortados,
    p.id_cliente,
    COALESCE(c.cnpj, '') as cnpj,
    COALESCE(c.nome_cliente, '') as nome_fantasia,
    COALESCE(c.razao_social, '') as razao_social,
    p.rca_id,
    COALESCE(v.nome, '') as rca_nome,
    COALESCE(s.id, '') as supervisor_id,
    COALESCE(s.nome, '') as supervisor_nome
  FROM pedidos p
  LEFT JOIN clientes_roteiro c ON p.id_cliente = c.id_cliente AND p.filial_codigo = c.filial_codigo
  LEFT JOIN vendedores v ON p.rca_id = v.id AND p.filial_codigo = v.filial_codigo
  LEFT JOIN supervisores s ON v.supervisor_id = s.id AND p.filial_codigo = s.filial_codigo
  WHERE p.filial_codigo = 'TCV1'
  ORDER BY p.data_pedido DESC, p.num_pedido DESC
`).all();

const pedidosFormatados = rawPedidos.map(p => ({
  'Filial': p.filial,
  'Numero_Pedido': p.num_pedido,
  'Data_Pedido': toExcelDate(p.data_pedido),
  'Status_Pedido': p.status_pedido,
  'Categoria_Corte': p.categoria_corte,
  'Valor_Faturado_R$': p.vl_faturado_winthor,
  'Valor_Cortado_R$': p.vl_perdido_logistica,
  'Qtd_Itens_Vendidos': p.qtd_skus,
  'Qtd_Itens_Cortados': p.qtd_cortados,
  'ID_Cliente': p.id_cliente,
  'CNPJ_Cliente': p.cnpj,
  'Nome_Fantasia': p.nome_fantasia,
  'Razao_Social': p.razao_social,
  'RCA_ID': p.rca_id,
  'RCA_Nome': p.rca_nome,
  'Supervisor_ID': p.supervisor_id,
  'Supervisor_Nome': p.supervisor_nome
}));
console.log(`   Formatados ${pedidosFormatados.length} pedidos.`);

// 2. Aba: Cortes TCV
console.log('2. Carregando e formatando Cortes TCV...');
const rawCortes = db.prepare(`
  SELECT 
    i.filial_codigo as filial,
    i.num_pedido,
    p.data_pedido,
    p.categoria_corte,
    i.id_cliente,
    COALESCE(c.nome_cliente, '') as nome_cliente,
    p.rca_id,
    COALESCE(v.nome, '') as rca_nome,
    COALESCE(s.id, '') as supervisor_id,
    COALESCE(s.nome, '') as supervisor_nome,
    i.codprod,
    i.descricao,
    i.quantidade,
    i.valor_total
  FROM pedido_itens i
  LEFT JOIN pedidos p ON i.num_pedido = p.num_pedido AND i.filial_codigo = p.filial_codigo
  LEFT JOIN clientes_roteiro c ON i.id_cliente = c.id_cliente AND i.filial_codigo = c.filial_codigo
  LEFT JOIN vendedores v ON p.rca_id = v.id AND i.filial_codigo = v.filial_codigo
  LEFT JOIN supervisores s ON v.supervisor_id = s.id AND i.filial_codigo = s.filial_codigo
  WHERE i.filial_codigo = 'TCV1' AND i.tipo_registro = 'CORTE'
  ORDER BY p.data_pedido DESC, i.num_pedido DESC
`).all();

const cortesFormatados = rawCortes.map(c => ({
  'Filial': c.filial,
  'Numero_Pedido': c.num_pedido,
  'Data_Pedido': toExcelDate(c.data_pedido),
  'Tipo_Corte_Pedido': c.categoria_corte,
  'ID_Cliente': c.id_cliente,
  'Nome_Cliente': c.nome_cliente,
  'RCA_ID': c.rca_id,
  'RCA_Nome': c.rca_nome,
  'Supervisor_ID': c.supervisor_id,
  'Supervisor_Nome': c.supervisor_nome,
  'Codigo_SKU': c.codprod,
  'Descricao_Produto': c.descricao,
  'Quantidade_Cortada': c.quantidade,
  'Valor_Cortado_R$': c.valor_total
}));
console.log(`   Formatados ${cortesFormatados.length} itens cortados.`);

// 3. Aba: Clientes TCV
console.log('3. Carregando e formatando Clientes TCV...');
const rawClientes = db.prepare(`
  SELECT 
    c.filial_codigo as filial,
    c.id_cliente,
    c.cnpj,
    c.nome_cliente as nome_fantasia,
    c.razao_social,
    c.rca_id,
    COALESCE(v.nome, '') as rca_nome,
    COALESCE(s.id, '') as supervisor_id,
    COALESCE(s.nome, '') as supervisor_nome,
    COUNT(DISTINCT p.num_pedido) as total_pedidos,
    ROUND(COALESCE(SUM(p.vl_faturado_winthor), 0), 2) as total_faturado,
    ROUND(COALESCE(AVG(p.vl_faturado_winthor), 0), 2) as ticket_medio,
    MAX(p.data_pedido) as data_ult
  FROM clientes_roteiro c
  LEFT JOIN pedidos p ON c.id_cliente = p.id_cliente AND c.filial_codigo = p.filial_codigo
  LEFT JOIN vendedores v ON c.rca_id = v.id AND c.filial_codigo = v.filial_codigo
  LEFT JOIN supervisores s ON v.supervisor_id = s.id AND c.filial_codigo = s.filial_codigo
  WHERE c.filial_codigo = 'TCV1'
  GROUP BY c.id_cliente, c.filial_codigo
  ORDER BY total_faturado DESC
`).all();

const clientesFormatados = rawClientes.map(cli => ({
  'Filial': cli.filial,
  'ID_Cliente': cli.id_cliente,
  'CNPJ': cli.cnpj,
  'Nome_Fantasia': cli.nome_fantasia,
  'Razao_Social': cli.razao_social,
  'RCA_ID': cli.rca_id,
  'RCA_Nome': cli.rca_nome,
  'Supervisor_ID': cli.supervisor_id,
  'Supervisor_Nome': cli.supervisor_nome,
  'Total_Pedidos_Historico': cli.total_pedidos,
  'Total_Faturado_R$': cli.total_faturado,
  'Ticket_Medio_R$': cli.ticket_medio,
  'Data_Ultima_Compra': toExcelDate(cli.data_ult)
}));
console.log(`   Formatados ${clientesFormatados.length} clientes.`);

// 4. Aba: Itens Vendidos TCV
console.log('4. Carregando e formatando Itens Vendidos TCV...');
const rawItens = db.prepare(`
  SELECT 
    i.num_pedido,
    p.data_pedido,
    i.id_cliente,
    COALESCE(c.nome_cliente, '') as nome_cliente,
    p.rca_id,
    COALESCE(v.nome, '') as rca_nome,
    i.codprod,
    i.descricao,
    i.quantidade,
    i.valor_total
  FROM pedido_itens i
  LEFT JOIN pedidos p ON i.num_pedido = p.num_pedido AND i.filial_codigo = p.filial_codigo
  LEFT JOIN clientes_roteiro c ON i.id_cliente = c.id_cliente AND i.filial_codigo = c.filial_codigo
  LEFT JOIN vendedores v ON p.rca_id = v.id AND i.filial_codigo = v.filial_codigo
  WHERE i.filial_codigo = 'TCV1' AND i.tipo_registro = 'VENDA'
  ORDER BY p.data_pedido DESC, i.num_pedido DESC
`).all();

const itensFormatados = rawItens.map(it => ({
  'Numero_Pedido': it.num_pedido,
  'Data_Pedido': toExcelDate(it.data_pedido),
  'ID_Cliente': it.id_cliente,
  'Nome_Cliente': it.nome_cliente,
  'RCA_ID': it.rca_id,
  'RCA_Nome': it.rca_nome,
  'Codigo_SKU': it.codprod,
  'Descricao_Produto': it.descricao,
  'Quantidade_Vendida': it.quantidade,
  'Valor_Faturado_R$': it.valor_total
}));
console.log(`   Formatados ${itensFormatados.length} itens vendidos.`);

// 5. Montar e Salvar o Workbook com opções nativas de data
console.log('\nMontando Pasta de Trabalho Excel com formatação nativa de datas (dd/mm/yyyy)...');
const wb = XLSX.utils.book_new();

const optSheet = { cellDates: true, dateNF: 'dd/mm/yyyy' };

console.log(' - Gerando aba Pedidos_TCV...');
const wsPedidos = XLSX.utils.json_to_sheet(pedidosFormatados, optSheet);
XLSX.utils.book_append_sheet(wb, wsPedidos, 'Pedidos_TCV');

console.log(' - Gerando aba Cortes_TCV...');
const wsCortes = XLSX.utils.json_to_sheet(cortesFormatados, optSheet);
XLSX.utils.book_append_sheet(wb, wsCortes, 'Cortes_TCV');

console.log(' - Gerando aba Clientes_TCV...');
const wsClientes = XLSX.utils.json_to_sheet(clientesFormatados, optSheet);
XLSX.utils.book_append_sheet(wb, wsClientes, 'Clientes_TCV');

console.log(' - Gerando aba Itens_Vendidos_TCV...');
const wsItens = XLSX.utils.json_to_sheet(itensFormatados, optSheet);
XLSX.utils.book_append_sheet(wb, wsItens, 'Itens_Vendidos_TCV');

const xlsxOut = path.join(__dirname, 'AUDITORIA_DADOS_BRUTOS_TCV.xlsx');
console.log(`Escrevendo arquivo corrigido em disco: ${xlsxOut}...`);
XLSX.writeFile(wb, xlsxOut);

console.log(`\n🎉 PLANILHA DE AUDITORIA DE TCV 100% CORRIGIDA E ATUALIZADA!`);
console.log(`📁 Local: ${xlsxOut}`);

