const statusStats = db.prepare(`
  SELECT 
    filial_codigo,
    status_pedido,
    COUNT(*) as total,
    SUM(vl_faturado_winthor) as valor_total
  FROM pedidos
  GROUP BY filial_codigo, status_pedido
`).all();

console.log('\nStatus dos Pedidos por Filial:');
console.table(statusStats);

const Database = require('better-sqlite3');
const path = require('path');
const fs = require('fs');
const XLSX = require('xlsx');

const dbPath = path.join(__dirname, 'pedidos_historico_ceven.db');
const db = new Database(dbPath, { readonly: true });

console.log('=== ATUALIZANDO EXCEL TCV COM REGRAS CONTÁBEIS E OPERACIONAIS DE STATUS ===\n');

// Converter string 'YYYY-MM-DD' em Date nativa do Excel com meio-dia UTC
function toExcelDate(dateStr) {
  if (!dateStr || typeof dateStr !== 'string') return null;
  const parts = dateStr.trim().slice(0, 10).split('-');
  if (parts.length === 3) {
    const y = parseInt(parts[0], 10);
    const m = parseInt(parts[1], 10) - 1;
    const d = parseInt(parts[2], 10);
    if (y >= 1990 && y <= 2050 && m >= 0 && m <= 11 && d >= 1 && d <= 31) {
      return new Date(Date.UTC(y, m, d, 12, 0, 0));
    }
  }
  return null;
}

// 1. Aba: Pedidos TCV
console.log('1. Carregando e estruturando Pedidos TCV...');
const rawPedidos = db.prepare(`
  SELECT 
    p.filial_codigo as filial,
    p.num_pedido,
    p.data_pedido,
    p.status_pedido,
    CASE 
      WHEN p.status_pedido = 'FATURADO' THEN 'Faturado Concluído'
      WHEN p.status_pedido = 'LIBERADO' THEN 'Liberado (Sujeito a Corte Logístico)'
      WHEN p.status_pedido = 'BLOQUEADO' THEN 'Bloqueado (Sujeito a Negação/Corte)'
      WHEN p.status_pedido = 'AGUARDANDO_WINTHOR' THEN 'Aguardando Winthor'
      ELSE p.status_pedido
    END as situacao_operacional,
    ROUND(COALESCE(p.total_clube, p.vl_faturado_winthor), 2) as valor_pedido_digitado,
    CASE WHEN p.status_pedido = 'FATURADO' THEN ROUND(p.vl_faturado_winthor, 2) ELSE 0 END as valor_faturado_oficial,
    CASE WHEN p.status_pedido = 'LIBERADO' THEN ROUND(p.vl_faturado_winthor, 2) ELSE 0 END as valor_liberado_expedicao,
    CASE WHEN p.status_pedido = 'BLOQUEADO' THEN ROUND(p.vl_faturado_winthor, 2) ELSE 0 END as valor_bloqueado,
    p.categoria_corte,
    ROUND(COALESCE(p.vl_perdido_logistica, 0), 2) as valor_cortado_logistica,
    p.qtd_skus,
    p.qtd_cortados,
    p.id_cliente,
    COALESCE(c.cnpj, '') as cnpj,
    COALESCE(c.nome_cliente, '') as nome_fantasia,
    COALESCE(c.razao_social, '') as razao_social,
    p.rca_id,
    COALESCE(v.nome, '') as rca_nome,
    COALESCE(s.id, '') as supervisor_id,
    COALESCE(s.nome, '') as supervisor_nome
  FROM pedidos p
  LEFT JOIN clientes_roteiro c ON p.id_cliente = c.id_cliente AND p.filial_codigo = c.filial_codigo
  LEFT JOIN vendedores v ON p.rca_id = v.id AND p.filial_codigo = v.filial_codigo
  LEFT JOIN supervisores s ON v.supervisor_id = s.id AND p.filial_codigo = s.filial_codigo
  WHERE p.filial_codigo = 'TCV1'
  ORDER BY p.data_pedido DESC, p.num_pedido DESC
`).all();

const pedidosFormatados = rawPedidos.map(p => ({
  'Filial': p.filial,
  'Numero_Pedido': p.num_pedido,
  'Data_Pedido': toExcelDate(p.data_pedido),
