  'Valor_Liberado_Expedicao_R$': p.valor_liberado_expedicao,
  'Valor_Bloqueado_R$': p.valor_bloqueado,
  'Categoria_Corte': p.categoria_corte,
  'Valor_Cortado_Logistica_R$': p.valor_cortado_logistica,
  'Qtd_Itens_Vendidos': p.qtd_skus,
