console.log(' - Gerando aba Itens_Vendidos_TCV...');
XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(itensFormatados, optSheet), 'Itens_Vendidos_TCV');

const xlsxOut = path.join(__dirname, 'AUDITORIA_DADOS_BRUTOS_TCV.xlsx');
console.log(`Escrevendo arquivo atualizado em disco: ${xlsxOut}...`);

try {
