const Database = require('better-sqlite3');
const path = require('path');
const axios = require('axios');
const https = require('https');

const CEVEN_BASE = 'https://ceven.drivetriunfante-locomotiva.com.br';
const agent = new https.Agent({ rejectUnauthorized: false, keepAlive: true });

const dbPath = path.join(__dirname, 'pedidos_historico_ceven.db');
const db = new Database(dbPath);
db.pragma('journal_mode = WAL');

console.log('=== ATUALIZANDO DEFINITIVAMENTE TODOS OS CORTES DE TCV ===\n');

// 1. Construir catálogo completo de preços unitários (TCV e Geral)
console.log('1. Carregando catálogo de preços unitários por SKU...');
const catalogo = new Map();

const precos = db.prepare(`
  SELECT 
    codprod,
    ROUND(SUM(valor_total) / SUM(quantidade), 2) as preco_unit
  FROM pedido_itens
  WHERE tipo_registro = 'VENDA' AND quantidade > 0 AND valor_total > 0
  GROUP BY codprod
`).all();

for (const p of precos) {
  catalogo.set(p.codprod, p.preco_unit);
}
console.log(`   ${catalogo.size} SKUs com preço unitário de venda mapeado.`);

// 2. Buscar clientes com pedidos que têm cortes
const clientes = db.prepare(`
  SELECT DISTINCT id_cliente 
  FROM pedidos 
  WHERE filial_codigo = 'TCV1' AND (categoria_corte != 'SEM CORTE' OR qtd_cortados > 0)
`).all().map(r => r.id_cliente);

console.log(`\n2. ${clientes.length} clientes possuem pedidos com corte em TCV. Iniciando varredura...`);

const stmtDeleteCortes = db.prepare(`
  DELETE FROM pedido_itens WHERE num_pedido = ? AND filial_codigo = 'TCV1' AND tipo_registro = 'CORTE'
`);

const stmtInsertCorte = db.prepare(`
  INSERT INTO pedido_itens (num_pedido, filial_codigo, id_cliente, tipo_registro, codprod, descricao, quantidade, valor_total)
  VALUES (@num_pedido, 'TCV1', @id_cliente, 'CORTE', @codprod, @descricao, @quantidade, @valor_total)
`);

const stmtUpdatePedidoCorte = db.prepare(`
  UPDATE pedidos 
  SET qtd_cortados = @qtd_cortados, 
      categoria_corte = @categoria_corte,
      vl_perdido_logistica = CASE 
        WHEN vl_perdido_logistica > 0 THEN vl_perdido_logistica 
        ELSE @vl_calculado 
      END
  WHERE num_pedido = @num_pedido AND filial_codigo = 'TCV1'
`);

async function run() {
  const queue = [...clientes];
  let totalCortesGravados = 0;
  let processados = 0;

  async function worker() {
    while (queue.length > 0) {
      const cliId = queue.shift();
      if (!cliId) break;

      try {
        const res = await axios.get(`${CEVEN_BASE}/api/rca/historico-cliente/${cliId}?filial=tcv1`, {
          headers: { 'User-Agent': 'Mozilla/5.0' },
          httpsAgent: agent,
          timeout: 10000
        });

        const visitas = res.data?.ultimas_visitas || [];
        const transacao = db.transaction(() => {
          for (const v of visitas) {
            const numPed = String(v.num_pedido || '').trim();
            if (!numPed) continue;

            const cortes = v.itens_cortados || [];
            if (cortes.length > 0) {
              stmtDeleteCortes.run(numPed);

              let somaValorCortado = 0;
              for (const c of cortes) {
                const cod = String(c.codigo || c.codprod || '').trim();
                const desc = c.descricao || '';
                const qt = Math.abs(parseFloat(c.qt_cortada || c.quantidade_cortada || c.qtdev || c.quantidade) || 1);

                let precoUnit = catalogo.get(cod) || 0;
                let vlCortado = Math.round(qt * precoUnit * 100) / 100;
                somaValorCortado += vlCortado;

                stmtInsertCorte.run({
                  num_pedido: numPed,
                  id_cliente: cliId,
                  codprod: cod,
                  descricao: desc,
                  quantidade: qt,
                  valor_total: vlCortado
                });
                totalCortesGravados++;
              }

              stmtUpdatePedidoCorte.run({
                num_pedido: numPed,
                qtd_cortados: cortes.length,
                categoria_corte: v.categoria_corte || 'COMERCIAL',
                vl_calculado: Math.round(somaValorCortado * 100) / 100
              });
            }
          }
        });
        transacao();

      } catch (e) {
        // ignora timeout pontual
      }

      processados++;
      if (processados % 100 === 0 || processados === clientes.length) {
        console.log(`   Progresso: ${processados}/${clientes.length} clientes | Cortes gravados com quantidade e valor: ${totalCortesGravados}`);
      }
    }
  }

  // 10 workers paralelos consumindo da fila thread-safe
  const workers = Array.from({ length: 10 }, () => worker());
  await Promise.all(workers);

  console.log(`\n🎉 Todos os ${totalCortesGravados} cortes foram atualizados com sucesso com quantidade real e preço!`);
}

run();

