    SELECT 
      filial_codigo AS "Filial",
      rca_id AS "Cód_RCA",
      rca_nome AS "Nome_RCA",
      supervisor_nome AS "Supervisor",
      numnota AS "Número_NF",
      data_devolucao_br AS "Data_Devolução",
