// -------------------------------------------------------------
// ABA 1: Devoluções Resumo por Nota Fiscal (COM ITENS E PEÇAS)
// -------------------------------------------------------------
const notas = db.prepare(`
  SELECT 
    n.filial_codigo AS "Filial",
    n.gerente_nome AS "Gerente",
    n.supervisor_nome AS "Supervisor",
    n.rca_id AS "Cód_RCA",
    n.rca_nome AS "Nome_RCA",
    n.numnota AS "Número_NF",
    n.data_devolucao_br AS "Data_Devolução",
    n.codcli AS "Cód_Cliente",
    n.nomecli AS "Razão_Social_Cliente",
    n.cnpj AS "CNPJ",
    COALESCE(sub.total_itens, n.qtd_itens) AS "Qtd_Itens_Distintos_Nota",
    COALESCE(sub.total_pecas, 0) AS "Qtd_Peças_Total_Nota",
    n.vl_devolvido_total AS "Valor_Total_Nota_R$"
  FROM devolucoes_notas n
  LEFT JOIN (
    SELECT filial_codigo, rca_id, numnota, COUNT(*) AS total_itens, SUM(qtdev) AS total_pecas
    FROM devolucoes_itens
    GROUP BY filial_codigo, rca_id, numnota
  ) sub ON sub.filial_codigo = n.filial_codigo AND sub.rca_id = n.rca_id AND sub.numnota = n.numnota
  ORDER BY n.filial_codigo, n.vl_devolvido_total DESC
`).all();

const wsNotas = XLSX.utils.json_to_sheet(notas);
XLSX.utils.book_append_sheet(wb, wsNotas, 'Devoluções_Notas');

// -------------------------------------------------------------
