args.CodeContent:
const Database = require('better-sqlite3');
const path = require('path');
const XLSX = require('xlsx');

const db = new Database(path.join(__dirname, 'pedidos_historico_ceven.db'));

console.log('🚀 REGERANDO PLANILHA DEVOLUÇÕES E CADASTROS COM HIERARQUIA COMPLETA (FILIAL, GERENTE, SUPERVISOR)...');

const wb = XLSX.utils.book_new();

// -------------------------------------------------------------
// ABA 1: Devoluções Itens Detalhados (COM FILIAL, GERENTE E SUPERVISOR NA FRENTE)
// -------------------------------------------------------------
const itens = db.prepare(`
  SELECT 
    i.filial_codigo AS "Filial",
    COALESCE(n.gerente_nome, 'Gerência Geral') AS "Gerente",
    i.supervisor_nome AS "Supervisor",
    i.rca_id AS "Cód_RCA",
    i.rca_nome AS "Nome_RCA",
    i.numnota AS "Número_NF",
    i.data_devolucao_br AS "Data_Devolução",
    i.codcli AS "Cód_Cliente",
    i.nomecli AS "Razão_Social_Cliente",
    i.cnpj AS "CNPJ",
    i.codprod AS "Cód_Produto",
    i.descricao AS "Descrição_Produto",
    i.qtdev AS "Quantidade_Devolvida",
    i.vl_devolvido AS "Valor_Devolvido_R$",
    i.motivo AS "Motivo_Devolução"
  FROM devolucoes_itens i
  LEFT JOIN devolucoes_notas n ON n.filial_codigo = i.filial_codigo AND n.rca_id = i.rca_id AND n.numnota = i.numnota
  ORDER BY i.filial_codigo, i.supervisor_nome, i.rca_id, i.numnota, i.vl_devolvido DESC
`).all();

const wsItens = XLSX.utils.json_to_sheet(itens);
XLSX.utils.book_append_sheet(wb, wsItens, 'Devoluções_Itens');

// -------------------------------------------------------------
// ABA 2: Devoluções Resumo por Nota Fiscal (COM ITENS E PEÇAS)
// -------------------------------------------------------------
const notas = db.prepare(`
  SELECT 
    n.filial_codigo AS "Filial",
    n.gerente_nome AS "Gerente",
    n.supervisor_nome AS "Supervisor",
    n.rca_id AS "Cód_RCA",
    n.rca_nome AS "Nome_RCA",
    n.numnota AS "Número_NF",
    n.data_devolucao_br AS "Data_Devolução",
    n.codcli AS "Cód_Cliente",
    n.nomecli AS "Razão_Social_Cliente",
    n.cnpj AS "CNPJ",
    COALESCE(sub.total_itens, n.qtd_itens) AS "Qtd_Itens_Distintos_Nota",
    COALESCE(sub.total_pecas, 0) AS "Qtd_Peças_Total_Nota",
    n.vl_devolvido_total AS "Valor_Total_Nota_R$"
  FROM devolucoes_notas n
  LEFT JOIN (
    SELECT filial_codigo, rca_id, numnota, COUNT(*) AS total_itens, SUM(qtdev) AS total_pecas
    FROM devolucoes_itens
    GROUP BY filial_codigo, rca_id, numnota
  ) sub ON sub.filial_codigo = n.filial_codigo AND sub.rca_id = n.rca_id AND sub.numnota = n.numnota
  ORDER BY n.filial_codigo, n.supervisor_nome, n.vl_devolvido_total DESC
`).all();

const wsNotas = XLSX.utils.json_to_sheet(notas);
XLSX.utils.book_append_sheet(wb, wsNotas, 'Devoluções_Notas');

// -------------------------------------------------------------
// ABA 3: Devoluções por Filial e Motivo (Filial, Motivo, Qtd, Peças, Valor)
// -------------------------------------------------------------
const devFilialMotivo = db.prepare(`
  SELECT 
    filial_codigo AS "Filial",
    motivo AS "Motivo_Devolução",
    COUNT(DISTINCT numnota) AS "Qtd_Notas_Afetadas",
    COUNT(*) AS "Qtd_Itens_Devolvidos",
    SUM(qtdev) AS "Qtd_Peças_Unidades",
    ROUND(SUM(vl_devolvido), 2) AS "Valor_Total_Devolvido_R$"
  FROM devolucoes_itens
  GROUP BY filial_codigo, motivo
  ORDER BY filial_codigo, "Valor_Total_Devolvido_R$" DESC
`).all();

const wsDevFilialMotivo = XLSX.utils.json_to_sheet(devFilialMotivo);
XLSX.utils.book_append_sheet(wb, wsDevFilialMotivo, 'Devoluções_Filial_Motivo');

// -------------------------------------------------------------
// ABA 4: Top 3 Vendedores que Mais Cadastram por Filial
// -------------------------------------------------------------
const top3Filial = db.prepare(`
  WITH ranked AS (
    SELECT 
      filial_codigo AS "Filial",
      ROW_NUMBER() OVER (PARTITION BY filial_codigo ORDER BY COUNT(*) DESC) AS "Posição_Ranking",
      vendedor_linkup AS "Vendedor_LinkUp",
      rca_nome AS "Nome_RCA_Oficial",
      supervisor_nome AS "Supervisor",
      COUNT(*) AS "Total_Novos_Cadastros",
      SUM(CASE WHEN status = 'Finalizado' THEN 1 ELSE 0 END) AS "Cadastros_Finalizados",
      SUM(CASE WHEN em_aberto = 1 THEN 1 ELSE 0 END) AS "Cadastros_Em_Aberto",
      ROUND(AVG(tempo_dias), 1) AS "Lead_Time_Médio_Dias",
      ROUND(CAST(SUM(CASE WHEN status = 'Finalizado' THEN 1 ELSE 0 END) AS REAL) / COUNT(*) * 100, 1) AS "Taxa_Aprovação_Pct"
    FROM cadastros_linkup
    WHERE tipo = 'Novo Cliente' AND filial_codigo != 'A DEFINIR'
    GROUP BY filial_codigo, vendedor_linkup
  )
  SELECT * FROM ranked WHERE "Posição_Ranking" <= 3
  ORDER BY "Filial", "Posição_Ranking"
`).all();

const wsTop3 = XLSX.utils.json_to_sheet(top3Filial);
XLSX.utils.book_append_sheet(wb, wsTop3, 'Top3_Cadastros_Por_Filial');

// -------------------------------------------------------------
// ABA 5: Performance e Tempo de Aprovação por Responsável (LinkUp SLA)
// -------------------------------------------------------------
const aprovadores = db.prepare(`
  SELECT 
    COALESCE(NULLIF(responsavel_linkup, ''), 'Aguardando Atribuição / Sem Responsável') AS "Aprovador_Responsável",
    responsavel_email AS "E-mail_Responsável",
    COUNT(*) AS "Total_Cadastros_Atribuídos",
    SUM(CASE WHEN status = 'Finalizado' THEN 1 ELSE 0 END) AS "Cadastros_Aprovados_Finalizados",
    SUM(CASE WHEN em_aberto = 1 THEN 1 ELSE 0 END) AS "Pendentes_Falta_Aprovar",
    SUM(CASE WHEN status = 'Não Realizado' THEN 1 ELSE 0 END) AS "Recusados_Não_Realizados",
    ROUND(AVG(CASE WHEN status = 'Finalizado' THEN tempo_dias ELSE NULL END), 1) AS "Tempo_Médio_Aprovação_Dias",
    ROUND(AVG(CASE WHEN status = 'Finalizado' THEN tempo_horas ELSE NULL END), 1) AS "Tempo_Médio_Aprovação_Horas",
    ROUND(MIN(CASE WHEN status = 'Finalizado' THEN tempo_dias ELSE NULL END), 1) AS "Menor_Tempo_Dias",
    ROUND(MAX(CASE WHEN status = 'Finalizado' THEN tempo_dias ELSE NULL END), 1) AS "Maior_Tempo_Dias",
    ROUND(CAST(SUM(CASE WHEN status = 'Finalizado' THEN 1 ELSE 0 END) AS REAL) / COUNT(*) * 100, 1) AS "Taxa_Aprovação_Pct"
  FROM cadastros_linkup
  WHERE tipo = 'Novo Cliente'
  GROUP BY responsavel_linkup
  ORDER BY "Total_Cadastros_Atribuídos" DESC
`).all();

const wsAprovadores = XLSX.utils.json_to_sheet(aprovadores);
XLSX.utils.book_append_sheet(wb, wsAprovadores, 'SLA_Aprovadores_Cadastros');

// -------------------------------------------------------------
// ABA 6: O Que Falta Aprovar Hoje (Pendências Nominais)
// -------------------------------------------------------------
const faltaAprovar = db.prepare(`
  SELECT 
    id AS "ID_LinkUp",
    filial_codigo AS "Filial",
    COALESCE(NULLIF(responsavel_linkup, ''), 'Aguardando Atribuição') AS "Com_Quem_Está_Pendente",
    responsavel_email AS "Email_Responsável",
    status AS "Status_Atual",
    nome_cliente AS "Razão_Social_Cliente",
    cpf_cnpj AS "CNPJ_CPF",
    cidade AS "Cidade",
    vendedor_linkup AS "Vendedor_Solicitante",
    rca_nome AS "Nome_RCA_Oficial",
    supervisor_nome AS "Supervisor",
    criado_em AS "Data_Criação",
