    atualizado_em AS "Última_Movimentação"
  FROM cadastros_linkup
  WHERE tipo = 'Novo Cliente' AND em_aberto = 1
  ORDER BY tempo_dias DESC
`).all();

const wsFaltaAprovar = XLSX.utils.json_to_sheet(faltaAprovar);
XLSX.utils.book_append_sheet(wb, wsFaltaAprovar, 'Falta_Aprovar_Pendentes');

// -------------------------------------------------------------
// ABA 7: Novos Cadastros LinkUp Completo
// -------------------------------------------------------------
const novosCadastros = db.prepare(`
  SELECT 
    id AS "ID_LinkUp",
    filial_codigo AS "Filial",
    gerente_nome AS "Gerente",
    supervisor_nome AS "Supervisor",
