const fs = require('fs');
const path = require('path');
const readline = require('readline');
const Database = require('better-sqlite3');

const db = new Database(path.join(__dirname, 'pedidos_historico_ceven.db'));
const rfCsvPath = path.join(__dirname, 'clientes_rf_2026-09-12 (1).csv');

function cleanCnpj(val) {
  if (!val) return '';
  const num = String(val).replace(/\D/g, '');
  if (!num) return '';
  return num.length >= 14 ? num.slice(-14) : num.padStart(14, '0');
}

async function runAudit() {
  console.log('========================================================================');
  console.log('🔍 AUDITORIA: CNPJs DE TCV E TSJ vs CLIENTES RF 2026');
  console.log('========================================================================');

  // Listar tabelas do banco
  const tables = db.prepare("SELECT name FROM sqlite_master WHERE type='table'").all();
  console.log('Tabelas no banco:', tables.map(t => t.name));

  // 1. Carregar todos os CNPJs únicos da planilha Clientes RF
  console.log(`\nLendo arquivo Clientes RF: ${rfCsvPath}...`);
  const cnpjsRF = new Set();
  const rl = readline.createInterface({
    input: fs.createReadStream(rfCsvPath, { encoding: 'utf8' }),
    crlfDelay: Infinity
  });

  let lineCount = 0;
  let cnpjColIdx = 4; // Coluna 4 é 'cnpj'

  for await (const line of rl) {
    lineCount++;
    if (lineCount === 1) {
      const headers = line.split(';');
      console.log(`Header[4]: "${headers[4]}"`);
      continue;
    }

    const cols = line.split(';');
    if (cols[cnpjColIdx]) {
      const limpo = cleanCnpj(cols[cnpjColIdx].replace(/"/g, ''));
      if (limpo) cnpjsRF.add(limpo);
    }
  }

  console.log(`Total de linhas lidas no Clientes RF: ${lineCount}`);
  console.log(`Total de CNPJs únicos no Clientes RF: ${cnpjsRF.size}`);

  // Testar se as tabelas existem
  const hasPedidos = tables.some(t => t.name === 'pedidos');
  const hasDevolucoes = tables.some(t => t.name === 'devolucoes_notas');
  const hasLinkup = tables.some(t => t.name === 'cadastros_linkup');

  // 2. Tabela de Pedidos
  if (hasPedidos) {
    const pedidosTCV_TSJ = db.prepare(`
      SELECT DISTINCT filial_codigo, id_cliente, nome_cliente, cnpj
      FROM pedidos
      WHERE filial_codigo IN ('TCV', 'TSJ') AND cnpj IS NOT NULL AND cnpj != ''
    `).all();

    console.log(`\n--- 1. AUDITORIA EM PEDIDOS (TCV e TSJ) ---`);
    console.log(`Total de clientes com pedidos em TCV e TSJ: ${pedidosTCV_TSJ.length}`);

    let pedidosEncontrados = 0;
    let pedidosNaoEncontrados = [];

    for (const c of pedidosTCV_TSJ) {
      const limpo = cleanCnpj(c.cnpj);
      if (cnpjsRF.has(limpo)) {
        pedidosEncontrados++;
      } else {
        pedidosNaoEncontrados.push(c);
      }
    }

    console.log(`✅ Presentes no Clientes RF: ${pedidosEncontrados} (${(pedidosEncontrados / pedidosTCV_TSJ.length * 100).toFixed(2)}%)`);
    console.log(`❌ NÃO presentes no Clientes RF: ${pedidosNaoEncontrados.length}`);

    if (pedidosNaoEncontrados.length > 0) {
      console.log('\nAmostra de clientes com pedidos NÃO encontrados no Clientes RF:');
      console.table(pedidosNaoEncontrados.slice(0, 10));
    }
  }

  // 3. Tabela de Devoluções
  if (hasDevolucoes) {
    const devolucoesTCV_TSJ = db.prepare(`
      SELECT DISTINCT filial_codigo, codcli, nomecli, cnpj
      FROM devolucoes_notas
      WHERE filial_codigo IN ('TCV', 'TSJ') AND cnpj IS NOT NULL AND cnpj != ''
    `).all();

    console.log(`\n--- 2. AUDITORIA EM DEVOLUÇÕES (TCV e TSJ) ---`);
    console.log(`Total de clientes com devoluções em TCV e TSJ: ${devolucoesTCV_TSJ.length}`);

    let devEncontrados = 0;
    let devNaoEncontrados = [];

    for (const c of devolucoesTCV_TSJ) {
      const limpo = cleanCnpj(c.cnpj);
      if (cnpjsRF.has(limpo)) {
        devEncontrados++;
      } else {
        devNaoEncontrados.push(c);
      }
    }

    console.log(`✅ Presentes no Clientes RF: ${devEncontrados} (${(devEncontrados / devolucoesTCV_TSJ.length * 100).toFixed(2)}%)`);
    console.log(`❌ NÃO presentes no Clientes RF: ${devNaoEncontrados.length}`);

    if (devNaoEncontrados.length > 0) {
      console.log('\nAmostra de devoluções NÃO encontradas no Clientes RF:');
      console.table(devNaoEncontrados.slice(0, 10));
    }
  }

  // 4. Novos Cadastros LinkUp
  if (hasLinkup) {
    const linkupTCV_TSJ = db.prepare(`
      SELECT DISTINCT filial_codigo, id, nome_cliente, cpf_cnpj, status, criado_em
      FROM cadastros_linkup
      WHERE filial_codigo IN ('TCV', 'TSJ') AND cpf_cnpj IS NOT NULL AND cpf_cnpj != ''
    `).all();

    console.log(`\n--- 3. AUDITORIA EM NOVOS CADASTROS LINKUP (TCV e TSJ) ---`);
    console.log(`Total de clientes cadastrados via LinkUp em TCV e TSJ: ${linkupTCV_TSJ.length}`);

    let linkupEncontrados = 0;
    let linkupNaoEncontrados = [];

    for (const c of linkupTCV_TSJ) {
      const limpo = cleanCnpj(c.cpf_cnpj);
      if (cnpjsRF.has(limpo)) {
        linkupEncontrados++;
      } else {
        linkupNaoEncontrados.push(c);
      }
    }

    console.log(`✅ Presentes no Clientes RF: ${linkupEncontrados} (${(linkupEncontrados / linkupTCV_TSJ.length * 100).toFixed(2)}%)`);
    console.log(`❌ NÃO presentes no Clientes RF: ${linkupNaoEncontrados.length}`);

    if (linkupNaoEncontrados.length > 0) {
      console.log('\nAmostra de novos cadastros LinkUp NÃO encontrados no Clientes RF:');
      console.table(linkupNaoEncontrados.slice(0, 10));
    }
  }
}

