const fs = require('fs');
const path = require('path');
const readline = require('readline');
const Database = require('better-sqlite3');

const db = new Database(path.join(__dirname, 'pedidos_historico_ceven.db'));
const rfCsvPath = path.join(__dirname, 'clientes_rf_2026-09-12 (1).csv');

function cleanCnpj(val) {
  if (!val) return '';
  const num = String(val).replace(/\D/g, '');
  if (!num) return '';
  return num.length >= 14 ? num.slice(-14) : num.padStart(14, '0');
}

async function runAudit() {
  console.log('========================================================================');
  console.log('🔍 AUDITORIA CRÍTICA: CNPJs DE TCV E TSJ vs CLIENTES RF 2026');
  console.log('========================================================================');

  // 1. Carregar todos os CNPJs únicos da planilha Clientes RF
  console.log(`Lendo arquivo Clientes RF: ${rfCsvPath}...`);
  const cnpjsRF = new Set();
  const cnpjsRFMap = new Map(); // cnpj -> razao_social
  const rl = readline.createInterface({
    input: fs.createReadStream(rfCsvPath, { encoding: 'utf8' }),
    crlfDelay: Infinity
  });

  let lineCount = 0;
  let cnpjColIdx = 4; // Coluna 'cnpj'
  let razaoColIdx = 5; // Coluna 'razao_social'
  let filialColIdx = 25; // Coluna 'filiais_cnpj'

  for await (const line of rl) {
    lineCount++;
    if (lineCount === 1) continue;

    const cols = line.split(';');
    if (cols[cnpjColIdx]) {
      const limpo = cleanCnpj(cols[cnpjColIdx].replace(/"/g, ''));
      if (limpo) {
        cnpjsRF.add(limpo);
        if (!cnpjsRFMap.has(limpo)) {
          cnpjsRFMap.set(limpo, {
            razao: cols[razaoColIdx] ? cols[razaoColIdx].replace(/"/g, '').trim() : '',
            filiais: cols[filialColIdx] ? cols[filialColIdx].replace(/"/g, '').trim() : ''
          });
        }
      }
    }
  }

  console.log(`Total de linhas lidas no Clientes RF: ${lineCount}`);
  console.log(`Total de CNPJs únicos no Clientes RF: ${cnpjsRF.size}`);

  // 2. Clientes da Carteira / Roteiro em TCV e TSJ
  const clientesCarteira = db.prepare(`
    SELECT DISTINCT filial_codigo, id_cliente, nome_cliente, razao_social, cnpj
    FROM clientes_roteiro
    WHERE filial_codigo IN ('TCV', 'TSJ') AND cnpj IS NOT NULL AND cnpj != ''
  `).all();

  console.log(`\n------------------------------------------------------------------------`);
  console.log(`📊 1. CARTEIRA DE CLIENTES (ROTEIROS TCV E TSJ)`);
  console.log(`------------------------------------------------------------------------`);
  console.log(`Total de clientes únicos na carteira de TCV e TSJ: ${clientesCarteira.length}`);

  let carteiraEncontrados = 0;
  let carteiraNaoEncontrados = [];

  for (const c of clientesCarteira) {
    const limpo = cleanCnpj(c.cnpj);
    if (cnpjsRF.has(limpo)) {
      carteiraEncontrados++;
    } else {
      carteiraNaoEncontrados.push(c);
    }
  }

  const pctCarteira = (carteiraEncontrados / clientesCarteira.length * 100).toFixed(2);
  console.log(`✅ Presentes no Clientes RF: ${carteiraEncontrados} (${pctCarteira}%)`);
  console.log(`❌ NÃO presentes no Clientes RF: ${carteiraNaoEncontrados.length}`);

  if (carteiraNaoEncontrados.length > 0) {
    console.log('\nExemplo de clientes da carteira que NÃO estão no Clientes RF:');
    console.table(carteiraNaoEncontrados.slice(0, 10));
  }

  // 3. Clientes que tiveram PEDIDOS em TCV e TSJ
  const clientesPedidos = db.prepare(`
    SELECT DISTINCT p.filial_codigo, p.id_cliente, c.nome_cliente, c.cnpj
    FROM pedidos p
    LEFT JOIN clientes_roteiro c ON c.filial_codigo = p.filial_codigo AND c.id_cliente = p.id_cliente
    WHERE p.filial_codigo IN ('TCV', 'TSJ') AND c.cnpj IS NOT NULL AND c.cnpj != ''
  `).all();

  console.log(`\n------------------------------------------------------------------------`);
  console.log(`📦 2. CLIENTES COM PEDIDOS EMITIDOS (TCV E TSJ)`);
  console.log(`------------------------------------------------------------------------`);
  console.log(`Total de clientes com pedidos em TCV e TSJ: ${clientesPedidos.length}`);

  let pedidosEncontrados = 0;
  let pedidosNaoEncontrados = [];

  for (const c of clientesPedidos) {
    const limpo = cleanCnpj(c.cnpj);
    if (cnpjsRF.has(limpo)) {
      pedidosEncontrados++;
    } else {
      pedidosNaoEncontrados.push(c);
    }
  }

  const pctPedidos = (pedidosEncontrados / clientesPedidos.length * 100).toFixed(2);
  console.log(`✅ Presentes no Clientes RF: ${pedidosEncontrados} (${pctPedidos}%)`);
  console.log(`❌ NÃO presentes no Clientes RF: ${pedidosNaoEncontrados.length}`);

  if (pedidosNaoEncontrados.length > 0) {
    console.log('\nExemplo de clientes com pedidos NÃO encontrados no Clientes RF:');
    console.table(pedidosNaoEncontrados.slice(0, 10));
  }

  // 4. Clientes com DEVOLUÇÕES em TCV e TSJ
  const clientesDevolucoes = db.prepare(`
    SELECT DISTINCT filial_codigo, codcli, nomecli, cnpj
    FROM devolucoes_notas
    WHERE filial_codigo IN ('TCV', 'TSJ') AND cnpj IS NOT NULL AND cnpj != ''
  `).all();

  console.log(`\n------------------------------------------------------------------------`);
  console.log(`↩️ 3. CLIENTES COM DEVOLUÇÕES NO MÊS (TCV E TSJ)`);
  console.log(`------------------------------------------------------------------------`);
  console.log(`Total de clientes com devoluções em TCV e TSJ: ${clientesDevolucoes.length}`);

  let devEncontrados = 0;
  let devNaoEncontrados = [];

  for (const c of clientesDevolucoes) {
    const limpo = cleanCnpj(c.cnpj);
    if (cnpjsRF.has(limpo)) {
      devEncontrados++;
    } else {
      devNaoEncontrados.push(c);
    }
  }

  const pctDev = (devEncontrados / clientesDevolucoes.length * 100).toFixed(2);
  console.log(`✅ Presentes no Clientes RF: ${devEncontrados} (${pctDev}%)`);
  console.log(`❌ NÃO presentes no Clientes RF: ${devNaoEncontrados.length}`);

  if (devNaoEncontrados.length > 0) {
    console.log('\nExemplo de clientes com devolução NÃO encontrados no Clientes RF:');
    console.table(devNaoEncontrados.slice(0, 10));
  }

  // 5. Clientes de NOVOS CADASTROS LINKUP em TCV e TSJ
  const clientesLinkup = db.prepare(`
    SELECT DISTINCT filial_codigo, id, nome_cliente, cpf_cnpj, status, criado_em
    FROM cadastros_linkup
    WHERE filial_codigo IN ('TCV', 'TSJ') AND tipo = 'Novo Cliente' AND cpf_cnpj IS NOT NULL AND cpf_cnpj != ''
  `).all();

  console.log(`\n------------------------------------------------------------------------`);
  console.log(`📝 4. NOVOS CADASTROS SOLICITADOS NO LINKUP (TCV E TSJ)`);
  console.log(`------------------------------------------------------------------------`);
  console.log(`Total de solicitações de novos clientes no LinkUp em TCV e TSJ: ${clientesLinkup.length}`);

  let linkupEncontrados = 0;
  let linkupNaoEncontrados = [];

  for (const c of clientesLinkup) {
    const limpo = cleanCnpj(c.cpf_cnpj);
    if (cnpjsRF.has(limpo)) {
      linkupEncontrados++;
    } else {
      linkupNaoEncontrados.push(c);
    }
  }

  const pctLinkup = (linkupEncontrados / clientesLinkup.length * 100).toFixed(2);
  console.log(`✅ Já presentes no Clientes RF: ${linkupEncontrados} (${pctLinkup}%)`);
  console.log(`❌ NÃO presentes no Clientes RF (cadastros muito recentes/pendentes): ${linkupNaoEncontrados.length}`);

  if (linkupNaoEncontrados.length > 0) {
    console.log('\nExemplo de novos cadastros LinkUp que NÃO estão no arquivo Clientes RF:');
    console.table(linkupNaoEncontrados.slice(0, 10));
  }

  // 6. Resumo Consolidado
  console.log('\n========================================================================');
  console.log('🏁 RESUMO CONSOLIDADO DA AUDITORIA');
  console.log('========================================================================');
  console.log(`1. Carteira Total (Roteiros TCV e TSJ): ${pctCarteira}% presentes (${carteiraEncontrados}/${clientesCarteira.length})`);
  console.log(`2. Clientes com Pedidos (TCV e TSJ):    ${pctPedidos}% presentes (${pedidosEncontrados}/${clientesPedidos.length})`);
  console.log(`3. Clientes com Devoluções (TCV e TSJ):  ${pctDev}% presentes (${devEncontrados}/${clientesDevolucoes.length})`);
  console.log(`4. Novos Cadastros LinkUp (TCV e TSJ):  ${pctLinkup}% presentes (${linkupEncontrados}/${clientesLinkup.length})`);
}

runAudit().catch(console.error);

