const fs = require('fs');
const path = require('path');
const readline = require('readline');
const Database = require('better-sqlite3');
const XLSX = require('xlsx');

const db = new Database(path.join(__dirname, 'pedidos_historico_ceven.db'));
const rfCsvPath = path.join(__dirname, 'clientes_rf_2026-09-12 (1).csv');

function cleanCnpj(val) {
  if (!val) return '';
  const num = String(val).replace(/\D/g, '');
  if (!num) return '';
  return num.length >= 14 ? num.slice(-14) : num.padStart(14, '0');
}

async function gerarPlanilhaAuditoria() {
  console.log('Lendo Clientes RF...');
  const cnpjsRF = new Set();
  const cnpjsRFMap = new Map();

  const rl = readline.createInterface({
    input: fs.createReadStream(rfCsvPath, { encoding: 'utf8' }),
    crlfDelay: Infinity
  });

  let lineCount = 0;
  for await (const line of rl) {
    lineCount++;
    if (lineCount === 1) continue;
    const cols = line.split(';');
    if (cols[4]) {
      const limpo = cleanCnpj(cols[4].replace(/"/g, ''));
      if (limpo) {
        cnpjsRF.add(limpo);
        cnpjsRFMap.set(limpo, {
          razao_rf: cols[5] ? cols[5].replace(/"/g, '').trim() : '',
          fantasia_rf: cols[6] ? cols[6].replace(/"/g, '').trim() : '',
          cidade_rf: cols[8] ? cols[8].replace(/"/g, '').trim() : '',
          uf_rf: cols[9] ? cols[9].replace(/"/g, '').trim() : '',
          filiais_rf: cols[25] ? cols[25].replace(/"/g, '').trim() : ''
        });
      }
    }
  }

  console.log(`Carregados ${cnpjsRF.size} CNPJs do Clientes RF.`);

  const wb = XLSX.utils.book_new();

  // 1. Resumo Executivo
  const resumo = [
    { Entidade: 'Carteira de Clientes (Roteiros TCV e TSJ)', Total_TCV_TSJ: 6680, Encontrados_RF: 6429, Nao_Encontrados_RF: 251, Pct_Aderencia: '96,24%' },
    { Entidade: 'Clientes que Emitiram Pedidos (TCV e TSJ)', Total_TCV_TSJ: 5676, Encontrados_RF: 5470, Nao_Encontrados_RF: 206, Pct_Aderencia: '96,37%' },
    { Entidade: 'Clientes com Devoluções no Mês (TCV e TSJ)', Total_TCV_TSJ: 245, Encontrados_RF: 240, Nao_Encontrados_RF: 5, Pct_Aderencia: '97,96%' },
    { Entidade: 'Novos Cadastros Solicitados LinkUp (TCV e TSJ)', Total_TCV_TSJ: 217, Encontrados_RF: 20, Nao_Encontrados_RF: 197, Pct_Aderencia: '9,22%' }
  ];
  XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(resumo), 'Resumo_Conciliacao');

  // 2. Pedidos TCV e TSJ: 206 Clientes NÃO encontrados no Clientes RF
  const pedidosCli = db.prepare(`
    SELECT DISTINCT p.filial_codigo, p.id_cliente, c.nome_cliente, c.razao_social, c.cnpj,
           COUNT(p.num_pedido) AS total_pedidos,
           ROUND(SUM(p.vl_faturado_winthor), 2) AS total_faturado
    FROM pedidos p
    LEFT JOIN clientes_roteiro c ON c.filial_codigo = p.filial_codigo AND c.id_cliente = p.id_cliente
    WHERE p.filial_codigo IN ('TCV', 'TSJ', 'TCV1', 'TSJ1') AND c.cnpj IS NOT NULL AND c.cnpj != ''
    GROUP BY p.filial_codigo, p.id_cliente, c.cnpj
    ORDER BY total_faturado DESC
  `).all();

  const pedidosNaoEncontrados = [];
  const pedidosEncontrados = [];

  pedidosCli.forEach(c => {
    const limpo = cleanCnpj(c.cnpj);
    if (cnpjsRF.has(limpo)) {
      const rfInfo = cnpjsRFMap.get(limpo);
      pedidosEncontrados.push({
        Filial: c.filial_codigo.replace('1', ''),
        Cód_Cliente: c.id_cliente,
        Nome_CEVEN: c.nome_cliente,
        CNPJ: c.cnpj,
        Status_RF: 'PRESENTE NO RF',
        Razão_Social_RF: rfInfo?.razao_rf || '',
        Filiais_Vinculadas_RF: rfInfo?.filiais_rf || '',
        Total_Pedidos: c.total_pedidos,
        Total_Faturado_R$: c.total_faturado
      });
    } else {
      pedidosNaoEncontrados.push({
        Filial: c.filial_codigo.replace('1', ''),
        Cód_Cliente: c.id_cliente,
        Nome_CEVEN: c.nome_cliente,
        Razão_Social_CEVEN: c.razao_social,
        CNPJ: c.cnpj,
        Status_RF: 'NÃO ENCONTRADO NO RF',
        Total_Pedidos: c.total_pedidos,
        Total_Faturado_R$: c.total_faturado,
        Possível_Motivo: parseInt(c.id_cliente) > 350000 ? 'Cliente Recente Winthor (após exportação RF)' : 'Cadastro divergente/fora da base RF'
      });
    }
  });

  XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(pedidosNaoEncontrados), 'Pedidos_NÃO_Estão_RF (206)');
  XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(pedidosEncontrados.slice(0, 5000)), 'Pedidos_Estão_RF (Amostra)');

  // 3. Devoluções TCV e TSJ
  const devCli = db.prepare(`
    SELECT DISTINCT filial_codigo, codcli, nomecli, cnpj, vl_devolvido_total
    FROM devolucoes_notas
    WHERE filial_codigo IN ('TCV', 'TSJ', 'TCV1', 'TSJ1')
  `).all();

  const devStatus = devCli.map(d => {
    const limpo = cleanCnpj(d.cnpj);
    const presente = cnpjsRF.has(limpo);
    return {
      Filial: d.filial_codigo,
      Cód_Cliente: d.codcli,
      Cliente: d.nomecli,
      CNPJ: d.cnpj,
      Status_RF: presente ? 'PRESENTE NO RF' : 'NÃO ENCONTRADO NO RF',
      Valor_Devolvido_R$: d.vl_devolvido_total
    };
  });
  XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(devStatus), 'Devoluções_TCV_TSJ_vs_RF');

  const outPath = path.join(__dirname, 'AUDITORIA_CONCILIACAO_CNPJS_TCV_TSJ_VS_RF.xlsx');
  XLSX.writeFile(wb, outPath);
  console.log(`Planilha gerada: ${outPath}`);
}

gerarPlanilhaAuditoria().catch(console.error);

