function inspect(file) {
  console.log(`\n========================================================`);
  console.log(`🔍 INSPECIONANDO: ${file}`);
  console.log(`========================================================`);
  if (!fs.existsSync(file)) {
    console.log(`Arquivo ${file} não encontrado!`);
    return;
  }

  const data = JSON.parse(fs.readFileSync(file, 'utf8'));
  const entries = data.log.entries;
  console.log(`Total de requisições: ${entries.length}`);

  const endpoints = new Set();
  const interesting = [];

  entries.forEach(e => {
    const url = e.request.url;
    endpoints.add(e.request.method + ' ' + url.split('?')[0]);

    if (
      url.includes('prospec') || 
      url.includes('mapa') || 
      url.includes('ret') || 
      url.includes('compromisso') || 
      url.includes('cliente') ||
      url.includes('coordenad') ||
      url.includes('localizac')
    ) {
      let sample = '';
      if (e.response && e.response.content && e.response.content.text) {
        sample = e.response.content.text.slice(0, 300);
      }
      interesting.push({
        method: e.request.method,
        url: url,
        status: e.response.status,
        sample
      });
    }
  });

  console.log('\nEndpoints únicos encontrados:');
  Array.from(endpoints).forEach(ep => console.log('  ' + ep));

  console.log('\nRequisições com Mapa / RET / Prospecção / Localização:');
  interesting.forEach(item => {
    console.log(`\n👉 [${item.method}] ${item.url} (Status: ${item.status})`);
    console.log(`   Sample: ${item.sample.replace(/\n/g, ' ')}`);
  });
}

