const fs = require('fs');
const path = require('path');
const readline = require('readline');
const Database = require('better-sqlite3');

const db = new Database(path.join(__dirname, 'pedidos_historico_ceven.db'));
const rfCsvPath = path.join(__dirname, 'clientes_rf_2026-09-12 (1).csv');

function cleanCnpj(val) {
  if (!val) return '';
  const num = String(val).replace(/\D/g, '');
  if (!num) return '';
  return num.length >= 14 ? num.slice(-14) : num.padStart(14, '0');
}

async function exportarCnpjsNaoEncontrados() {
  const cnpjsRF = new Set();
  const rl = readline.createInterface({
    input: fs.createReadStream(rfCsvPath, { encoding: 'utf8' }),
    crlfDelay: Infinity
  });

  let lineCount = 0;
  for await (const line of rl) {
    lineCount++;
    if (lineCount === 1) continue;
    const cols = line.split(';');
    if (cols[4]) {
      const limpo = cleanCnpj(cols[4].replace(/"/g, ''));
      if (limpo) cnpjsRF.add(limpo);
    }
  }

  // Buscar clientes com pedidos em TCV e TSJ
  const pedidosCli = db.prepare(`
    SELECT DISTINCT 
      p.filial_codigo,
      p.id_cliente,
      c.nome_cliente,
      c.razao_social,
      c.cnpj,
      COUNT(p.num_pedido) AS total_pedidos,
      ROUND(SUM(p.vl_faturado_winthor), 2) AS total_faturado
    FROM pedidos p
    LEFT JOIN clientes_roteiro c ON c.filial_codigo = p.filial_codigo AND c.id_cliente = p.id_cliente
    WHERE p.filial_codigo IN ('TCV', 'TSJ', 'TCV1', 'TSJ1') AND c.cnpj IS NOT NULL AND c.cnpj != ''
    GROUP BY p.filial_codigo, p.id_cliente, c.cnpj
    ORDER BY total_faturado DESC
  `).all();

  const naoEncontrados = [];
  pedidosCli.forEach(c => {
    const limpo = cleanCnpj(c.cnpj);
    if (!cnpjsRF.has(limpo)) {
      naoEncontrados.push({
        filial: c.filial_codigo.replace('1', ''),
        cod_cliente: c.id_cliente,
        cnpj: c.cnpj,
        cnpj_limpo: limpo,
        nome_cliente: c.nome_cliente,
        razao_social: c.razao_social,
        total_pedidos: c.total_pedidos,
        total_faturado: c.total_faturado
      });
    }
  });

  console.log(`Total de CNPJs de clientes com pedidos não encontrados: ${naoEncontrados.length}`);

  // Gerar CSV
  const header = 'Filial;Cod_Cliente;CNPJ_Formatado;CNPJ_Numerico;Nome_Cliente;Razao_Social;Total_Pedidos;Total_Faturado_RS\n';
  const rows = naoEncontrados.map(n => 
    `"${n.filial}";"${n.cod_cliente}";"${n.cnpj}";"${n.cnpj_limpo}";"${n.nome_cliente.replace(/"/g, '""')}";"${(n.razao_social || '').replace(/"/g, '""')}";${n.total_pedidos};${n.total_faturado}`
  ).join('\n');

  const outCsv = path.join(__dirname, 'cnpjs_tcv_tsj_nao_encontrados_rf.csv');
  fs.writeFileSync(outCsv, header + rows, 'utf8');
  console.log(`Arquivo CSV gravado em: ${outCsv}`);

  // Exibir os top 20 maiores clientes não encontrados
  console.log('\nTop 20 maiores clientes em faturamento NÃO encontrados no Clientes RF:');
  console.table(naoEncontrados.slice(0, 20).map(n => ({
    Filial: n.filial,
    Cod: n.cod_cliente,
    CNPJ: n.cnpj,
    Cliente: n.nome_cliente.slice(0, 30),
    Pedidos: n.total_pedidos,
    Faturado_RS: n.total_faturado
  })));
}

exportarCnpjsNaoEncontrados().catch(console.error);

