// ========================================================================
// 2. ARQUIVO EXPANSÃO: EXPANSAO_CADASTROS_E_PROSPECTS.xlsx
// ========================================================================
console.log('\nGerando Arquivo 2: EXPANSAO_CADASTROS_E_PROSPECTS.xlsx...');
const wbExpansao = XLSX.utils.book_new();

// Aba 1: SLA dos Aprovadores (LinkUp)
const aprovadores = db.prepare(`
  SELECT 
    COALESCE(NULLIF(responsavel_linkup, ''), 'Aguardando Atribuição / Sem Responsável') AS "Aprovador_Responsável",
