  ORDER BY id DESC
`).all();
XLSX.utils.book_append_sheet(wbExpansao, XLSX.utils.json_to_sheet(novosCadastros), 'Novos_Cadastros_LinkUp');

// Aba 5: Base de Prospects do Radar CEVEN (Aba Mapa)
// Carregar o arquivo PROSPECTS_RCA_1022_HOJE.csv que tem os dados mapeados
const prospectsCsvPath = path.join(__dirname, '..', 'PROSPECTS_RCA_1022_HOJE.csv');
if (fs.existsSync(prospectsCsvPath)) {
  const csvRaw = fs.readFileSync(prospectsCsvPath, 'utf8');
  const lines = csvRaw.split('\n').filter(l => l.trim().length > 0);
  const headers = lines[0].split(';').map(h => h.replace(/"/g, '').trim());
  const rows = [];
  for (let i = 1; i < lines.length; i++) {
    const cols = lines[i].split(';').map(c => c.replace(/"/g, '').trim());
    const obj = {};
    headers.forEach((h, idx) => {
      obj[h] = cols[idx] || '';
    });
    rows.push(obj);
  }
  XLSX.utils.book_append_sheet(wbExpansao, XLSX.utils.json_to_sheet(rows), 'Prospects_Mapa_Exemplo_Radar');
  console.log(`✅ Aba de Prospects do Mapa adicionada com ${rows.length} registros.`);
}

const outExpansao = path.join(__dirname, 'EXPANSAO_CADASTROS_E_PROSPECTS.xlsx');
