XLSX.utils.book_append_sheet(wbExpansao, XLSX.utils.json_to_sheet(faltaAprovar), 'Falta_Aprovar_Pendentes');

const top3Filial = db.prepare(`
  WITH ranked AS (
    SELECT 
      filial_codigo AS "Filial",
      ROW_NUMBER() OVER (PARTITION BY filial_codigo ORDER BY COUNT(*) DESC) AS "Posição_Ranking",
      vendedor_linkup AS "Vendedor_LinkUp",
      rca_nome AS "Nome_RCA_Oficial",
      supervisor_nome AS "Supervisor",
      COUNT(*) AS "Total_Novos_Cadastros",
      SUM(CASE WHEN status = 'Finalizado' THEN 1 ELSE 0 END) AS "Cadastros_Finalizados",
      SUM(CASE WHEN em_aberto = 1 THEN 1 ELSE 0 END) AS "Cadastros_Em_Aberto",
      ROUND(AVG(tempo_dias), 1) AS "Lead_Time_Médio_Dias",
      ROUND(CAST(SUM(CASE WHEN status = 'Finalizado' THEN 1 ELSE 0 END) AS REAL) / COUNT(*) * 100, 1) AS "Taxa_Aprovação_Pct"
    FROM cadastros_linkup
    WHERE tipo = 'Novo Cliente' AND filial_codigo != 'A DEFINIR'
    GROUP BY filial_codigo, vendedor_linkup
  )
  SELECT * FROM ranked WHERE "Posição_Ranking" <= 3
  ORDER BY "Filial", "Posição_Ranking"
`).all().map(r => ({ ...r, Filial: normalizarFilial(r.Filial) }));
XLSX.utils.book_append_sheet(wbExpansao, XLSX.utils.json_to_sheet(top3Filial), 'Top3_Cadastros_Por_Filial');

const novosCadastros = db.prepare(`
  SELECT 
    id AS "ID_LinkUp",
    filial_codigo AS "Filial",
    gerente_nome AS "Gerente",
    supervisor_nome AS "Supervisor",
    rca_id AS "Cód_RCA",
    rca_nome AS "Vendedor_RCA",
    nome_cliente AS "Razão_Social_Cliente",
    cpf_cnpj AS "CNPJ_CPF",
    cidade AS "Cidade",
    status AS "Status_Atual",
    CASE WHEN em_aberto = 1 THEN 'SIM' ELSE 'NAO' END AS "Em_Aberto?",
    responsavel_linkup AS "Responsável_Atual",
    criado_em AS "Data_Criação",
    tempo_dias AS "Idade_Decorridos_Dias",
    tempo_horas AS "Tempo_Atendimento_Horas",
    data_finalizacao_br AS "Data_Finalização_Calculada",
    atualizado_em AS "Data_Última_Atualização"
  FROM cadastros_linkup
  WHERE tipo = 'Novo Cliente'
  ORDER BY id DESC
`).all().map(r => ({ ...r, Filial: normalizarFilial(r.Filial) }));
XLSX.utils.book_append_sheet(wbExpansao, XLSX.utils.json_to_sheet(novosCadastros), 'Novos_Cadastros_LinkUp');

// Aba 5: Prospects Mapa do Radar CEVEN com normalização ESTREITA da Filial
const prospectsCsvPath = path.join(__dirname, '..', 'PROSPECTS_RCA_1022_HOJE.csv');
if (fs.existsSync(prospectsCsvPath)) {
  const csvRaw = fs.readFileSync(prospectsCsvPath, 'utf8');
  const lines = csvRaw.split('\n').filter(l => l.trim().length > 0);
  const headers = lines[0].split(';').map(h => h.replace(/"/g, '').trim());
  const rows = [];
  for (let i = 1; i < lines.length; i++) {
    const cols = lines[i].split(';').map(c => c.replace(/"/g, '').trim());
    const obj = {};
    headers.forEach((h, idx) => {
      let val = cols[idx] || '';
      // Normalização estrita da filial: NUNCA colocar nome de cidade!
      if (h === 'Filial') {
        val = normalizarFilial(val);
      }
      obj[h] = val;
    });
    rows.push(obj);
  }
  XLSX.utils.book_append_sheet(wbExpansao, XLSX.utils.json_to_sheet(rows), 'Prospects_Mapa_Radar_CEVEN');
  console.log(`✅ Aba de Prospects adicionada com Filial normalizada estritamente para '${rows[0].Filial}'.`);
}

const outExpansao = path.join(__dirname, 'EXPANSAO_CADASTROS_E_PROSPECTS.xlsx');
XLSX.writeFile(wbExpansao, outExpansao);
console.log(`✅ Arquivo Expansão atualizado com sucesso: ${outExpansao}`);

