78:   const m = str.match(/^(\d{2})\/(\d{2})\/(\d{4})\s+(\d{2}):(\d{2})/);
79:   if (m) {
80:     const [_, d, mo, y, h, mi] = m;
81:     const dateObj = new Date(Date.UTC(parseInt(y), parseInt(mo) - 1, parseInt(d), parseInt(h), parseInt(mi)));
82:     return {
83:       iso: `${y}-${mo}-${d} ${h}:${mi}:00`,
84:       dataIso: `${y}-${mo}-${d}`,
85:       br: `${d}/${mo}/${y} ${h}:${mi}`,
86:       dataBr: `${d}/${mo}/${y}`,
87:       timestamp: dateObj.getTime(),
88:       dateObj
89:     };
90:   }
91:   return null;
92: }
