164: // 1. Extração de Cadastros LinkUp
165: async function extrairLinkUp() {
166:   console.log('\n======================================================');
167:   console.log('📡 1. EXTRAINDO HISTÓRICO COMPLETO DO LINKUP...');
168:   console.log('======================================================');
169: 
170:   // Construir mapa de correspondência de vendedores da hierarquia
171:   const repsList = [];
172:   HIERARQUIA.forEach(f => {
173:     f.supervisores.forEach(s => {
174:       s.rcas.forEach(r => {
175:         repsList.push({
176:           filial_codigo: f.filial,
177:           filial_key: f.codigoFilial,
178:           gerente_nome: f.gerentes,
179:           supervisor_id: s.supervisorId,
180:           supervisor_nome: s.supervisorNome,
181:           rca_id: String(r.rcaId),
182:           rca_nome: r.rcaNome,
183:           rca_norm: r.rcaNome.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/^(clt|pj)\s*-\s*/, '').trim()
184:         });
185:       });
186:     });
187:   });
188: 
189:   const url = 'https://ceven.drivetriunfante-locomotiva.com.br/api/linkup/solicitacoes?dias=365&limite=20000';
190:   const res = await fetchJson(url);
191:   const solicitacoes = res?.solicitacoes || [];
192:   console.log(`📥 Total de solicitações retornadas pela API LinkUp: ${solicitacoes.length}`);
193: 
194:   const insertLinkup = db.prepare(`
195:     INSERT OR REPLACE INTO cadastros_linkup (
196:       id, tipo, status, em_aberto, nome_cliente, cpf_cnpj, cidade,
197:       vendedor_linkup, vendedor_email, rca_id, rca_nome, filial_codigo,
198:       supervisor_nome, gerente_nome, responsavel_linkup, responsavel_email,
199:       criado_em, criado_em_data, atualizado_em, atualizado_em_data,
200:       tempo_horas, tempo_dias, data_finalizacao_calculada, data_finalizacao_br
201:     ) VALUES (
202:       ?, ?, ?, ?, ?, ?, ?,
203:       ?, ?, ?, ?, ?,
204:       ?, ?, ?, ?,
205:       ?, ?, ?, ?,
206:       ?, ?, ?, ?
207:     )
208:   `);
209: 
210:   const rowsToInsert = [];
211: 
212:   for (const s of solicitacoes) {
213:     const rawCnpj = (s.cpf_cnpj || '').trim();
214:     const vLink = (s.vendedor || '').replace(/_/g, ' ').trim();
215:     const vEmail = (s.vendedor_email || '').trim().toLowerCase();
216:     const respEmail = (s.responsavel_email || '').trim().toLowerCase();
217:     const vNorm = vLink.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();
218: 
219:     // Cruzar com hierarquia
220:     let matchedRep = repsList.find(r => {
221:       if (r.rca_norm === vNorm) return true;
222:       const partes = vNorm.split(/\s+/).filter(p => p.length > 2);
223:       if (partes.length >= 2 && partes.every(p => r.rca_norm.includes(p))) return true;
224:       return false;
225:     });
226: 
227:     let filial = matchedRep ? matchedRep.filial_codigo : null;
228:     let rcaId = matchedRep ? matchedRep.rca_id : '';
229:     let rcaNome = matchedRep ? matchedRep.rca_nome : vLink;
230:     let supNome = matchedRep ? matchedRep.supervisor_nome : '';
231:     let gerNome = matchedRep ? matchedRep.gerente_nome : '';
232: 
233:     // Se não encontrou por nome, tentar identificar a filial pelo e-mail
234:     if (!filial) {
235:       if (respEmail.startsWith('tsj') || vEmail.includes('tsj')) filial = 'TSJ';
236:       else if (respEmail.startsWith('tcg') || vEmail.includes('tcg')) filial = 'TCG';
237:       else if (respEmail.startsWith('tcv') || vEmail.includes('tcv')) filial = 'TCV';
238:       else if (respEmail.startsWith('tca') || vEmail.includes('tca')) filial = 'TCA';
239:       else if (respEmail.startsWith('tbe') || vEmail.includes('tbe')) filial = 'TBE';
240:       else if (respEmail.startsWith('tpa') || vEmail.includes('tpa')) filial = 'TPA';
241:       else if (respEmail.startsWith('tph') || vEmail.includes('tph')) filial = 'TPH';
242:       else if (respEmail.startsWith('tbl') || vEmail.includes('tbl')) filial = 'TBL';
243:       else if (respEmail.startsWith('mcd') || vEmail.includes('mcd')) filial = 'MCD';
244:       else if (respEmail.startsWith('api') || vEmail.includes('api')) filial = 'API';
245:       else if (respEmail.startsWith('abc') || vEmail.includes('abc')) filial = 'ABC';
246:     }
247: 
248:     // Tratamento de datas
249:     const dtCriado = parseDateTimeBR(s.criado_em);
250:     const dtAtualizado = parseDateTimeBR(s.atualizado_em);
251:     const horas = typeof s.tempo_horas === 'number' ? s.tempo_horas : parseFloat(s.tempo_horas) || 0;
252:     const dias = parseFloat((horas / 24).toFixed(1));
253: 
254:     // Cálculo da data de finalização
255:     // Regra solicitada: se criação foi dia 01 e finalizado com 4d, então finalizou dia 05
256:     let dataFinCalculada = '';
257:     let dataFinBR = '';
258:     if (dtCriado && horas > 0) {
259:       const finMs = dtCriado.timestamp + Math.round(horas * 3600 * 1000);
260:       const finDate = new Date(finMs);
261:       const fy = finDate.getUTCFullYear();
262:       const fmo = String(finDate.getUTCMonth() + 1).padStart(2, '0');
263:       const fd = String(finDate.getUTCDate()).padStart(2, '0');
264:       const fh = String(finDate.getUTCHours()).padStart(2, '0');
265:       const fmi = String(finDate.getUTCMinutes()).padStart(2, '0');
266: 
267:       dataFinCalculada = `${fy}-${fmo}-${fd} ${fh}:${fmi}:00`;
268:       dataFinBR = `${fd}/${fmo}/${fy} ${fh}:${fmi}`;
269:     } else if (dtAtualizado && s.status === 'Finalizado') {
270:       dataFinCalculada = dtAtualizado.iso;
271:       dataFinBR = dtAtualizado.br;
272:     }
273: 
274:     rowsToInsert.push([
275:       s.id,
276:       s.tipo || 'Novo Cliente',
277:       s.status || 'Pendente',
278:       s.em_aberto ? 1 : 0,
279:       s.nome_cliente || '',
280:       rawCnpj,
281:       s.cidade || '',
282:       vLink,
283:       vEmail,
284:       rcaId,
285:       rcaNome,
286:       filial || 'A DEFINIR',
287:       supNome,
288:       gerNome,
289:       s.responsavel || '',
290:       s.responsavel_email || '',
291:       s.criado_em || '',
292:       dtCriado ? dtCriado.dataIso : '',
293:       s.atualizado_em || '',
294:       dtAtualizado ? dtAtualizado.dataIso : '',
295:       horas,
296:       dias,
297:       dataFinCalculada,
298:       dataFinBR
299:     ]);
300:   }
301: 
302:   const insertMany = db.transaction((rows) => {
303:     for (const r of rows) insertLinkup.run(...r);
304:   });
305: 
306:   insertMany(rowsToInsert);
307:   console.log(`✅ ${rowsToInsert.length} solicitações inseridas no SQLite.`);
308: 
309:   return rowsToInsert;
310: }
