312: // 2. Extração de Devoluções de Todas as 11 Filiais
313: async function extrairDevolucoes() {
314:   console.log('\n======================================================');
315:   console.log('📦 2. EXTRAINDO DEVOLUÇÕES DE TODAS AS 11 FILIAIS...');
316:   console.log('======================================================');
317: 
318:   const todosRcas = [];
319:   HIERARQUIA.forEach(f => {
320:     f.supervisores.forEach(s => {
321:       s.rcas.forEach(r => {
322:         todosRcas.push({
323:           filial_codigo: f.filial,
324:           filial_key: f.codigoFilial,
325:           gerente_nome: f.gerentes,
326:           supervisor_id: s.supervisorId,
327:           supervisor_nome: s.supervisorNome,
328:           rca_id: r.rcaId,
329:           rca_nome: r.rcaNome
