331:       });
332:     });
333:   });
334: 
335:   console.log(`Total de ${todosRcas.length} RCAs para consultar em 11 filiais.`);
336: 
337:   const insertNota = db.prepare(`
338:     INSERT OR REPLACE INTO devolucoes_notas (
339:       chave_nota, filial_codigo, filial_key, rca_id, rca_nome,
340:       supervisor_id, supervisor_nome, gerente_nome, numnota,
341:       data_devolucao, data_devolucao_br, codcli, nomecli, cnpj,
342:       vl_devolvido_total, qtd_itens
343:     ) VALUES (
344:       ?, ?, ?, ?, ?,
345:       ?, ?, ?, ?,
346:       ?, ?, ?, ?, ?,
347:       ?, ?
348:     )
349:   `);
350: 
351:   const insertItem = db.prepare(`
352:     INSERT OR REPLACE INTO devolucoes_itens (
353:       chave_item, filial_codigo, rca_id, rca_nome, supervisor_nome,
354:       numnota, data_devolucao, data_devolucao_br, codcli, nomecli,
355:       cnpj, codprod, descricao, qtdev, vl_devolvido, motivo
356:     ) VALUES (
357:       ?, ?, ?, ?, ?,
358:       ?, ?, ?, ?, ?,
359:       ?, ?, ?, ?, ?, ?
360:     )
361:   `);
362: 
363:   let totalNotasEncontradas = 0;
364:   let totalItensEncontrados = 0;
365:   let totalValorDevolvido = 0;
366: 
367:   const notasParaGravar = [];
368:   const itensParaGravar = [];
369: 
370:   // Processar em lotes de 15 RCAs simultâneos
371:   const BATCH_SIZE = 15;
372:   for (let i = 0; i < todosRcas.length; i += BATCH_SIZE) {
373:     const batch = todosRcas.slice(i, i + BATCH_SIZE);
374:     process.stdout.write(`\rProcessando RCAs ${i + 1} a ${Math.min(i + BATCH_SIZE, todosRcas.length)} de ${todosRcas.length}...`);
375: 
376:     await Promise.all(batch.map(async (rca) => {
377:       const devUrl = `https://ceven.drivetriunfante-locomotiva.com.br/api/rca/devolucoes?filial=${rca.filial_key}&id=${rca.rca_id}`;
378:       const devList = await fetchJson(devUrl);
379: 
380:       if (Array.isArray(devList) && devList.length > 0) {
381:         for (const d of devList) {
382:           const numnota = String(d.numnota || d.nota || '').trim();
383:           if (!numnota) return;
384: 
385:           const vlNota = parseMoney(d.vl_devolvido || d.valor || d.total);
386:           const dtParsed = parseDateBR(d.data || d.data_nota);
387:           const codcli = String(d.codcli || d.id_cliente || '');
388:           const nomecli = String(d.nomecli || d.cliente || '');
389:           const cnpj = String(d.cnpj || '');
390: 
391:           const chaveNota = `${rca.filial_codigo}_${rca.rca_id}_${numnota}`;
392: 
393:           // Buscar os itens da nota fiscal devolvida
394:           const itensUrl = `https://ceven.drivetriunfante-locomotiva.com.br/api/rca/devolucoes/${numnota}?filial=${rca.filial_key}&id=${rca.rca_id}`;
395:           const itensList = await fetchJson(itensUrl);
396: 
397:           let qtdItensNaNota = 0;
398: 
399:           if (Array.isArray(itensList) && itensList.length > 0) {
400:             qtdItensNaNota = itensList.length;
401:             itensList.forEach((it, idx) => {
402:               const codprod = String(it.codprod || '').trim();
403:               const desc = String(it.descricao || '').trim();
404:               const qtdev = parseFloat(it.qtdev) || 0;
405:               const vlItem = parseMoney(it.vl_devolvido || it.valor);
406:               const motivo = String(it.motivo || 'NÃO INFORMADO').trim();
407: 
408:               const chaveItem = `${chaveNota}_${codprod}_${idx}`;
409: 
410:               itensParaGravar.push([
411:                 chaveItem,
412:                 rca.filial_codigo,
413:                 rca.rca_id,
414:                 rca.rca_nome,
415:                 rca.supervisor_nome,
416:                 numnota,
417:                 dtParsed ? dtParsed.iso : '',
418:                 dtParsed ? dtParsed.br : '',
419:                 codcli,
420:                 nomecli,
421:                 cnpj,
422:                 codprod,
423:                 desc,
424:                 qtdev,
425:                 vlItem,
426:                 motivo
427:               ]);
428: 
429:               totalItensEncontrados++;
430:             });
431:           }
432: 
433:           notasParaGravar.push([
434:             chaveNota,
435:             rca.filial_codigo,
436:             rca.filial_key,
437:             rca.rca_id,
438:             rca.rca_nome,
439:             rca.supervisor_id,
440:             rca.supervisor_nome,
441:             rca.gerente_nome,
442:             numnota,
443:             dtParsed ? dtParsed.iso : '',
444:             dtParsed ? dtParsed.br : '',
445:             codcli,
446:             nomecli,
447:             cnpj,
448:             vlNota,
449:             qtdItensNaNota
450:           ]);
451: 
452:           totalNotasEncontradas++;
453:           totalValorDevolvido += vlNota;
454:         }
455:       }
456:     }));
457:   }
458: 
459:   console.log(`\n\nGravando ${notasParaGravar.length} notas e ${itensParaGravar.length} itens no SQLite...`);
460: 
461:   const insertNotasTx = db.transaction((rows) => {
462:     for (const r of rows) insertNota.run(...r);
463:   });
464:   insertNotasTx(notasParaGravar);
465: 
466:   const insertItensTx = db.transaction((rows) => {
467:     for (const r of rows) insertItem.run(...r);
468:   });
469:   insertItensTx(itensParaGravar);
470: 
471:   console.log(`✅ Extração de devoluções concluída:`);
472:   console.log(`   - Notas Fiscais Devolvidas: ${totalNotasEncontradas}`);
473:   console.log(`   - Itens Devolvidos: ${totalItensEncontrados}`);
474:   console.log(`   - Valor Total Devolvido: R$ ${totalValorDevolvido.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}`);
475: }
