const https = require('https');
const http = require('http');
const fs = require('fs');
const path = require('path');
const Database = require('better-sqlite3');
const XLSX = require('xlsx');

const DB_PATH = path.join(__dirname, 'pedidos_historico_ceven.db');
const db = new Database(DB_PATH);
db.pragma('journal_mode = WAL');

const HIERARQUIA = JSON.parse(fs.readFileSync(path.join(__dirname, 'hierarquia_completa_ceven.json'), 'utf8'));

// ====================================================================
//  HELPERS
// ====================================================================
function fetchJson(url, retries = 3) {
  return new Promise((resolve) => {
    const mod = url.startsWith('https') ? https : http;
    function attempt(n) {
      const req = mod.get(url, {
        headers: {
          'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64)',
          'Referer': 'https://ceven.drivetriunfante-locomotiva.com.br/dashboard'
        },
        timeout: 15000,
        rejectUnauthorized: false
      }, (res) => {
        let data = '';
        res.on('data', chunk => data += chunk);
        res.on('end', () => {
          try { resolve(JSON.parse(data)); }
          catch(e) {
            if (n > 1) setTimeout(() => attempt(n - 1), 800);
            else resolve(null);
          }
        });
      });
      req.on('error', () => {
        if (n > 1) setTimeout(() => attempt(n - 1), 800);
        else resolve(null);
      });
      req.on('timeout', () => {
        req.destroy();
        if (n > 1) setTimeout(() => attempt(n - 1), 800);
        else resolve(null);
      });
    }
    attempt(retries);
  });
}

function parseMoney(val) {
  if (val === null || val === undefined) return 0;
  if (typeof val === 'number') return val;
  let str = String(val).replace('R$', '').replace('r$', '').trim();
  if (str.includes(',') && str.includes('.')) str = str.replace(/\./g, '').replace(',', '.');
  else if (str.includes(',')) str = str.replace(',', '.');
  const num = parseFloat(str);
  return isNaN(num) ? 0 : num;
}

function parseDateBR(str) {
  if (!str) return null;
  if (/^\d{4}-\d{2}-\d{2}/.test(str)) {
    const p = str.slice(0, 10).split('-');
    return { iso: `${p[0]}-${p[1]}-${p[2]}`, br: `${p[2]}/${p[1]}/${p[0]}` };
  }
  if (/^\d{2}\/\d{2}\/\d{4}/.test(str)) {
    const p = str.slice(0, 10).split('/');
    return { iso: `${p[2]}-${p[1]}-${p[0]}`, br: `${p[0]}/${p[1]}/${p[2]}` };
  }
  return null;
}

function parseDateTimeBR(str) {
  if (!str) return null;
  const m = str.match(/^(\d{2})\/(\d{2})\/(\d{4})\s+(\d{2}):(\d{2})/);
  if (m) {
    const [_, d, mo, y, h, mi] = m;
    const dateObj = new Date(Date.UTC(parseInt(y), parseInt(mo) - 1, parseInt(d), parseInt(h), parseInt(mi)));
    return {
      iso: `${y}-${mo}-${d} ${h}:${mi}:00`,
      dataIso: `${y}-${mo}-${d}`,
      br: `${d}/${mo}/${y} ${h}:${mi}`,
      dataBr: `${d}/${mo}/${y}`,
      timestamp: dateObj.getTime(),
      dateObj
    };
  }
  return null;
}

function normalizarFilial(val) {
  if (!val) return '';
  let str = String(val).trim().toUpperCase();
  if (str.includes('TSJ')) return 'TSJ';
  if (str.includes('TCV')) return 'TCV';
  if (str.includes('TBE')) return 'TBE';
  if (str.includes('ABC')) return 'ABC';
  if (str.includes('TPH')) return 'TPH';
  if (str.includes('MCD')) return 'MCD';
  if (str.includes('TCA')) return 'TCA';
  if (str.includes('API')) return 'API';
  if (str.includes('TCG')) return 'TCG';
  if (str.includes('TPA')) return 'TPA';
  if (str.includes('TBL')) return 'TBL';
  return str;
}

// ====================================================================
//  ETAPA 0: INICIALIZAR TABELAS
// ====================================================================
function initDatabase() {
  db.exec(`
    CREATE TABLE IF NOT EXISTS devolucoes_notas (
      chave_nota TEXT PRIMARY KEY,
      filial_codigo TEXT, filial_key TEXT,
      rca_id INTEGER, rca_nome TEXT,
      supervisor_id INTEGER, supervisor_nome TEXT, gerente_nome TEXT,
      numnota TEXT, data_devolucao TEXT, data_devolucao_br TEXT,
      codcli TEXT, nomecli TEXT, cnpj TEXT,
      vl_devolvido_total REAL, qtd_itens INTEGER
    );
    CREATE TABLE IF NOT EXISTS devolucoes_itens (
      chave_item TEXT PRIMARY KEY,
      filial_codigo TEXT, rca_id INTEGER, rca_nome TEXT, supervisor_nome TEXT,
      numnota TEXT, data_devolucao TEXT, data_devolucao_br TEXT,
      codcli TEXT, nomecli TEXT, cnpj TEXT,
      codprod TEXT, descricao TEXT, qtdev REAL, vl_devolvido REAL, motivo TEXT
    );
    CREATE TABLE IF NOT EXISTS cadastros_linkup (
      id INTEGER PRIMARY KEY,
      tipo TEXT, status TEXT, em_aberto INTEGER,
      nome_cliente TEXT, cpf_cnpj TEXT, cidade TEXT, estado TEXT,
      vendedor_linkup TEXT, vendedor_email TEXT,
      rca_id TEXT, rca_nome TEXT, filial_codigo TEXT,
      supervisor_nome TEXT, gerente_nome TEXT,
      responsavel_linkup TEXT, responsavel_email TEXT,
      criado_em TEXT, criado_em_data TEXT,
      atualizado_em TEXT, atualizado_em_data TEXT,
      tempo_horas REAL, tempo_dias REAL,
      data_finalizacao_calculada TEXT, data_finalizacao_br TEXT
    );
    CREATE TABLE IF NOT EXISTS ibge_municipios (
      id INTEGER PRIMARY KEY,
      nome TEXT, uf_sigla TEXT, uf_nome TEXT,
      mesorregiao TEXT, microrregiao TEXT,
      populacao_estimada INTEGER,
      pib_per_capita REAL,
      area_km2 REAL,
      densidade_demografica REAL
    );
  `);

  // Garantir que a coluna estado existe em cadastros_linkup
  try { db.exec("ALTER TABLE cadastros_linkup ADD COLUMN estado TEXT DEFAULT ''"); } catch(e) { /* coluna já existe */ }
}

// ====================================================================
//  ETAPA 1: EXTRAIR DEVOLUÇÕES (11 FILIAIS)
// ====================================================================
async function extrairDevolucoes() {
  console.log('\n' + '='.repeat(70));
  console.log('📦 ETAPA 1: EXTRAINDO DEVOLUÇÕES DE TODAS AS 11 FILIAIS...');
  console.log('='.repeat(70));

  const todosRcas = [];
  HIERARQUIA.forEach(f => {
    f.supervisores.forEach(s => {
      s.rcas.forEach(r => {
        todosRcas.push({
          filial_codigo: f.filial,
          filial_key: f.codigoFilial,
          gerente_nome: f.gerentes,
          supervisor_id: s.supervisorId,
          supervisor_nome: s.supervisorNome,
          rca_id: r.rcaId,
          rca_nome: r.rcaNome
        });
      });
    });
  });

  console.log(`Total de ${todosRcas.length} RCAs para consultar.`);

  const insertNota = db.prepare(`
    INSERT OR REPLACE INTO devolucoes_notas (
      chave_nota, filial_codigo, filial_key, rca_id, rca_nome,
      supervisor_id, supervisor_nome, gerente_nome, numnota,
      data_devolucao, data_devolucao_br, codcli, nomecli, cnpj,
      vl_devolvido_total, qtd_itens
    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
  `);

  const insertItem = db.prepare(`
    INSERT OR REPLACE INTO devolucoes_itens (
      chave_item, filial_codigo, rca_id, rca_nome, supervisor_nome,
      numnota, data_devolucao, data_devolucao_br, codcli, nomecli,
      cnpj, codprod, descricao, qtdev, vl_devolvido, motivo
    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
  `);

  let totalNotas = 0, totalItens = 0, totalValor = 0;
  const notasArr = [], itensArr = [];

  const BATCH_SIZE = 15;
  for (let i = 0; i < todosRcas.length; i += BATCH_SIZE) {
    const batch = todosRcas.slice(i, i + BATCH_SIZE);
    process.stdout.write(`\rProcessando RCAs ${i + 1}-${Math.min(i + BATCH_SIZE, todosRcas.length)} de ${todosRcas.length}...`);

    await Promise.all(batch.map(async (rca) => {
      const devUrl = `https://ceven.drivetriunfante-locomotiva.com.br/api/rca/devolucoes?filial=${rca.filial_key}&id=${rca.rca_id}`;
      const devList = await fetchJson(devUrl);

      if (Array.isArray(devList) && devList.length > 0) {
        for (const d of devList) {
          const numnota = String(d.numnota || d.nota || '').trim();
          if (!numnota) continue;

          const vlNota = parseMoney(d.vl_devolvido || d.valor || d.total);
          const dtParsed = parseDateBR(d.data || d.data_nota);
          const codcli = String(d.codcli || d.id_cliente || '');
          const nomecli = String(d.nomecli || d.cliente || '');
          const cnpj = String(d.cnpj || '');
          const chaveNota = `${rca.filial_codigo}_${rca.rca_id}_${numnota}`;

          const itensUrl = `https://ceven.drivetriunfante-locomotiva.com.br/api/rca/devolucoes/${numnota}?filial=${rca.filial_key}&id=${rca.rca_id}`;
          const itensList = await fetchJson(itensUrl);

          let qtdItensNaNota = 0;
          if (Array.isArray(itensList) && itensList.length > 0) {
            qtdItensNaNota = itensList.length;
            itensList.forEach((it, idx) => {
              const codprod = String(it.codprod || '').trim();
              const desc = String(it.descricao || '').trim();
              const qtdev = parseFloat(it.qtdev) || 0;
              const vlItem = parseMoney(it.vl_devolvido || it.valor);
              const motivo = String(it.motivo || 'NÃO INFORMADO').trim();
              const chaveItem = `${chaveNota}_${codprod}_${idx}`;

              itensArr.push([
                chaveItem, rca.filial_codigo, rca.rca_id, rca.rca_nome,
                rca.supervisor_nome, numnota,
                dtParsed ? dtParsed.iso : '', dtParsed ? dtParsed.br : '',
                codcli, nomecli, cnpj, codprod, desc, qtdev, vlItem, motivo
              ]);
              totalItens++;
            });
          }

          notasArr.push([
            chaveNota, rca.filial_codigo, rca.filial_key,
            rca.rca_id, rca.rca_nome,
            rca.supervisor_id, rca.supervisor_nome, rca.gerente_nome,
            numnota,
            dtParsed ? dtParsed.iso : '', dtParsed ? dtParsed.br : '',
            codcli, nomecli, cnpj, vlNota, qtdItensNaNota
          ]);
          totalNotas++;
          totalValor += vlNota;
        }
      }
    }));
  }

  console.log(`\n\nGravando ${notasArr.length} notas e ${itensArr.length} itens no SQLite...`);

  db.transaction((rows) => { for (const r of rows) insertNota.run(...r); })(notasArr);
  db.transaction((rows) => { for (const r of rows) insertItem.run(...r); })(itensArr);

  console.log(`✅ Devoluções: ${totalNotas} notas | ${totalItens} itens | R$ ${totalValor.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}`);
}

// ====================================================================
//  ETAPA 2: EXTRAIR CADASTROS LINKUP (com cidade e estado separados)
// ====================================================================
async function extrairLinkUp() {
  console.log('\n' + '='.repeat(70));
  console.log('📡 ETAPA 2: EXTRAINDO HISTÓRICO COMPLETO DO LINKUP...');
  console.log('='.repeat(70));

  const repsList = [];
  HIERARQUIA.forEach(f => {
    f.supervisores.forEach(s => {
      s.rcas.forEach(r => {
        repsList.push({
          filial_codigo: f.filial,
          filial_key: f.codigoFilial,
          gerente_nome: f.gerentes,
          supervisor_id: s.supervisorId,
          supervisor_nome: s.supervisorNome,
          rca_id: String(r.rcaId),
          rca_nome: r.rcaNome,
          rca_norm: r.rcaNome.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/^(clt|pj)\s*-\s*/, '').trim()
        });
      });
    });
  });

  const url = 'https://ceven.drivetriunfante-locomotiva.com.br/api/linkup/solicitacoes?dias=365&limite=20000';
  const res = await fetchJson(url);
  const solicitacoes = res?.solicitacoes || [];
  console.log(`📥 Total de solicitações retornadas pela API LinkUp: ${solicitacoes.length}`);

  const insertLinkup = db.prepare(`
    INSERT OR REPLACE INTO cadastros_linkup (
      id, tipo, status, em_aberto, nome_cliente, cpf_cnpj, cidade, estado,
      vendedor_linkup, vendedor_email, rca_id, rca_nome, filial_codigo,
      supervisor_nome, gerente_nome, responsavel_linkup, responsavel_email,
      criado_em, criado_em_data, atualizado_em, atualizado_em_data,
      tempo_horas, tempo_dias, data_finalizacao_calculada, data_finalizacao_br
    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
  `);

  const rowsToInsert = [];

  for (const s of solicitacoes) {
    const rawCnpj = (s.cpf_cnpj || '').trim();
    const vLink = (s.vendedor || '').replace(/_/g, ' ').trim();
    const vEmail = (s.vendedor_email || '').trim().toLowerCase();
    const respEmail = (s.responsavel_email || '').trim().toLowerCase();
    const vNorm = vLink.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();

    let matchedRep = repsList.find(r => {
      if (r.rca_norm === vNorm) return true;
      const partes = vNorm.split(/\s+/).filter(p => p.length > 2);
      if (partes.length >= 2 && partes.every(p => r.rca_norm.includes(p))) return true;
      return false;
    });

    let filial = matchedRep ? matchedRep.filial_codigo : null;
    let rcaId = matchedRep ? matchedRep.rca_id : '';
    let rcaNome = matchedRep ? matchedRep.rca_nome : vLink;
    let supNome = matchedRep ? matchedRep.supervisor_nome : '';
    let gerNome = matchedRep ? matchedRep.gerente_nome : '';

    if (!filial) {
      if (respEmail.startsWith('tsj') || vEmail.includes('tsj')) filial = 'TSJ';
      else if (respEmail.startsWith('tcg') || vEmail.includes('tcg')) filial = 'TCG';
      else if (respEmail.startsWith('tcv') || vEmail.includes('tcv')) filial = 'TCV';
      else if (respEmail.startsWith('tca') || vEmail.includes('tca')) filial = 'TCA';
      else if (respEmail.startsWith('tbe') || vEmail.includes('tbe')) filial = 'TBE';
      else if (respEmail.startsWith('tpa') || vEmail.includes('tpa')) filial = 'TPA';
      else if (respEmail.startsWith('tph') || vEmail.includes('tph')) filial = 'TPH';
      else if (respEmail.startsWith('tbl') || vEmail.includes('tbl')) filial = 'TBL';
      else if (respEmail.startsWith('mcd') || vEmail.includes('mcd')) filial = 'MCD';
      else if (respEmail.startsWith('api') || vEmail.includes('api')) filial = 'API';
      else if (respEmail.startsWith('abc') || vEmail.includes('abc')) filial = 'ABC';
    }

    // Separar cidade e estado
    let cidadeRaw = (s.cidade || '').trim();
    let cidade = cidadeRaw;
    let estado = '';

    // Tentar extrair estado: "Curitiba - PR", "Curitiba/PR", "Curitiba (PR)"
    const mEstado1 = cidadeRaw.match(/^(.+?)\s*[-\/]\s*([A-Z]{2})$/i);
    const mEstado2 = cidadeRaw.match(/^(.+?)\s*\(([A-Z]{2})\)$/i);
    if (mEstado1) {
      cidade = mEstado1[1].trim();
      estado = mEstado1[2].toUpperCase();
    } else if (mEstado2) {
      cidade = mEstado2[1].trim();
      estado = mEstado2[2].toUpperCase();
    }

    // Padronizar cidade: Primeira letra maiúscula
    cidade = cidade.replace(/\b\w/g, c => c.toUpperCase());

    const dtCriado = parseDateTimeBR(s.criado_em);
    const dtAtualizado = parseDateTimeBR(s.atualizado_em);
    const horas = typeof s.tempo_horas === 'number' ? s.tempo_horas : parseFloat(s.tempo_horas) || 0;
    const dias = parseFloat((horas / 24).toFixed(1));

    let dataFinCalculada = '', dataFinBR = '';
    if (dtCriado && horas > 0) {
      const finMs = dtCriado.timestamp + Math.round(horas * 3600 * 1000);
      const finDate = new Date(finMs);
      const fy = finDate.getUTCFullYear();
      const fmo = String(finDate.getUTCMonth() + 1).padStart(2, '0');
      const fd = String(finDate.getUTCDate()).padStart(2, '0');
      const fh = String(finDate.getUTCHours()).padStart(2, '0');
      const fmi = String(finDate.getUTCMinutes()).padStart(2, '0');
      dataFinCalculada = `${fy}-${fmo}-${fd} ${fh}:${fmi}:00`;
      dataFinBR = `${fd}/${fmo}/${fy} ${fh}:${fmi}`;
    } else if (dtAtualizado && s.status === 'Finalizado') {
      dataFinCalculada = dtAtualizado.iso;
      dataFinBR = dtAtualizado.br;
    }

    rowsToInsert.push([
      s.id, s.tipo || 'Novo Cliente', s.status || 'Pendente',
      s.em_aberto ? 1 : 0, s.nome_cliente || '', rawCnpj,
      cidade, estado,
      vLink, vEmail, rcaId, rcaNome, filial || 'A DEFINIR',
      supNome, gerNome, s.responsavel || '', s.responsavel_email || '',
      s.criado_em || '', dtCriado ? dtCriado.dataIso : '',
      s.atualizado_em || '', dtAtualizado ? dtAtualizado.dataIso : '',
      horas, dias, dataFinCalculada, dataFinBR
    ]);
  }

  db.transaction((rows) => { for (const r of rows) insertLinkup.run(...r); })(rowsToInsert);
  console.log(`✅ ${rowsToInsert.length} solicitações inseridas com cidade/estado separados.`);
}

// ====================================================================
//  ETAPA 3: BUSCAR DADOS IBGE (Municípios + População + PIB)
// ====================================================================
async function buscarDadosIBGE() {
  console.log('\n' + '='.repeat(70));
  console.log('🏛️  ETAPA 3: BUSCANDO DADOS IBGE DE TODOS OS MUNICÍPIOS...');
  console.log('='.repeat(70));

  // 1. Buscar todos os municípios com localidades
  console.log('Buscando lista de municípios...');
  const municipios = await fetchJson('https://servicodados.ibge.gov.br/api/v1/localidades/municipios');

  if (!Array.isArray(municipios) || municipios.length === 0) {
    console.log('⚠️ Falha ao buscar municípios do IBGE. Continuando sem dados demográficos.');
    return;
  }
  console.log(`📥 ${municipios.length} municípios obtidos.`);

  // 2. Buscar população estimada - usar Censo 2022 / estimativa mais recente
  // A API de agregados do IBGE: Estimativas populacionais - Tabela 6579
  console.log('Buscando estimativas de população (pode levar um momento)...');

  // Estados relevantes para o CEVEN: PR, SC, SP, MS, MT, GO, MG (para cobrir as 11 filiais)
  // Vamos buscar PR, SC, SP, MS, MT diretamente - os mais relevantes
  const estadosRelevantes = ['PR', 'SC', 'SP', 'MS', 'MT', 'GO', 'MG', 'RS'];
  const ufMap = {};
  municipios.forEach(m => {
    const uf = m.microrregiao?.mesorregiao?.UF?.sigla || '';
    ufMap[m.id] = {
      nome: m.nome,
      uf_sigla: uf,
      uf_nome: m.microrregiao?.mesorregiao?.UF?.nome || '',
      mesorregiao: m.microrregiao?.mesorregiao?.nome || '',
      microrregiao: m.microrregiao?.nome || ''
    };
  });

  // 3. Buscar população por UF relevante via API de agregados
  // Tabela 4714 = Censo 2022 | Variável 93 = População residente
  const populacaoMap = {};

  for (const uf of estadosRelevantes) {
    console.log(`  Buscando população ${uf}...`);
    try {
      const popUrl = `https://servicodados.ibge.gov.br/api/v3/agregados/4714/periodos/2022/variaveis/93?localidades=N6[N3[${getUFCode(uf)}]]`;
      const popData = await fetchJson(popUrl);

      if (popData && Array.isArray(popData) && popData[0]?.resultados?.[0]?.series) {
        popData[0].resultados[0].series.forEach(s => {
          const codMunicipio = parseInt(s.localidade?.id);
          const pop = parseInt(s.serie?.['2022']) || 0;
          if (codMunicipio && pop > 0) {
            populacaoMap[codMunicipio] = pop;
          }
        });
      }
    } catch(e) {
      console.log(`  ⚠️ Erro ao buscar população ${uf}: ${e.message}`);
    }
  }

  console.log(`📊 Populações coletadas para ${Object.keys(populacaoMap).length} municípios.`);

  // 4. Buscar PIB per capita por UF relevante
  // Tabela 5938 = PIB per capita | Variável 37 = PIB per capita
  const pibMap = {};
  for (const uf of estadosRelevantes) {
    console.log(`  Buscando PIB per capita ${uf}...`);
    try {
      const pibUrl = `https://servicodados.ibge.gov.br/api/v3/agregados/5938/periodos/2021/variaveis/37|513|517?localidades=N6[N3[${getUFCode(uf)}]]`;
      const pibData = await fetchJson(pibUrl);

      if (pibData && Array.isArray(pibData)) {
        pibData.forEach(variavel => {
          if (variavel.id === '37') { // PIB per capita
            variavel.resultados?.[0]?.series?.forEach(s => {
              const codMunicipio = parseInt(s.localidade?.id);
              const pib = parseFloat(s.serie?.['2021']) || 0;
              if (codMunicipio && pib > 0) {
                pibMap[codMunicipio] = pib;
              }
            });
          }
        });
      }
    } catch(e) {
      console.log(`  ⚠️ Erro ao buscar PIB ${uf}: ${e.message}`);
    }
  }

  console.log(`💰 PIB per capita coletado para ${Object.keys(pibMap).length} municípios.`);

  // 5. Inserir no banco
  const insertIBGE = db.prepare(`
    INSERT OR REPLACE INTO ibge_municipios (id, nome, uf_sigla, uf_nome, mesorregiao, microrregiao, populacao_estimada, pib_per_capita, area_km2, densidade_demografica)
    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
  `);

  let inserted = 0;
  const insertAll = db.transaction(() => {
    for (const [idStr, info] of Object.entries(ufMap)) {
      const id = parseInt(idStr);
      // Somente municípios dos estados relevantes
      if (estadosRelevantes.includes(info.uf_sigla)) {
        const pop = populacaoMap[id] || 0;
        const pib = pibMap[id] || 0;
        insertIBGE.run(id, info.nome, info.uf_sigla, info.uf_nome, info.mesorregiao, info.microrregiao, pop, pib, 0, 0);
        inserted++;
      }
    }
  });
  insertAll();

  console.log(`✅ ${inserted} municípios IBGE inseridos no banco (estados: ${estadosRelevantes.join(', ')}).`);
}

function getUFCode(sigla) {
  const map = {
    'RO': 11, 'AC': 12, 'AM': 13, 'RR': 14, 'PA': 15, 'AP': 16, 'TO': 17,
    'MA': 21, 'PI': 22, 'CE': 23, 'RN': 24, 'PB': 25, 'PE': 26, 'AL': 27,
    'SE': 28, 'BA': 29, 'MG': 31, 'ES': 32, 'RJ': 33, 'SP': 35,
    'PR': 41, 'SC': 42, 'RS': 43, 'MS': 50, 'MT': 51, 'GO': 52, 'DF': 53
  };
  return map[sigla] || 0;
}

