19: function fetchJson(url, retries = 3) {
20:   return new Promise((resolve) => {
21:     function attempt(n) {
22:       const req = https.get(url, {
23:         headers: { 'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64)', 'Referer': `${CEVEN_BASE}/dashboard` },
24:         timeout: 15000,
25:         rejectUnauthorized: false
26:       }, (res) => {
27:         let data = '';
28:         res.on('data', c => data += c);
29:         res.on('end', () => {
30:           try { resolve(JSON.parse(data)); }
31:           catch(e) {
32:             if (n > 1) setTimeout(() => attempt(n - 1), 600);
33:             else resolve(null);
34:           }
35:         });
36:       });
37:       req.on('error', () => { if (n > 1) setTimeout(() => attempt(n - 1), 600); else resolve(null); });
38:       req.on('timeout', () => { req.destroy(); if (n > 1) setTimeout(() => attempt(n - 1), 600); else resolve(null); });
39:     }
40:     attempt(retries);
41:   });
42: }
