const fs = require('fs');
const path = require('path');
const Database = require('better-sqlite3');

const db = new Database(path.join(__dirname, 'pedidos_historico_ceven.db'));

console.log('--- BUSCANDO FONTES DE DADOS DE CIDADE ---');

// 1. Checar tabelas no banco atual
const tables = db.prepare("SELECT name FROM sqlite_master WHERE type='table'").all();
for (const t of tables) {
  const cols = db.prepare(`PRAGMA table_info(${t.name})`).all();
  const hasCidade = cols.some(c => c.name.toLowerCase().includes('cidade') || c.name.toLowerCase().includes('municipio'));
  if (hasCidade) {
    console.log(`Tabela ${t.name} tem coluna de cidade/municipio.`);
  }
}

// 2. Checar outros arquivos .db no projeto
function findDbs(dir) {
  let res = [];
  for (const f of fs.readdirSync(dir)) {
    const full = path.join(dir, f);
    try {
      if (fs.statSync(full).isDirectory() && !f.startsWith('.') && f !== 'node_modules') {
        res = res.concat(findDbs(full));
      } else if (f.endsWith('.db') || f.endsWith('.sqlite')) {
        res.push(full);
      }
    } catch(e) {}
  }
  return res;
}

const allDbs = findDbs(path.join(__dirname, '..'));
console.log('\nTodos os bancos .db encontrados:');
for (const d of allDbs) {
  try {
    const ddb = new Database(d, { readonly: true });
    const tabs = ddb.prepare("SELECT name FROM sqlite_master WHERE type='table'").all().map(x => x.name);
    console.log(`- ${path.relative(path.join(__dirname, '..'), d)}: [${tabs.join(', ')}]`);
    ddb.close();
  } catch(e) {
    console.log(`- ${d}: erro ao abrir (${e.message})`);
  }
}

