const path = require('path');
const Database = require('better-sqlite3');
const XLSX = require('xlsx');

const DB_PATH = path.join(__dirname, 'pedidos_historico_ceven.db');
const db = new Database(DB_PATH);
db.pragma('journal_mode = WAL');

console.log('🔄 Atualizando métricas de inatividade e último pedido nos clientes...');

// 1. Atualizar clientes_completo com base no histórico real de pedidos extraídos
db.exec(`
  UPDATE clientes_completo
  SET 
    ultimo_pedido = (
      SELECT MAX(p.data_pedido) 
      FROM pedidos_historico p 
      WHERE p.id_cliente = clientes_completo.id_cliente 
        AND p.filial_codigo = clientes_completo.filial_codigo
    ),
    dias_sem_compra = COALESCE((
      SELECT CAST(ROUND(JULIANDAY('2026-09-12') - JULIANDAY(MAX(p.data_pedido))) AS INTEGER)
      FROM pedidos_historico p 
      WHERE p.id_cliente = clientes_completo.id_cliente 
        AND p.filial_codigo = clientes_completo.filial_codigo
    ), 999)
`);

console.log('✅ Clientes atualizados com inatividade real.');

const inatStats = db.prepare(`
  SELECT 
    COUNT(*) as total,
    SUM(CASE WHEN dias_sem_compra < 30 THEN 1 ELSE 0 END) as ativos_30d,
    SUM(CASE WHEN dias_sem_compra >= 30 AND dias_sem_compra < 60 THEN 1 ELSE 0 END) as inativos_30_59d,
    SUM(CASE WHEN dias_sem_compra >= 60 THEN 1 ELSE 0 END) as inativos_60d_mais
  FROM clientes_completo
`).get();

console.log('Estatísticas de Clientes:', inatStats);

function normalizarFilial(val) {
  if (!val) return '';
  let s = String(val).trim().toUpperCase();
  if (s.includes('TSJ')) return 'TSJ';
  if (s.includes('TCV')) return 'TCV';
  if (s.includes('TBE')) return 'TBE';
  if (s.includes('ABC')) return 'ABC';
  if (s.includes('TPH')) return 'TPH';
  if (s.includes('MCD')) return 'MCD';
  if (s.includes('TCA')) return 'TCA';
  if (s.includes('API')) return 'API';
  if (s.includes('TCG')) return 'TCG';
  if (s.includes('TPA')) return 'TPA';
  if (s.includes('TBL')) return 'TBL';
  return s;
}

console.log('\n📊 Gerando planilha AUDITORIA_COMPLETA_11_FILIAIS.xlsx atualizada...');
const wb = XLSX.utils.book_new();

// ABA 1: Histórico de Pedidos
console.log('  1. Histórico_Pedidos...');
const pedidos = db.prepare(`
  SELECT 
    filial_sigla AS "Filial",
    gerente_nome AS "Gerente",
    supervisor_nome AS "Supervisor",
    rca_id AS "Cód_RCA",
    rca_nome AS "Nome_RCA",
    id_cliente AS "Cód_Cliente",
    cnpj_cliente AS "CNPJ_Cliente",
    nome_cliente AS "Nome_Cliente",
    num_pedido AS "Num_Pedido",
    data_pedido_br AS "Data_Pedido",
    data_pedido AS "Data_ISO",
    status_pedido AS "Status_Pedido",
    categoria_corte AS "Categoria_Corte",
    vl_faturado AS "Valor_Faturado_R$",
    vl_cortado AS "Valor_Cortado_R$",
    (vl_faturado + vl_cortado) AS "Valor_Total_Emitido_R$",
    CASE WHEN (vl_faturado + vl_cortado) > 0 THEN 
      ROUND(vl_cortado * 100.0 / (vl_faturado + vl_cortado), 2)
    ELSE 0 END AS "Perc_Corte",
    qtd_skus AS "Qtd_SKUs",
    qtd_cortados AS "Qtd_SKUs_Cortados"
  FROM pedidos_historico
  ORDER BY filial_sigla, data_pedido DESC, num_pedido DESC
`).all().map(r => ({ ...r, Filial: normalizarFilial(r.Filial) }));
XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(pedidos), 'Histórico_Pedidos');

// ABA 2: Resumo por Filial
console.log('  2. Resumo_Por_Filial...');
const resumoFilial = db.prepare(`
  SELECT 
    filial_sigla AS "Filial",
    SUBSTR(data_pedido, 1, 7) AS "Ano_Mês",
    COUNT(DISTINCT num_pedido) AS "Total_Pedidos",
    COUNT(DISTINCT id_cliente) AS "Clientes_Compradores",
    COUNT(DISTINCT rca_id) AS "RCAs_Ativos",
    ROUND(SUM(vl_faturado), 2) AS "Faturamento_Total_R$",
    ROUND(SUM(vl_cortado), 2) AS "Valor_Cortado_R$",
    ROUND(SUM(vl_faturado + vl_cortado), 2) AS "Valor_Emitido_R$",
    CASE WHEN SUM(vl_faturado + vl_cortado) > 0 THEN
      ROUND(SUM(vl_cortado) * 100.0 / SUM(vl_faturado + vl_cortado), 2)
    ELSE 0 END AS "Taxa_Corte_Pct",
    ROUND(AVG(vl_faturado), 2) AS "Ticket_Médio_Pedido_R$"
  FROM pedidos_historico
  WHERE data_pedido != ''
  GROUP BY filial_sigla, SUBSTR(data_pedido, 1, 7)
  ORDER BY filial_sigla, "Ano_Mês" DESC
`).all().map(r => ({ ...r, Filial: normalizarFilial(r.Filial) }));
XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(resumoFilial), 'Resumo_Por_Filial');

// ABA 3: Resumo por RCA
console.log('  3. Resumo_Por_RCA...');
const resumoRca = db.prepare(`
  SELECT 
    filial_sigla AS "Filial",
    gerente_nome AS "Gerente",
    supervisor_nome AS "Supervisor",
    rca_id AS "Cód_RCA",
    rca_nome AS "Nome_RCA",
    COUNT(DISTINCT num_pedido) AS "Total_Pedidos",
    COUNT(DISTINCT id_cliente) AS "Clientes_Atendidos",
    ROUND(SUM(vl_faturado), 2) AS "Faturamento_Total_R$",
    ROUND(SUM(vl_cortado), 2) AS "Valor_Cortado_R$",
    CASE WHEN SUM(vl_faturado + vl_cortado) > 0 THEN
      ROUND(SUM(vl_cortado) * 100.0 / SUM(vl_faturado + vl_cortado), 2)
    ELSE 0 END AS "Taxa_Corte_Pct",
    ROUND(AVG(vl_faturado), 2) AS "Ticket_Médio_R$"
  FROM pedidos_historico
  GROUP BY filial_sigla, rca_id
  ORDER BY filial_sigla, "Faturamento_Total_R$" DESC
`).all().map(r => ({ ...r, Filial: normalizarFilial(r.Filial) }));
XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(resumoRca), 'Resumo_Por_RCA');

// ABA 4: Clientes Completos
console.log('  4. Clientes_Completos...');
const clientesCompletos = db.prepare(`
  SELECT 
    filial_sigla AS "Filial", gerente_nome AS "Gerente", supervisor_nome AS "Supervisor",
    rca_id AS "Cód_RCA", rca_nome AS "Nome_RCA",
    id_cliente AS "Cód_Cliente", cnpj AS "CNPJ",
    nome_cliente AS "Nome_Fantasia", razao_social AS "Razão_Social",
    dias_sem_compra AS "Dias_Sem_Compra",
    CASE 
      WHEN dias_sem_compra < 30 THEN 'ATIVO (<30d)'
      WHEN dias_sem_compra < 60 THEN 'ALERTA (30-59d)'
      ELSE 'INATIVO (60d+)'
    END AS "Classificação_Carteira",
    ultimo_pedido AS "Último_Pedido",
    CASE WHEN teve_ret = 1 THEN 'SIM' ELSE 'NÃO' END AS "Teve_RET"
  FROM clientes_completo
  ORDER BY filial_sigla, rca_id, dias_sem_compra ASC
`).all().map(r => ({ ...r, Filial: normalizarFilial(r.Filial) }));
XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(clientesCompletos), 'Clientes_Completos');

// ABA 5: Clientes Inativos (30+ dias)
console.log('  5. Clientes_Inativos...');
const inativos = db.prepare(`
  SELECT 
    filial_sigla AS "Filial", gerente_nome AS "Gerente", supervisor_nome AS "Supervisor",
    rca_id AS "Cód_RCA", rca_nome AS "Nome_RCA",
    id_cliente AS "Cód_Cliente", cnpj AS "CNPJ",
    nome_cliente AS "Nome_Fantasia", razao_social AS "Razão_Social",
    dias_sem_compra AS "Dias_Sem_Compra",
    ultimo_pedido AS "Último_Pedido",
    status_cliente AS "Status_Visita"
  FROM clientes_completo
  WHERE dias_sem_compra >= 30
  ORDER BY filial_sigla, dias_sem_compra DESC
`).all().map(r => ({ ...r, Filial: normalizarFilial(r.Filial) }));
XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(inativos), 'Clientes_Inativos');

// ABA 6: Top SKUs
console.log('  6. Top_SKUs_Vendidos...');
const topSkus = db.prepare(`
  SELECT 
    i.filial_codigo AS "Filial",
    i.codprod AS "Cód_Produto", i.descricao AS "Descrição",
    COUNT(DISTINCT i.id_cliente) AS "Clientes_Distintos",
    COUNT(DISTINCT i.num_pedido) AS "Pedidos_Com_Produto",
    SUM(i.quantidade) AS "Qtd_Total_Vendida",
    ROUND(SUM(i.valor_total), 2) AS "Faturamento_R$",
    ROUND(AVG(i.valor_total / NULLIF(i.quantidade, 0)), 4) AS "Preço_Médio_Unit"
  FROM pedidos_historico_itens i
  WHERE i.tipo_registro = 'VENDA' AND i.codprod != ''
  GROUP BY i.filial_codigo, i.codprod
  ORDER BY "Faturamento_R$" DESC
  LIMIT 10000
`).all().map(r => ({ ...r, Filial: normalizarFilial(r.Filial) }));
XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(topSkus), 'Top_SKUs_Vendidos');

// ABA 7: Itens Cortados
console.log('  7. Itens_Cortados_Histórico...');
const cortados = db.prepare(`
  SELECT 
    i.filial_codigo AS "Filial",
    i.codprod AS "Cód_Produto", i.descricao AS "Descrição",
    COUNT(DISTINCT i.id_cliente) AS "Clientes_Afetados",
    COUNT(DISTINCT i.num_pedido) AS "Pedidos_Com_Corte",
    SUM(i.quantidade) AS "Qtd_Total_Cortada",
    ROUND(SUM(i.valor_total), 2) AS "Valor_Cortado_R$"
  FROM pedidos_historico_itens i
  WHERE i.tipo_registro = 'CORTE' AND i.codprod != ''
  GROUP BY i.filial_codigo, i.codprod
  ORDER BY "Valor_Cortado_R$" DESC
  LIMIT 5000
`).all().map(r => ({ ...r, Filial: normalizarFilial(r.Filial) }));
XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(cortados), 'Itens_Cortados_Histórico');

// ABA 8: Devoluções por Filial (integrando com as devoluções já extraídas)
console.log('  8. Resumo_Devoluções_Filial...');
const devolucoes = db.prepare(`
  SELECT 
    filial_codigo AS "Filial",
    COUNT(DISTINCT numero_nota) AS "Qtd_Notas_Devolução",
    ROUND(SUM(valor_total), 2) AS "Valor_Total_Devolvido_R$",
    COUNT(DISTINCT rca_id) AS "RCAs_Com_Devolução",
    COUNT(DISTINCT cliente_id) AS "Clientes_Com_Devolução"
  FROM devolucoes_notas
  GROUP BY filial_codigo
  ORDER BY "Valor_Total_Devolvido_R$" DESC
`).all().map(r => ({ ...r, Filial: normalizarFilial(r.Filial) }));
XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(devolucoes), 'Resumo_Devoluções_Filial');

const outPath = path.join(__dirname, 'AUDITORIA_COMPLETA_11_FILIAIS.xlsx');
try {
  XLSX.writeFile(wb, outPath);
  console.log(`\n🎉 Planilha AUDITORIA_COMPLETA_11_FILIAIS.xlsx atualizada com sucesso!`);
} catch(e) {
  const fallback = outPath.replace('.xlsx', '_CONSOLIDADA.xlsx');
  XLSX.writeFile(wb, fallback);
  console.log(`\n🎉 Planilha salva como: ${fallback}`);
}
db.close();

