const fs = require('fs');
const path = require('path');
const harPath = path.join(__dirname, 'ceven.drivetriunfante-locomotiva.com.br - Vendedor.har');
const content = fs.readFileSync(harPath, 'utf8');
const har = JSON.parse(content);

console.log('Total entries no HAR Vendedor:', har.log.entries.length);

for (const entry of har.log.entries) {
  const url = entry.request.url;
  const postData = entry.request.postData ? entry.request.postData.text : '';
  if (postData && (postData.includes('target_cnpj') || postData.includes('universo_cnpjs'))) {
    console.log('\n🎯 ENDPOINT ENCONTRADO!');
    console.log('Method:', entry.request.method);
    console.log('URL:', url);
    console.log('Headers:', entry.request.headers.filter(h => !h.name.startsWith(':')));
    console.log('PostData (primeiros 300 chars):', postData.slice(0, 300));
    console.log('Response Status:', entry.response.status);
