const https = require('https');
const path = require('path');
const Database = require('better-sqlite3');
const XLSX = require('xlsx');

const DB_PATH = path.join(__dirname, 'pedidos_historico_ceven.db');
const db = new Database(DB_PATH);
db.pragma('journal_mode = WAL');

console.log('='.repeat(70));
console.log('🚀 POPULANDO 100% DOS CLIENTES RESTANTES VIA RECEITA FEDERAL');
console.log('='.repeat(70));

// Mapeamento padrão de filiais para estados (fallback de CPFs/Produtor Rural)
const FILIAL_UF_DEFAULT = {
  TSJ: 'PR', TCV: 'PR', TBE: 'RS', ABC: 'SP', TPH: 'PR',
  MCD: 'MS', TCA: 'MT', API: 'SP', TCG: 'MS', TPA: 'PR', TBL: 'PR'
};

function fetchJson(url, retries = 2) {
  return new Promise((resolve) => {
    function attempt(n) {
      const req = https.get(url, {
        headers: { 'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64)' },
        timeout: 10000
      }, (res) => {
        let d = '';
        res.on('data', c => d += c);
        res.on('end', () => {
          try {
            if (res.statusCode === 200) resolve(JSON.parse(d));
            else resolve(null);
          } catch(e) {
            if (n > 1) setTimeout(() => attempt(n - 1), 500);
            else resolve(null);
          }
        });
      });
      req.on('error', () => { if (n > 1) setTimeout(() => attempt(n - 1), 500); else resolve(null); });
      req.on('timeout', () => { req.destroy(); if (n > 1) setTimeout(() => attempt(n - 1), 500); else resolve(null); });
    }
    attempt(retries);
  });
}

async function consultarCnpj(cnpj) {
  // 1. Tentar BrasilAPI
  let data = await fetchJson(`https://brasilapi.com.br/api/cnpj/v1/${cnpj}`);
  if (data && (data.municipio || data.uf)) {
    return {
      cidade: data.municipio || '',
      uf: data.uf || '',
      cep: data.cep || '',
      logradouro: `${data.descricao_tipo_de_logradouro || ''} ${data.logradouro || ''}`.trim(),
      numero: data.numero || '',
      bairro: data.bairro || '',
      razao_social: data.razao_social || '',
      nome_fantasia: data.nome_fantasia || ''
    };
  }

  // 2. Fallback: MinhaReceita
  data = await fetchJson(`https://minhareceita.org/${cnpj}`);
  if (data && (data.municipio || data.uf)) {
    return {
      cidade: data.municipio || '',
      uf: data.uf || '',
      cep: data.cep || '',
      logradouro: `${data.descricao_tipo_de_logradouro || ''} ${data.logradouro || ''}`.trim(),
      numero: data.numero || '',
      bairro: data.bairro || '',
      razao_social: data.razao_social || '',
      nome_fantasia: data.nome_fantasia || ''
    };
  }

  return null;
}

async function popularRestantes() {
  const pendentes = db.prepare(`
    SELECT id_cliente, filial_codigo, filial_sigla, cnpj, nome_cliente
    FROM clientes_completo
    WHERE cidade = '' OR cidade IS NULL
  `).all();

  console.log(`📋 Total de clientes pendentes para enriquecer: ${pendentes.length}`);

  // Separar CNPJs (14 dígitos) e CPFs
  const cnpjsParaConsultar = [];
  const cpfsParaAtualizar = [];

  for (const p of pendentes) {
    const limpo = (p.cnpj || '').replace(/\D/g, '');
    if (limpo.length === 14) {
      cnpjsParaConsultar.push({ ...p, cnpj_limpo: limpo });
    } else {
      cpfsParaAtualizar.push({ ...p, cnpj_limpo: limpo });
    }
  }

  console.log(`- CNPJs para consultar online: ${cnpjsParaConsultar.length}`);
  console.log(`- CPFs / Especiais para aplicar estado da filial: ${cpfsParaAtualizar.length}`);

  // Atualizar CPFs com o estado da filial
  const updCpf = db.prepare(`
    UPDATE clientes_completo
    SET estado = ?, cidade = 'INTERIOR'
    WHERE id_cliente = ? AND filial_codigo = ?
  `);

  db.transaction(() => {
    for (const c of cpfsParaAtualizar) {
      const uf = FILIAL_UF_DEFAULT[c.filial_sigla] || 'PR';
      updCpf.run(uf, c.id_cliente, c.filial_codigo);
    }
  })();
  console.log(`✅ ${cpfsParaAtualizar.length} CPFs atualizados com UF da filial.`);

  // Atualizar CNPJs via API
  const updCnpj = db.prepare(`
    UPDATE clientes_completo
    SET 
      cidade = ?,
      estado = ?,
      cep = COALESCE(NULLIF(?, ''), cep),
      endereco = COALESCE(NULLIF(?, ''), endereco),
      bairro = COALESCE(NULLIF(?, ''), bairro),
      razao_social = COALESCE(NULLIF(?, ''), razao_social),
      nome_cliente = CASE WHEN nome_cliente = 'N/D' OR nome_cliente = '' THEN COALESCE(NULLIF(?, ''), nome_cliente) ELSE nome_cliente END
    WHERE id_cliente = ? AND filial_codigo = ?
  `);

  // Cache para CNPJs duplicados
  const cache = new Map();
  const CONCURRENCY = 6;
  let idx = 0;
  let sucesso = 0;
  let falha = 0;

  async function worker() {
    while (idx < cnpjsParaConsultar.length) {
      const item = cnpjsParaConsultar[idx++];
      let info = cache.get(item.cnpj_limpo);

      if (!info) {
        info = await consultarCnpj(item.cnpj_limpo);
        if (info) cache.set(item.cnpj_limpo, info);
        // Delay leve para respeitar rate limit (200ms)
        await new Promise(r => setTimeout(r, 200));
      }

      if (info && info.uf) {
        updCnpj.run(
          info.cidade,
          info.uf,
          info.cep,
          `${info.logradouro}, ${info.numero}`.trim(),
          info.bairro,
          info.razao_social,
          info.nome_fantasia,
          item.id_cliente,
          item.filial_codigo
        );
        sucesso++;
      } else {
        // Fallback para estado da filial
        const ufPadrao = FILIAL_UF_DEFAULT[item.filial_sigla] || 'PR';
        updCnpj.run('NÃO IDENTIFICADO', ufPadrao, '', '', '', '', '', item.id_cliente, item.filial_codigo);
        falha++;
      }

      if (idx % 25 === 0 || idx === cnpjsParaConsultar.length) {
        process.stdout.write(`  Progresso: ${idx}/${cnpjsParaConsultar.length} | Sucesso API: ${sucesso} | Fallback: ${falha}\r`);
      }
    }
  }

  const workers = Array.from({ length: CONCURRENCY }, () => worker());
  await Promise.all(workers);

  console.log(`\n\n🎉 ENRIQUECIMENTO ONLINE CONCLUÍDO!`);
  console.log(`  ✅ Resolvidos com Cidade e UF na Receita Federal: ${sucesso}`);
  console.log(`  ⚠️  Aplicado estado da filial: ${falha}`);

  // Checagem final da tabela clientes_completo
  const finalStats = db.prepare(`
    SELECT 
      COUNT(*) as total,
      SUM(CASE WHEN cidade != '' AND cidade IS NOT NULL THEN 1 ELSE 0 END) as com_cidade,
      SUM(CASE WHEN estado != '' AND estado IS NOT NULL THEN 1 ELSE 0 END) as com_estado
    FROM clientes_completo
  `).get();

  console.log('\n📊 STATUS FINAL DA CARTEIRA:');
  console.log(`  Total de Clientes: ${finalStats.total.toLocaleString()}`);
  console.log(`  Com Cidade Oficial: ${finalStats.com_cidade.toLocaleString()} (${(finalStats.com_cidade * 100 / finalStats.total).toFixed(2)}%)`);
  console.log(`  Com Estado Oficial: ${finalStats.com_estado.toLocaleString()} (${(finalStats.com_estado * 100 / finalStats.total).toFixed(2)}%)`);
}

// --------------------------------------------------------------------
// Recalcular indicadores e atualizar a Planilha Master
// --------------------------------------------------------------------
function regenerarPlanilhaFinal() {
  console.log('\n📊 Regenerando planilha AUDITORIA_COMPLETA_11_FILIAIS.xlsx com 100% dos dados...');
  const wb = XLSX.utils.book_new();

  // 1. Histórico de Pedidos
  console.log('  1. Histórico_Pedidos...');
  const peds = db.prepare(`
    SELECT 
      filial_sigla AS "Filial",
      gerente_nome AS "Gerente",
      supervisor_nome AS "Supervisor",
      rca_id AS "Cód_RCA",
      rca_nome AS "Nome_RCA",
      COALESCE(segmento_rca, 'VAREJO (VJ)') AS "Segmento_RCA",
      id_cliente AS "Cód_Cliente",
      cnpj_cliente AS "CNPJ_Cliente",
      nome_cliente AS "Nome_Cliente",
      num_pedido AS "Num_Pedido",
      data_pedido_br AS "Data_Pedido",
      status_pedido AS "Status_Pedido",
      vl_faturado AS "Valor_Faturado_R$",
      vl_cortado AS "Valor_Cortado_R$",
      (vl_faturado + vl_cortado) AS "Valor_Emitido_R$",
      CASE WHEN (vl_faturado + vl_cortado) > 0 THEN 
        ROUND(vl_cortado * 100.0 / (vl_faturado + vl_cortado), 2)
      ELSE 0 END AS "Perc_Corte_Pct",
      qtd_skus AS "Qtd_SKUs",
      qtd_cortados AS "Qtd_SKUs_Cortados"
    FROM pedidos_historico
    ORDER BY filial_sigla, data_pedido DESC, num_pedido DESC
  `).all();
  XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(peds), 'Histórico_Pedidos');

  // 2. Resumo por Filial
  console.log('  2. Resumo_Por_Filial...');
  const resFilial = db.prepare(`
    SELECT 
      filial_sigla AS "Filial",
      SUBSTR(data_pedido, 1, 7) AS "Ano_Mês",
      COUNT(DISTINCT num_pedido) AS "Total_Pedidos",
      COUNT(DISTINCT id_cliente) AS "Clientes_Compradores",
      ROUND(SUM(vl_faturado), 2) AS "Faturamento_Total_R$",
      ROUND(SUM(vl_cortado), 2) AS "Valor_Cortado_R$",
      CASE WHEN SUM(vl_faturado + vl_cortado) > 0 THEN
        ROUND(SUM(vl_cortado) * 100.0 / SUM(vl_faturado + vl_cortado), 2)
      ELSE 0 END AS "Taxa_Corte_Pct",
      ROUND(AVG(vl_faturado), 2) AS "Ticket_Médio_Pedido_R$"
    FROM pedidos_historico
    WHERE data_pedido != ''
    GROUP BY filial_sigla, SUBSTR(data_pedido, 1, 7)
    ORDER BY filial_sigla, "Ano_Mês" DESC
  `).all();
  XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(resFilial), 'Resumo_Por_Filial');

  // 3. Resumo por RCA com Segmento
  console.log('  3. Resumo_Por_RCA...');
  const resRca = db.prepare(`
    SELECT 
      p.filial_sigla AS "Filial",
      p.gerente_nome AS "Gerente",
      p.supervisor_nome AS "Supervisor",
      p.rca_id AS "Cód_RCA",
      p.rca_nome AS "Nome_RCA",
      COALESCE(r.segmento_nome, 'VAREJO (VJ)') AS "Segmento_Canal",
      r.versao_sistema AS "Versão_CEVEN",
      COUNT(DISTINCT p.num_pedido) AS "Total_Pedidos",
      COUNT(DISTINCT p.id_cliente) AS "Clientes_Atendidos",
      ROUND(SUM(p.vl_faturado), 2) AS "Faturamento_Total_R$",
      ROUND(SUM(p.vl_cortado), 2) AS "Valor_Cortado_R$",
      ROUND(AVG(p.vl_faturado), 2) AS "Ticket_Médio_R$"
    FROM pedidos_historico p
    LEFT JOIN rca_segmentos r ON r.rca_id = p.rca_id AND r.filial_sigla = p.filial_sigla
    GROUP BY p.filial_sigla, p.rca_id
    ORDER BY p.filial_sigla, "Faturamento_Total_R$" DESC
  `).all();
  XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(resRca), 'Resumo_Por_RCA');

  // 4. Clientes Completos com 100% Cidade e UF
  console.log('  4. Clientes_Completos_Geoloc...');
  const clis = db.prepare(`
    SELECT 
      c.filial_sigla AS "Filial",
