  RcaVendas AS (
    SELECT 
      p.rca_id, p.filial_sigla,
      COUNT(DISTINCT p.num_pedido) as total_pedidos,
      ROUND(SUM(p.vl_faturado), 2) as faturado_total,
      ROUND(AVG(p.vl_faturado), 2) as ticket_medio,
      COUNT(DISTINCT i.codprod) as total_skus_distintos,
      ROUND(AVG(p.qtd_skus), 2) as media_skus_por_pedido,
      ROUND(SUM(p.vl_cortado) * 100.0 / NULLIF(SUM(p.vl_faturado + p.vl_cortado), 0), 2) as taxa_corte_pct
    FROM pedidos_historico p
    JOIN pedidos_historico_itens i ON i.chave_pedido = p.chave AND i.tipo_registro = 'VENDA'
    WHERE p.status_pedido = 'FATURADO'
    GROUP BY p.rca_id, p.filial_sigla
  ),
  RcaCarteira AS (
    SELECT 
      c.filial_sigla, c.rca_id, c.rca_nome,
      COUNT(DISTINCT c.id_cliente) as carteira_total,
      COUNT(DISTINCT CASE WHEN c.dias_sem_compra < 30 THEN c.id_cliente END) as ativos_30d,
      COUNT(DISTINCT CASE WHEN c.dias_sem_compra >= 30 THEN c.id_cliente END) as inativos_30d
    FROM clientes_completo c
    WHERE c.rca_id IS NOT NULL AND c.rca_id != 0 AND COALESCE(c.segmento_rca, 'VAREJO (VJ)') = 'VAREJO (VJ)'
    GROUP BY c.filial_sigla, c.rca_id
    HAVING carteira_total >= 10
  )
  SELECT 
    rc.filial_sigla,
    rc.rca_id,
    rc.rca_nome,
    rc.carteira_total,
    rc.ativos_30d,
    rc.inativos_30d,
    ROUND(rc.ativos_30d * 100.0 / rc.carteira_total, 2) as taxa_positivacao_pct,
    COALESCE(v.total_pedidos, 0) as total_pedidos,
    COALESCE(v.faturado_total, 0) as faturado_total,
    COALESCE(v.ticket_medio, 0) as ticket_medio,
    COALESCE(v.total_skus_distintos, 0) as skus_distintos,
    COALESCE(v.media_skus_por_pedido, 0) as skus_por_pedido,
    COALESCE(v.taxa_corte_pct, 0) as taxa_corte_pct,
    COALESCE(cid.total_cidades, 1) as total_cidades,
    COALESCE(m.meta_faturamento, 0) as meta_faturamento,
    COALESCE(m.meta_positivacao, 0) as meta_positivacao,
    COALESCE(m.atingimento_fat_pct, 0) as atingimento_fat_pct,
    COALESCE(m.atingimento_pos_pct, 0) as atingimento_pos_pct,
    COALESCE(m.visit_plan_mes, 0) as visitas_planejadas,
    COALESCE(m.visit_real_mes, 0) as visitas_realizadas,
    COALESCE(m.eficiencia_visita_pct, 0) as eficiencia_visita_pct,
    -- Taxa de Conversão da Visita (Strike Rate) = Pedidos / Visitas Realizadas
    CASE 
      WHEN m.visit_real_mes > 0 THEN ROUND(COALESCE(v.total_pedidos, 0) * 100.0 / m.visit_real_mes, 2)
      ELSE 0 
    END as taxa_conversao_visita_pct,
    -- Faturamento Médio por Cliente da Carteira (ARPU Comercial)
    ROUND(COALESCE(v.faturado_total, 0) / NULLIF(rc.carteira_total, 0), 2) as faturamento_por_pdv_carteira
  FROM RcaCarteira rc
  LEFT JOIN RcaVendas v ON v.rca_id = rc.rca_id AND v.filial_sigla = rc.filial_sigla
  LEFT JOIN RcaCidades cid ON cid.rca_id = rc.rca_id AND cid.filial_sigla = rc.filial_sigla
  LEFT JOIN rca_metas_dashboard m ON m.rca_id = rc.rca_id AND m.filial_sigla = rc.filial_sigla
  WHERE v.total_pedidos > 0
`).all();

console.log(`Dataset carregado com ${dataset.length} representantes de VAREJO.`);

// 2. FUNÇÕES ESTATÍSTICAS CIENTÍFICAS
function media(arr) {
  return arr.reduce((a, b) => a + b, 0) / arr.length;
}

function desvioPadrao(arr, m) {
  const avg = m !== undefined ? m : media(arr);
  const sumSq = arr.reduce((acc, val) => acc + Math.pow(val - avg, 2), 0);
  return Math.sqrt(sumSq / (arr.length - 1 || 1));
}

function correlacaoPearson(arrX, arrY) {
  const n = arrX.length;
  if (n < 2) return 0;
  const mX = media(arrX);
  const mY = media(arrY);
  const sX = desvioPadrao(arrX, mX);
  const sY = desvioPadrao(arrY, mY);
  if (sX === 0 || sY === 0) return 0;

  let sumProd = 0;
  for (let i = 0; i < n; i++) {
    sumProd += (arrX[i] - mX) * (arrY[i] - mY);
  }
  return sumProd / ((n - 1) * sX * sY);
}

// 3. MATRIZ DE CORRELAÇÃO DE PEARSON (Multivariada)
const variaveis = [
  { key: 'carteira_total', nome: '1. Tamanho Carteira' },
  { key: 'skus_distintos', nome: '2. SKUs Distintos (Mix)' },
  { key: 'skus_por_pedido', nome: '3. SKUs por Pedido' },
  { key: 'ticket_medio', nome: '4. Ticket Médio (R$)' },
  { key: 'taxa_positivacao_pct', nome: '5. Taxa Positivação (%)' },
  { key: 'taxa_conversao_visita_pct', nome: '6. Conversão Visita (Strike Rate %)' },
  { key: 'faturado_total', nome: '7. Faturamento Total' },
  { key: 'faturamento_por_pdv_carteira', nome: '8. Faturamento / PDV Carteira' },
  { key: 'atingimento_pos_pct', nome: '9. Atingimento Meta Posit. (%)' },
  { key: 'total_cidades', nome: '10. Dispersão (Qtd Cidades)' }
];

console.log('\n--- MATRIZ DE CORRELAÇÃO DE PEARSON MULTIVARIADA (r) ---');
const matrizCorrelacao = {};

for (const v1 of variaveis) {
  matrizCorrelacao[v1.nome] = {};
  const arrX = dataset.map(d => d[v1.key]);
  for (const v2 of variaveis) {
    const arrY = dataset.map(d => d[v2.key]);
    const r = correlacaoPearson(arrX, arrY);
    matrizCorrelacao[v1.nome][v2.nome] = parseFloat(r.toFixed(3));
  }
}
console.table(matrizCorrelacao);

// 4. CLUSTERIZAÇÃO EM 4 QUADRANTES DE EFICIÊNCIA DE VENDAS
// Baseado na literatura de RTM (Harvard Business Review & ZS Associates):
// Eixo X: Produtividade de Mix e Conversão (Qualidade da Execução)
// Eixo Y: Positivação e Cobertura de Carteira (Capilaridade)

const medPositivacao = 50.0; // Benchmark 50% de positivação ativa
const medSkus = media(dataset.map(d => d.skus_distintos)); // Média de SKUs da equipe

const clusters = {
  Q1_Hunters_Top_Performers: [],
  Q2_Tiradores_De_Pedido_Superficiais: [],
  Q3_Atacadistas_Falso_Varejo: [],
  Q4_Criticos_Em_Risco: []
};

dataset.forEach(r => {
  const altaPosit = r.taxa_positivacao_pct >= medPositivacao;
  const altoMix = r.skus_distintos >= medSkus;

  if (altaPosit && altoMix) {
    clusters.Q1_Hunters_Top_Performers.push(r);
  } else if (altaPosit && !altoMix) {
    clusters.Q2_Tiradores_De_Pedido_Superficiais.push(r);
  } else if (!altaPosit && altoMix) {
    clusters.Q3_Atacadistas_Falso_Varejo.push(r);
  } else {
    clusters.Q4_Criticos_Em_Risco.push(r);
  }
});

const resumoClusters = Object.keys(clusters).map(q => {
  const grp = clusters[q];
  const n = grp.length || 1;
  return {
    Quadrante: q,
    Qtd_RCAs: grp.length,
    Pct_Equipe: (grp.length * 100.0 / dataset.length).toFixed(1) + '%',
    Carteira_Media: (grp.reduce((a,b)=>a+b.carteira_total,0)/n).toFixed(1),
    Positivacao_Media_Pct: (grp.reduce((a,b)=>a+b.taxa_positivacao_pct,0)/n).toFixed(1) + '%',
    SKUs_Distintos_Medio: (grp.reduce((a,b)=>a+b.skus_distintos,0)/n).toFixed(1),
    Ticket_Medio_R$: (grp.reduce((a,b)=>a+b.ticket_medio,0)/n).toFixed(2),
    Faturamento_Total_R$: (grp.reduce((a,b)=>a+b.faturado_total,0)).toFixed(2),
    Atingimento_Posit_Meta: (grp.reduce((a,b)=>a+b.atingimento_pos_pct,0)/n).toFixed(1) + '%',
    Atingimento_Fat_Meta: (grp.reduce((a,b)=>a+b.atingimento_fat_pct,0)/n).toFixed(1) + '%'
  };
});

console.log('\n--- QUADRANTES DE MATURIDADE DA FORÇA DE VENDAS (HARVARD / ZS ASSOCIATES) ---');
console.table(resumoClusters);

// 5. REGRESSÃO LINEAR MÚLTIPLA (Elasticidade dos Fatores sobre o Faturamento)
// Y = Faturamento Total
// X1 = Carteira Total, X2 = SKUs Distintos, X3 = Ticket Médio, X4 = Visitas Realizadas
console.log('\n--- REGRESSÃO LINEAR & ELASTICIDADE DE IMPACTO ---');
// Correlações com Faturamento Total:
const corrComFaturamento = {
  'SKUs Distintos (Mix)': correlacaoPearson(dataset.map(d => d.skus_distintos), dataset.map(d => d.faturado_total)),
  'Ticket Médio': correlacaoPearson(dataset.map(d => d.ticket_medio), dataset.map(d => d.faturado_total)),
  'Tamanho da Carteira': correlacaoPearson(dataset.map(d => d.carteira_total), dataset.map(d => d.faturado_total)),
  'Taxa de Positivação': correlacaoPearson(dataset.map(d => d.taxa_positivacao_pct), dataset.map(d => d.faturado_total)),
  'Qtd Cidades Atendidas': correlacaoPearson(dataset.map(d => d.total_cidades), dataset.map(d => d.faturado_total))
};
console.table(corrComFaturamento);

// Salvar todos os dados científicos
const outData = {
  n_amostra: dataset.length,
  matrizCorrelacao,
  resumoClusters,
  corrComFaturamento,
  exemplosCasosReais: {
    caso_vendedor_200_ineficiente: dataset.filter(d => d.carteira_total >= 180 && d.skus_distintos < 100).slice(0, 3),
    caso_vendedor_100_super_eficiente: dataset.filter(d => d.carteira_total >= 80 && d.carteira_total <= 120 && d.skus_distintos > 250).slice(0, 3)
  }
};

fs.writeFileSync(path.join(__dirname, 'analise_estatistica_avancada_nasa.json'), JSON.stringify(outData, null, 2));
console.log('\n✅ Resultados estatísticos salvos em analises/analise_estatistica_avancada_nasa.json');
db.close();

