console.log('='.repeat(70));
console.log('🔄 RECALCULAÇÃO INTEGRAL: REATRIBUIÇÃO DO RCA REAL EMISSOR NOS PEDIDOS');
console.log('='.repeat(70));

// 1. Criar coluna rca_emissor_real caso não exista
