} catch (e) {
  console.log('ℹ️ Coluna rca_nome_emissor já existia.');
}

// 2. Atualizar rca_emissor_real baseado no padrão Winthor dos números de pedido
console.log('⏳ Atualizando rca_emissor_real nos 91.616 pedidos históricos...');
db.exec(`
  UPDATE pedidos_historico
  SET rca_emissor_real = CASE 
    WHEN length(num_pedido) >= 7 AND num_pedido GLOB '[0-9]*' THEN CAST(substr(num_pedido, 1, length(num_pedido)-6) AS INTEGER)
    ELSE rca_id
  END;
`);

