  FROM pedidos_historico;
`).get();

console.log('✅ Reatribuição concluída com sucesso!');
console.log(`   Total Pedidos: ${stats.total_pedidos.toLocaleString()}`);
console.log(`   Pedidos Remanejados para o RCA Emissor Real: ${stats.pedidos_remanejados.toLocaleString()}`);
console.log(`   Faturamento Reatribuído: R$ ${stats.valor_remanejado.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}`);

const Database = require('better-sqlite3');
const path = require('path');
const fs = require('fs');

const db = new Database(path.join(__dirname, 'pedidos_historico_ceven.db'));

console.log('='.repeat(70));
console.log('🔬 REPROCESSAMENTO CIENTÍFICO INTEGRAL (PADRÃO NASA / MIT / ZS ASSOCIATES)');
console.log('='.repeat(70));

// 1. Carregar carteiras reais do roteiro do mês coletadas diretamente da API do CEVEN
const carteirasReais = JSON.parse(fs.readFileSync(path.join(__dirname, '../scripts/clientes_distintos_carteira_mes.json'), 'utf8'));

// 2. Montar visão consolidada de performance por RCA baseada no RCA EMISSOR REAL DOS PEDIDOS e na CARTEIRA REAL
const queryPerformance = `
  WITH VendasReais AS (
    SELECT 
      p.filial_sigla,
      p.rca_emissor_real as rca_id,
      COALESCE(p.rca_nome_emissor, 'RCA ' || p.rca_emissor_real) as rca_nome,
      COUNT(DISTINCT p.id_cliente) as clientes_positivados_historico,
      COUNT(DISTINCT p.num_pedido) as pedidos_totais,
      ROUND(SUM(p.vl_faturado), 2) as faturamento_total_real,
      ROUND(AVG(p.vl_faturado), 2) as ticket_medio_real,
      COUNT(DISTINCT i.codprod) as total_skus_distintos,
      ROUND(AVG(p.qtd_skus), 1) as media_skus_por_pedido,
      COUNT(DISTINCT c.cidade) as cidades_atendidas
    FROM pedidos_historico p
    JOIN pedidos_historico_itens i ON i.chave_pedido = p.chave AND i.tipo_registro = 'VENDA'
    LEFT JOIN clientes_completo c ON c.id_cliente = p.id_cliente AND c.filial_sigla = p.filial_sigla
    WHERE p.status_pedido = 'FATURADO'
    GROUP BY p.filial_sigla, p.rca_emissor_real
  )
  SELECT 
    v.filial_sigla,
    v.rca_id,
    v.rca_nome,
    COALESCE(m.segmento_rca, 'VAREJO (VJ)') as segmento,
    COALESCE(m.meta_faturamento, 0) as meta_fat,
    COALESCE(m.faturado_mes, v.faturamento_total_real) as fat_atingido_mes,
    COALESCE(m.atingimento_fat_pct, 0) as ating_fat_pct,
    COALESCE(m.meta_positivacao, 0) as meta_pos,
    COALESCE(m.realizado_positivacao, v.clientes_positivados_historico) as pos_atingida_mes,
    COALESCE(m.atingimento_pos_pct, 0) as ating_pos_pct,
    v.pedidos_totais,
    v.faturamento_total_real,
    v.ticket_medio_real,
    v.total_skus_distintos,
    v.media_skus_por_pedido,
    v.cidades_atendidas
  FROM VendasReais v
  LEFT JOIN rca_metas_dashboard m 
    ON m.filial_sigla = v.filial_sigla AND m.rca_id = v.rca_id
  WHERE v.rca_id IS NOT NULL AND v.rca_id != 0;
`;

const rows = db.prepare(queryPerformance).all();
console.log(`Total de RCAs com emissão real mapeada: ${rows.length}`);

// Filtrar apenas Varejo (VJ)
const rcasVj = rows.filter(r => r.segmento === 'VAREJO (VJ)' || r.segmento === 'VJ');
console.log(`RCAs de Varejo (VJ) para reanálise estatística: ${rcasVj.length}`);

// Enriquecer cada RCA com a sua Carteira Real do Mês (sem distorção de desduplicação)
rcasVj.forEach(r => {
  const key = `${r.filial_sigla}_${r.rca_id}`;
  r.carteira_real = carteirasReais[key] || 0;

  // Taxa de Positivação Real sobre a Carteira Real do Roteiro do Mês
  if (r.carteira_real > 0) {
    r.taxa_positivacao_carteira_pct = Math.min(100, parseFloat(((r.pos_atingida_mes / r.carteira_real) * 100).toFixed(1)));
  } else {
    r.taxa_positivacao_carteira_pct = 0;
  }

  // Classificação de Faixa de Carteira Real
  if (r.carteira_real < 60) {
    r.faixa_carteira = '1. Crítico (<60 clis)';
  } else if (r.carteira_real < 120) {
    r.faixa_carteira = '2. Baixo (60-119 clis)';
  } else if (r.carteira_real < 180) {
    r.faixa_carteira = '3. Médio (120-179 clis)';
  } else if (r.carteira_real <= 230) {
    r.faixa_carteira = '4. Ideal / Meta (180-230 clis)';
  } else {
    r.faixa_carteira = '5. Alto / Sobrecarregado (>230 clis)';
  }
});

// Apenas RCAs ativos com carteira >= 10
const amostraValida = rcasVj.filter(r => r.carteira_real >= 10);
console.log(`Amostra válida com carteira >= 10 para matriz estatística: ${amostraValida.length}`);

// 3. CALCULAR MATRIZ DE CORRELAÇÃO DE PEARSON (NASA / MIT)
function calcPearson(arr, keyX, keyY) {
  const n = arr.length;
  if (n === 0) return 0;
  let sumX = 0, sumY = 0, sumXY = 0, sumX2 = 0, sumY2 = 0;
  for (const item of arr) {
    const x = parseFloat(item[keyX]) || 0;
    const y = parseFloat(item[keyY]) || 0;
    sumX += x;
    sumY += y;
    sumXY += x * y;
    sumX2 += x * x;
    sumY2 += y * y;
  }
  const denom = Math.sqrt((n * sumX2 - sumX * sumX) * (n * sumY2 - sumY * sumY));
  if (denom === 0) return 0;
  return parseFloat(((n * sumXY - sumX * sumY) / denom).toFixed(3));
}

const vars = [
  { id: 'carteira_real', label: '1. Tamanho Carteira Real' },
  { id: 'total_skus_distintos', label: '2. Mix SKUs Distintos' },
  { id: 'media_skus_por_pedido', label: '3. SKUs por Pedido' },
  { id: 'ticket_medio_real', label: '4. Ticket Médio Real' },
  { id: 'taxa_positivacao_carteira_pct', label: '5. Taxa Positivação Carteira (%)' },
  { id: 'faturamento_total_real', label: '6. Faturamento Total Real' },
  { id: 'ating_pos_pct', label: '7. % Atingimento Meta Posit.' }
];

const matrizCorrelacao = {};
vars.forEach(v1 => {
  matrizCorrelacao[v1.label] = {};
  vars.forEach(v2 => {
    matrizCorrelacao[v1.label][v2.label] = calcPearson(amostraValida, v1.id, v2.id);
  });
});

console.log('\n--- MATRIZ DE CORRELAÇÃO DE PEARSON RECALCULADA ---');
console.table(matrizCorrelacao);

// 4. DISTRIBUIÇÃO DAS FAIXAS DE CARTEIRA REAIS E COMPORTAMENTO
const faixas = {};
['1. Crítico (<60 clis)', '2. Baixo (60-119 clis)', '3. Médio (120-179 clis)', '4. Ideal / Meta (180-230 clis)', '5. Alto / Sobrecarregado (>230 clis)'].forEach(f => {
  const grupo = rcasVj.filter(r => r.faixa_carteira === f);
  const n = grupo.length;
  if (n === 0) return;
  const avg = (k) => (grupo.reduce((acc, x) => acc + (parseFloat(x[k]) || 0), 0) / n);

  faixas[f] = {
    faixa: f,
    qtd_rcas: n,
    pct_equipe: parseFloat(((n / rcasVj.length) * 100).toFixed(1)),
    carteira_media: parseFloat(avg('carteira_real').toFixed(1)),
    ticket_medio: parseFloat(avg('ticket_medio_real').toFixed(2)),
    skus_distintos: parseFloat(avg('total_skus_distintos').toFixed(1)),
    skus_por_pedido: parseFloat(avg('media_skus_por_pedido').toFixed(1)),
    taxa_positivacao_pct: parseFloat(avg('taxa_positivacao_carteira_pct').toFixed(1)),
    ating_fat_pct: parseFloat(avg('ating_fat_pct').toFixed(1)),
    ating_pos_pct: parseFloat(avg('ating_pos_pct').toFixed(1))
  };
});

console.log('\n--- DISTRIBUIÇÃO DE FAIXAS DE CARTEIRA RECALCULADAS ---');
console.table(faixas);

// 5. CLUSTERIZAÇÃO EM 4 QUADRANTES (ZS ASSOCIATES)
const medianPos = 25.0; // Mediana da taxa de positivação sobre a carteira
const medianMix = 200;  // Mediana de SKUs distintos trabalhados no mês

const q1 = [], q2 = [], q3 = [], q4 = [];

amostraValida.forEach(r => {
  const altaPos = r.taxa_positivacao_carteira_pct >= medianPos;
  const altoMix = r.total_skus_distintos >= medianMix;

  if (altaPos && altoMix) q1.push(r);
  else if (altaPos && !altoMix) q2.push(r);
  else if (!altaPos && altoMix) q3.push(r);
  else q4.push(r);
});

const quadrantes = {
  Q1_Hunters_TopPerformers: {
    qtd: q1.length,
    pct: parseFloat(((q1.length / amostraValida.length) * 100).toFixed(1)),
    carteira_media: parseFloat((q1.reduce((a, b) => a + b.carteira_real, 0) / q1.length).toFixed(1)),
    taxa_pos_media: parseFloat((q1.reduce((a, b) => a + b.taxa_positivacao_carteira_pct, 0) / q1.length).toFixed(1)),
    skus_medios: parseFloat((q1.reduce((a, b) => a + b.total_skus_distintos, 0) / q1.length).toFixed(1)),
    ticket_medio: parseFloat((q1.reduce((a, b) => a + b.ticket_medio_real, 0) / q1.length).toFixed(2)),
    fat_total: parseFloat(q1.reduce((a, b) => a + b.faturamento_total_real, 0).toFixed(2))
  },
  Q2_Superficiais_BaixoMix: {
    qtd: q2.length,
    pct: parseFloat(((q2.length / amostraValida.length) * 100).toFixed(1)),
    carteira_media: parseFloat((q2.reduce((a, b) => a + b.carteira_real, 0) / q2.length).toFixed(1)),
    taxa_pos_media: parseFloat((q2.reduce((a, b) => a + b.taxa_positivacao_carteira_pct, 0) / q2.length).toFixed(1)),
    skus_medios: parseFloat((q2.reduce((a, b) => a + b.total_skus_distintos, 0) / q2.length).toFixed(1)),
    ticket_medio: parseFloat((q2.reduce((a, b) => a + b.ticket_medio_real, 0) / q2.length).toFixed(2)),
    fat_total: parseFloat(q2.reduce((a, b) => a + b.faturamento_total_real, 0).toFixed(2))
  },
  Q3_Atacadistas_Dispersos: {
    qtd: q3.length,
    pct: parseFloat(((q3.length / amostraValida.length) * 100).toFixed(1)),
    carteira_media: parseFloat((q3.reduce((a, b) => a + b.carteira_real, 0) / q3.length).toFixed(1)),
    taxa_pos_media: parseFloat((q3.reduce((a, b) => a + b.taxa_positivacao_carteira_pct, 0) / q3.length).toFixed(1)),
    skus_medios: parseFloat((q3.reduce((a, b) => a + b.total_skus_distintos, 0) / q3.length).toFixed(1)),
    ticket_medio: parseFloat((q3.reduce((a, b) => a + b.ticket_medio_real, 0) / q3.length).toFixed(2)),
    fat_total: parseFloat(q3.reduce((a, b) => a + b.faturamento_total_real, 0).toFixed(2))
  },
  Q4_ZonaCritica_Risco: {
    qtd: q4.length,
    pct: parseFloat(((q4.length / amostraValida.length) * 100).toFixed(1)),
    carteira_media: parseFloat((q4.reduce((a, b) => a + b.carteira_real, 0) / q4.length).toFixed(1)),
    taxa_pos_media: parseFloat((q4.reduce((a, b) => a + b.taxa_positivacao_carteira_pct, 0) / q4.length).toFixed(1)),
    skus_medios: parseFloat((q4.reduce((a, b) => a + b.total_skus_distintos, 0) / q4.length).toFixed(1)),
    ticket_medio: parseFloat((q4.reduce((a, b) => a + b.ticket_medio_real, 0) / q4.length).toFixed(2)),
    fat_total: parseFloat(q4.reduce((a, b) => a + b.faturamento_total_real, 0).toFixed(2))
  }
};

console.log('\n--- 4 QUADRANTES RECALCULADOS ---');
console.table(quadrantes);

// Salvar resultados consolidados
fs.writeFileSync(
  path.join(__dirname, 'analise_estatistica_recalculada_oficial.json'),
  JSON.stringify({ matrizCorrelacao, faixas, quadrantes, totalRCAsVJ: rcasVj.length, rcasDetalhe: rcasVj }, null, 2)
);

