const Database = require('better-sqlite3');
const path = require('path');
const fs = require('fs');

const dbPath = path.join(__dirname, '../analises/pedidos_historico_ceven.db');
const db = new Database(dbPath);

console.log('⏳ Extraindo dados para a Apresentação Web 3D...');

// 1. Carregar o Datalake Oficial
const datalake = JSON.parse(fs.readFileSync(path.join(__dirname, '../analises/DATALAKE_ESTATISTICO_INTEGRAL_NASA_MIT.json'), 'utf8'));

// 2. Extrair 4.000 pontos de clientes geoestatísticos (para o mapa de calor / partículas 3D)
const geoPoints = db.prepare(`
  SELECT 
    id_cliente, filial_sigla, latitude, longitude,
    CASE 
      WHEN dias_sem_compra < 30 THEN 'ativo'
      WHEN dias_sem_compra < 60 THEN 'alerta'
      ELSE 'critico'
    END as status,
    dias_sem_compra
  FROM clientes_completo
  WHERE latitude != 0 AND longitude != 0 AND latitude IS NOT NULL
    AND estado IN ('PR', 'RS', 'MS', 'MT', 'SP')
  ORDER BY RANDOM()
  LIMIT 4000
`).all();

// 3. Extrair dados de mix de alta performance vs baixo mix (para a Constelação 3D de Shannon)
const topMixRca = db.prepare(`
  SELECT i.codprod, i.descricao, SUM(i.valor_total) as total
  FROM pedidos_historico p
  JOIN pedidos_historico_itens i ON i.chave_pedido = p.chave AND i.tipo_registro = 'VENDA'
  WHERE p.rca_emissor_real = 268 AND p.status_pedido = 'FATURADO'
  GROUP BY i.codprod, i.descricao
  ORDER BY total DESC
  LIMIT 150
`).all();

const lowMixRca = db.prepare(`
  SELECT i.codprod, i.descricao, SUM(i.valor_total) as total
  FROM pedidos_historico p
  JOIN pedidos_historico_itens i ON i.chave_pedido = p.chave AND i.tipo_registro = 'VENDA'
  WHERE p.rca_emissor_real = 150 AND p.status_pedido = 'FATURADO'
  GROUP BY i.codprod, i.descricao
  ORDER BY total DESC
  LIMIT 20
`).all();

const payload = {
  filiais: datalake.nivel_filial,
  supervisores_top: datalake.nivel_supervisor.slice(0, 15),
  rcas_canibalizacao_top: datalake.nivel_rca.filter(r => r.adv_3_clis_fechamento_antecipado >= 40).sort((a, b) => b.adv_3_clis_bloqueados_setembro - a.adv_3_clis_bloqueados_setembro).slice(0, 15),
  geo_points: geoPoints,
  mix_hunter: topMixRca,
  mix_falso_varejo: lowMixRca,
  gerado_em: new Date().toISOString()
};

fs.writeFileSync(path.join(__dirname, 'dados_apresentacao_3d.js'), `window.TRIUNFANTE_DATA = ${JSON.stringify(payload)};`);
console.log('✅ Arquivo apresentacao_3d/dados_apresentacao_3d.js gerado com sucesso!');

const http = require('http');
const fs = require('fs');
const path = require('path');

const PORT = 3000;
const DIR = __dirname;

const mimeTypes = {
  '.html': 'text/html',
  '.js': 'text/javascript',
  '.css': 'text/css',
  '.json': 'application/json',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.svg': 'image/svg+xml'
};

const server = http.createServer((req, res) => {
  let filePath = path.join(DIR, req.url === '/' ? 'index.html' : req.url);
  const extname = String(path.extname(filePath)).toLowerCase();
  const contentType = mimeTypes[extname] || 'application/octet-stream';

  fs.readFile(filePath, (error, content) => {
    if (error) {
      if (error.code === 'ENOENT') {
        res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
        res.end('Arquivo não encontrado');
      } else {
        res.writeHead(500);
        res.end(`Erro no servidor: ${error.code}`);
      }
    } else {
      res.writeHead(200, { 
        'Content-Type': contentType,
        'Cache-Control': 'no-cache'
      });
      res.end(content, 'utf-8');
    }
  });
});

server.listen(PORT, () => {
  console.log(`🚀 Servidor da Apresentação Web 3D rodando em: http://localhost:${PORT}`);
});

